/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121010-4","meetingId":"h24-c-settlement","date":"2012年10月10日","dateIso":"2012-10-10","committee":"決算特別委員会","time":"午前１０時００分～午後５時１２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を161件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成２３年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開会いたします。 それでは、平成２３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"１７４ページの教育委員会費、それから、同じく１７４ページの教育指導費で、先日の第２回定例会であった、拉致についての教育についてお聞かせいただきたいと思います。教育委員会制度に関して、いろいろお伺いしたいことがあるんですけれども、昨今、多くの議論、提言がされております。","respondent":"齋藤庶務課長","answer":"教育委員会制度についてのご質問です。委員お話のとおり、過度に行政が教育にかかわることは危険であると、こういう認識のもとに教育制度の根本が成り立っております。区の場合は、区長、教育長とも十分にコミュニケーションを図っております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"区長と教育長の関係は、今、お話をいただいたんですが、教育長と教育委員長というか、教育委員会のメンバーの中に教育長が入っているかと思うんですけれども、教育委員長と教育長の関係というのは、どうなっていますか。","respondent":"齋藤庶務課長","answer":"教育長は教育委員のメンバーです。組織の成り立ちは、教育委員長が組織体の運営を、一義的に責任を負っております。ただ、教育長は事務局の長ですので、具体的な教育行政についての中身についてご説明をし、委員会として果たすべき議決、案件について、十分な説明をしています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"具体的に品川区が進めてきたプラン２１とか、そういった政策を策定していく中で、教育委員会が果たしてきた役割というか、どのような議論がなされたのか。今回、そういった具体的ないろいろな事例がありましたけれども、そのあたりで、教育委員会の中でどういった話がされてきたのかということを、わかる範囲で少しお聞かせいただければと思います。","respondent":"齋藤庶務課長","answer":"これは私も議事録をいろいろ見せてもらいましたけれども、率直なご意見をいただきました。反対の方もいらっしゃいました。そういったことも含めてオープンにしながら、開かれた学校づくりを教育委員会事務局が推進するということで、委員会運営に努めてきたところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"その再質問で、３分の１との答弁がありましたけれども、３分の１の学校ということで、こういった事件が歴史的に実際にあったという事実として、二度と起こしてはいけない、起こってはいけないという観点から、全ての学校の授業で必ず扱うようにしていただきたいと思っているのですが、実際に扱っている校数、そして、何年生で扱っているのかということと、今後についてお聞かせいただければと思います。","respondent":"太田指導課長","answer":"現在、その扱っている学校数というと、ちょっと正確な数字は手元にないのですが、１５校程度というところでは、状況を捉えて把握しております。いずれにしましても、この問題につきましては、小中一貫教育要領に基づいて、しっかり子どもたちにも指導していきたいと考えています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"ほんとうに、こういったことは絶対に起こしてはいけないし、こういうことが起こされたという事実のもとに、こういった映像を見ることによって、この悲劇を繰り返さないということで、子どもたちにそれをわかっていただく、そして、必ず救出していただかなくてはいけないということを、子どもたちにも、こういうことがあったという事実を理解したうえで、そういう思いを持ってもらうということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"私からは、１７４ページ、教育指導費、いわゆるいじめについてが一つ。それから、１７７ページの特別支援教育費について、伺いたいと思います。この大きな非を招いている大津市の事例を紹介しながら、今後の品川区の対応などについて見解を伺いたいと思います。それから、２月２４日、大津市、そして加害者側の生徒３人、またその保護者を相手どり、約７,７００万円の損害賠償を求める訴訟を起こしました。","respondent":"太田指導課長","answer":"その対応についての率直な見解を、ですけれども、大津市の対応について、私どもが、それをこうだったのではないかというような見解というよりも、今回、私どもは、決算特別委員会の冒頭で、教育長も申し上げたように、まず対応の第一として、ご遺族のお気持ちに沿った形で調査。","voiceIndex":14,"id":"exchange-006"},{"speaker":"若林委員","kind":"提案","question":"述べるというのは、また文書での提出と、いわゆる開陳ということだと思います。直近の任命同意では平成２４年第２回定例会で、区長から、このような説明がありました。改めて、この教育行政に何らかの形で、また任命同意という大きな形で携わっている者として、一つは教育委員の任命同意について、いわゆる所見を開陳するという工夫を、ぜひしていただきたいと思いますけれども、ご見解を伺いたいと思います。","respondent":"濱野区長","answer":"教育委員の任命同意についての、一つのご提案です。検討させていただきたいと存じます。若干のお時間をいただきたいと思います。","voiceIndex":16,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"１７４ページ、委員報酬、１７７ページ、すまいるスクール運営費、１７８ページ、図書館経費についてお伺いします。学校の先生が、今置かれている状況というのは、とても忙しくて、厳しい状況の中で、授業のほうに専念していただきたいという思いがあるので、この変更は、私は、いいと思っているんです、放課後の対策ですから。その状況について、お伺いします。","respondent":"齋藤庶務課長、安井子育て支援課長、中元品川図書館長","answer":"委員の皆様にご意見をいただいて、充実した形で教科書の採択ができたと考えております。子どもについての情報の共有、特に気になるような子どもについては、担任、あるいは校長先生に必ず連絡を入れていくということと。私のほうから、図書館のクレーマーが多い状況を、お答えいたします。","voiceIndex":20,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこはやはり、職員の皆様を、体制として守っていかないといけないと思うので、そこも考えてこれからもやっていっていただきたいと思います。そんな中で、今、どういうふうなことをして、主な議題は、というので、出てきたものを処理しているとしか感じないんですけれども、区民の声をどう教育委員会の方たちが教育の場において反映しているのか。その辺について、お伺いします。","respondent":"齋藤庶務課長","answer":"これをまた、教育委員の皆様にご報告して、教育委員会の中でも議論をしている。今後、いただいた意見につきましては、施策の中で活かしていきたいと考えております。","voiceIndex":24,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"回数にしてもそうですけれども、月額の報酬も結構いただいているではないですか。これはまだ、橋下市長の考えみたいに、廃止だとか、そういう意味ではなくて、何かよくわからないという思いが出るので、その辺について、これこれこうだから、教育委員会の制度が、区の教育の施策に対して、これだけ有効なんだということを、もうちょっと詳しくといいますか、教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"そういった方も現場に行って、校長先生のお話を聞いていただきながら、地域の声を十分に反映できる人選になっていると考えております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"藤原委員","kind":"意見","question":"担当としては、継続していきたいと思っていると思うんですけれども、最後に、今後のあり方について、どう考えているのか、お尋ねします。","respondent":"齋藤庶務課長","answer":"教育委員会制度、現在の制度もうまく活用すると、十分に地域の声は図っていけます。教員のプロである教育長を先頭に、これからも教育委員会、区長部局と連携しながら事業を推進していきたいと思います。","voiceIndex":28,"id":"exchange-011"},{"speaker":"木村委員","kind":"質問","question":"１８２ページの中ほど、教育振興費からの質問です。就学援助費、小学校が２億４,４４５万円余、中学校が１億９,９１７万円余が区分けされていますが、この事業を、簡単にご説明お願いします。","respondent":"和氣学務課長","answer":"私から、就学援助の制度全般についてというご質問にお答えいたします。","voiceIndex":31,"id":"exchange-012"},{"speaker":"木村委員","kind":"質問","question":"一人ひとりの児童・生徒、小学校とか中学校という形で書いてありますけれども、該当する項目には、全て受けることができるのでしょうか。そして、生活費に少し困窮をしているご家庭の子どもたちですが、生活保護受給者とは、どのように違うのでしょうか。１３項目の中で、どのようにして、この生徒にはこの項目、そしてこの生徒にはこの項目と決めるのでしょうか、お聞かせください。","respondent":"和氣学務課長","answer":"項目をご覧いただいて、例としましては、上から６行目の移動教室費というのがあります。これは、移動教室に参加する学年が受け取るものです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"木村委員","kind":"質問・要望","question":"これは、指導者がいる区内の各中学校が、指導者のいない中学校に対して呼びかけをするとのことですが、今現在、区内で合同部活動を行っている学校は何校あり、どのような部活が行われているのでしょうか。そして、この合同部活動は、区内だけで行われているのか、他区との合同部活動は前例がないのでしょうか。将来的にも、このようなことは絶対にあり得ないのか、教えていただきたいと思います。","respondent":"和氣学務課長、太田指導課長","answer":"数等については、私のほうからお答えします。合同部活動は、今、５校でやってあります。戸越台中学校、八潮学園、荏原第一中学校、大崎中学校、伊藤学園、それぞれバレーであるとか、バドミントン、柔道等でやってあります。今後の予定も、特にございません。合同部活動については、どの項目に入っているかというご質問ですけれども、項目は１７６ページの合同部活動実施経費です。","voiceIndex":35,"id":"exchange-014"},{"speaker":"木村委員","kind":"質問・要望","question":"ほとんどのスポーツが入っているということでありますけれども、大変すばらしいことだと思いますので、これからも続けていただきたいと思います。戸越台中学校と八潮学園などが行っているという話を聞きました。６年に一度異動があるということを聞きましたけれども、どのような形になっても、これからこういうことはずっと続けていくお考えでしょうか、お聞かせください。","respondent":"太田指導課長","answer":"今後も続けてまいりたいと考えております。","voiceIndex":38,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問","question":"休廃部防止外部指導員からの質問です。これは教育資格がある方に限るのか、それとも、資格がなくても、競技に優れていれば指導員になることができるのでしょうか。そして、外部指導員を探すのは、学校側なのか、それとも区教育委員会なのか、それとも、東京都でしょうか、お聞かせください。そして、実際に品川区では、どの学校が行っているのでしょうか。","respondent":"和氣学務課長","answer":"基本的に、学校に探していただきます。お金は、私どもが払うという形になります。実際にやっている学校は４校ございまして、内容としては、吹奏楽、それから伝統文化、水泳、ソフトテニス、剣道、バレーボールということで、６名にお願いをしています。","voiceIndex":40,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"そして小中合同部活動というのがあるとお聞きしますが、この項目は、どこに入っているのでしょうか。ちょっと探し切れないので。そして、この事業もやはり、指導者がいない小学校に対して呼びかけるのでしょうか。この事業の狙いというものがありましたら、お聞かせください。","respondent":"和氣学務課長、太田指導課長","answer":"項目としましては、１７６ページの真ん中あたりの合同部活動実施経費に入ってあります。指導者については、先ほどちょっと答弁漏れでしたが、免許は要りません。やっていただける方であれば、採用をして、お願いをしています。狙いですけれども、小学生は中学校生活に慣れるということ、それから、中学生は小学校に教えることで、上級生である自覚を深めるというようなことを狙いといたしまして、そのことで小中一貫教育を推進しております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"中学生が小学生を教える、また、小学生が中学校に慣れるということも、大変大事なことだと思っています。小学校５、６年生の生徒が中学校の部活に参加するんですが、小学校と中学生は少しレベルが違い過ぎるような気がするんですけれども、もしよろしければ、お答えください。","respondent":"太田指導課長","answer":"個々によって、体格とかそういうものは違いますけれども、今、発達段階を考慮いたしまして、５年生以上を対象としています。","voiceIndex":45,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"同じページの下のほうの、ものづくり教育推進事業からの質問ですが、産業技術高等専門学校が、八潮学園の生徒に対して、ものづくりを教えている実例があるお聞きしました。ソニー財団からも、中学生を対象にロボットづくりの授業を行っているとのことですが、どのような目的を持ってこの授業があるのか、児童・生徒が、両企業から受ける影響力や成果のほどはいかがでしょうか、お聞かせください。","respondent":"太田指導課長","answer":"成果といたしましては、子どもたちの中にも、つくる喜びを感じたとか、達成感を感じたというような感想を持つ子どもも非常に多いと聞いております。ソニー財団の取り組みですけれども、こちらも同様の取り組みをしています。","voiceIndex":47,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"品川区には、市民科、そしてまちの人々に学ぶ授業など、品川区独自の授業、教育方法がありますけれども、この品川区は、ほかの全国平均を超える学習能力を持っている。ですから、あとは時間の関係もあるでしょうけれども、少しでも多くの、そういう心の授業、そして、頭脳と心身がともに成長できるように取り計らっていただきたいです。これは要望として収めておきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１７５ページ、プラン２１推進事業に係わって、品川区における小・中学校のいじめ克服、子どもの命が守れる学校づくりを求めて質問したいと思います。それからもう１点、区教育委員会が発表するいじめの件数ですが、いじめと判断する根拠、基準は何か、具体的にアンケートにどのように記入されているといじめと判断、報告を求めているのか、ご説明いただきたいと思います。","respondent":"太田指導課長","answer":"ただ、いじめかどうかということよりも、そこに困っている子どもがいるとすれば、救わなければいけないというところで、学校にも、対応できるようにということで指導しています。","voiceIndex":51,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"こうしたプロセスについての研究を、品川区の教育改革に位置づけて教育研修を実践すべきではでしょうか。改めて伺いたいと思います。それとも、どの学校のどの子なのか、またどの学校に事例が多いのか、少ないのか、傾向はどうなのか、そういったことまで把握されているのでしょうか。ここで把握している件数の中に、子どもの死亡へと至ってしまったケースはあるのでしょうか、伺いたいと思います。","respondent":"太田指導課長","answer":"いじめの進行による対応ですけれども、知見については、参考にします。いじめの報告につきましては、ただ数字を挙げさせるだけではなく、その数字について、指導主事が学校に折り返し聞き取りを行うなど、その内容についても、把握するように努めております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"既に件数として報告されている中に、子どもの死亡へと至ってしまったケースはあるのか、そこを伺いたいと思います。教育長は、各学校長に、７月上旬に緊急のアンケートを行っております。その予兆がつかめていなかったのであれば、何が問題だったのか。残念ながら、区教育委員会は、子どもの命が奪われてから、その子どもの過去の実態把握に努めたというのがこの経過なんでしょうか、伺いたいと思います。","respondent":"太田指導課長","answer":"２月の件につきましては、事前には、そういった兆候をつかめなかったですが、兆候はなかったです。そして、先ほど、お話があったように、過去に死につながった件はございません。","voiceIndex":55,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"そこに問題として何が残っているのか、どうこれを解決していかなければならないのか、ここは問われることだと思います。率直な見解を伺いたいと思います。子どもの命は、何よりも重いものです。過去２件の子どもの死亡について、なぜ調査委員会を立ち上げなかったのか、その理由を伺います。今からでも、再検証を行うべきだと思いますが、いかがでしょうか。","respondent":"太田指導課長","answer":"予兆をつかむことができなかった、それに対する対応、対策ですけれども、いじめについての対応につきましては、教員がいじめの兆候を見抜く目を持つということが大切だと考えております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"教員のコミュニケーションのことを話しておりました。２月、７月の、区教育委員会が事故と発表した件につきまして、私は、なぜ調査委員会を立ち上げなかったのかと伺いました。その事情をご説明いただきたいと思います。ぜひ、この３件についての真相を明らかにし、今後のいじめ克服、子どもの命が守られる学校づくりへとつなげていただきたいと思いますが、いかがでしょうか。","respondent":"田村教育次長","answer":"ここで、その話を蒸し返してやられても、今回のケースはいじめに関する可能性が強いというお話をしていますが、前の２件については遺族の意向を全く無視して、調査委員会を立ち上げて、１件は事故として扱ってほしいという遺族の強い意向ですし、もう一つは。","voiceIndex":59,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、子どもの命が奪われた、この事態は重要だと思います。なぜその予兆を事前につかむことができなかったのか、結果として、つかむことができなければ、何が足りなかったのか、真摯に向き合い努力を重ねていく、そうした学校づくり、地域づくりが欠かせないと思います。今後の方向について、ご説明いただきたいと思います。","respondent":"田村教育次長","answer":"手引書をご覧になるとわかりますけれども、先ほど来、ご質問にあるように、子どもが自分で自己申告しない限り、いじめを書くのにも勇気が要るのではないかという話ですけれども、まさに、手引書の６ページを見ていただければわかるように、学級担任が、早期発見で遅刻、欠席なり。","voiceIndex":61,"id":"exchange-026"},{"speaker":"山内委員","kind":"質問","question":"１８３ページの学校保健費の中で、歯磨き指導法研究委託のこと、それから、１７４ページの教育指導費の中で、進学校と特進クラスについて、それから、時間があれば、区の独自教員について、伺いたいと思います。１８３ページの歯磨きなんですが、この４０万円の決算額の内訳を伺います。先日、我が会派と学校歯科医師会の方々と、ちょっと話をする機会がありました。","respondent":"和氣学務課長","answer":"それなので、なかなか一気に全校で、ということにならないので、今、一つ一つ実験をしながら、どううまく定着させていくかということで努めているところです。","voiceIndex":64,"id":"exchange-027"},{"speaker":"山内委員","kind":"質問・要望","question":"少し進学校の考えを伺いたいと思います。そういった中で、いろいろ区内の小学校は特色があるかと思います。そういった意味で、これは公立の学校なので、そういう位置づけというのは、ちょっと難しいかなとは思うんですけれども、進学校というような、こういう言い方が適切なのかどうかわかりませんけれども、そういった考えはあるのかということを、伺いたいと思います。","respondent":"太田指導課長","answer":"まず第一に、私立の中学校に負けない学校づくりを、プラン２１を通して進めているところですので、そのようにご理解いただければと思います。","voiceIndex":66,"id":"exchange-028"},{"speaker":"山内委員","kind":"質問・要望","question":"今、特進クラスという答弁がありましたけれども、そこも伺いたいと思ったんですが、子どもには、いろいろなレベルがあろうかと思います。ですから、簡単に答弁で、考えていないというのではなくて、私は、そういう答えを求めているのではないんですよ。どういう形で、そういう子どもたちのニーズにこたえていくかということを、今この場で聞いているので、そのあたりの答弁をいただきたいと思います。","respondent":"太田指導課長","answer":"中には国語はできないけれども、算数はすごく得意だとかいう子であれば、算数の教科では習熟度の高いクラスで、ほかの子たちと競い合う、そういったような場が、今学校の中でもありますので、そこを充実させていきたいと、そういう思いです。","voiceIndex":68,"id":"exchange-029"},{"speaker":"山内委員","kind":"質問","question":"区の独自採用教員を平成２１年度から始めて、もうかれこれ３年たちましたけれども、まず、教員の延べ人数と、この品川区の風土に合わずに、残念ながらおやめになられた方もいらっしゃるのかなと思いますが、そのあたりを伺いたいと思います。そういう中で、とにかくいろいろな方がいると思います。そういう意味で、この辺を伺いたい。今後の独自教員の採用の仕方というものを伺いたいと思います。","respondent":"太田指導課長","answer":"教科指導はもちろんそうですけれども、私たちが申し上げているのは、区長もおっしゃっていますけれども、区教員を子どもたちにとって生涯の先生という位置づけで、東京都の教員は、大体６年ぐらいで外に出てしまいますけれども、子どもたちの成長とともに。","voiceIndex":70,"id":"exchange-030"},{"speaker":"山内委員","kind":"質問・要望","question":"やめられた方はいない、これはやはり品川区の教育のあり方と先生方がうまく合致しているのかなと思います。最後に一つだけ、要望させてください。私、最近の子どもは競争心がないと思うんです。その競争心をしっかりと高めていただけるような、そういった教育をぜひともお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-031"},{"speaker":"鶴委員","kind":"質問","question":"私からは、１７４ページの教育費全般というところと、あとは時間が残れば、個別に図書館経費、お伺いしたいと思います。子どもたちの確かな学力と豊かな社会性、人間性の育成を目指して策定されたのが、品川区の教育改革プラン２１であると思います。冒頭、品川区が目指す児童・生徒像、これはどういうものなのか、簡潔に教えてください。","respondent":"太田指導課長","answer":"教育目標の三つ目には、学校・家庭・地域社会が、教育の担い手としてそれぞれの役割と責任を果たし、相互補完しながら青少年の健全育成に努める。","voiceIndex":74,"id":"exchange-032"},{"speaker":"鶴委員","kind":"質問・要望","question":"今、教育目標から４点、掲げていただきました。当然、公開講座ですから、おすましした姿かなという部分もあるかなと思ったんですけれども、子どもの姿を見れば、それがうそではない、本来の姿なんだなと、ふだんから先生がこうやって接してくれているのではないかと、そういうふうに思いました。","respondent":"太田指導課長","answer":"もちろん教員にも、勤務時間と休憩時間等の制限もありますけれども、その勤務時間を割り振りまして、昼休み、それから休み時間等は教員にとって、子どもの様子を観察することの大切な役割として対応しています。","voiceIndex":76,"id":"exchange-033"},{"speaker":"鶴委員","kind":"質問・要望","question":"子どもたちのメディアから受ける影響について確認したいんですが、文部科学省の、平成２０年度で、これは最新かどうかあれなんですけれども、全国学力・学習状況調査を見たところ、保護者たちの声ということなんですが、テレビ等から悪い影響を受けるというのが５０％になっていて、もちろんいい影響もあると思うんですけれども、こうした数字について、品川区でも同様の影響が見られるのかどうか。","respondent":"太田指導課長","answer":"ただ、それに対する取り組みとして、例えばノーテレビ、ノーゲームデイとか、そういったような対策とか、あとは学校では、必要な情報がどういう情報なのかという情報モラルの教育とか、そういったことも全て総合して指導いたしまして。","voiceIndex":78,"id":"exchange-034"},{"speaker":"鶴委員","kind":"質問","question":"ノーテレビ、ノーゲームとありましたけれども、子どもたちの今現在の楽しみを、あまり奪い過ぎてもあれかなと思いますけれども。そういう点から、こうしたメディアで活躍している、特に子どもたちが影響を受けやすい芸人の方に講師になってもらって、児童とか生徒にわかりやすく、メディアの世界と現実の世界を明確するとか、そうした講演会を開いては、と思いますけれども、いかがでしょうか。","respondent":"太田指導課長","answer":"委員おっしゃるように、子どもたちにそういったテレビに出ている方々の影響というのは、非常に大きいと思います。そういった意味では、いい意味での影響ということを考えますと、委員のご意見も、今後参考にさせていただきたいと考えています。","voiceIndex":80,"id":"exchange-035"},{"speaker":"鶴委員","kind":"提案","question":"その際には、また言っていただければ、しっかりお話をつなげていきたいと思います。さまざま提案させていただきました。まさに、子どもにとって教師こそが最大の教育環境、このように考えてありますので、教育委員会、また現場の先生が一丸となって、児童・生徒のためのプラン２１を、どうか今後とも鋭意推進をしていただきたいと思います。残った時間で、図書館経費にいきたいと思います。","respondent":"中元品川図書館長","answer":"カセットテープのほうですが、主に音楽カセットです。それから、映像資料のほうでは、一部映画とかそのほかの地域資料的なビデオ等もあります。","voiceIndex":82,"id":"exchange-036"},{"speaker":"鶴委員","kind":"質問","question":"私の聞き方がおかしくて、すみません。ＣＤとかよりは劣化が早いのではないかという意味で、ＤＶＤとか、ＣＤとか、そうしたものにデジタル化させて保存をするというような形にして、公共財産の適切な管理ということについては、されているのかどうか、もしされていなければ、ぜひやったらどうかと思いますけれども、いかがでしょうか。","respondent":"中元品川図書館長","answer":"品川区立図書館として取り組むべきことは、やはり地域の歴史的音源、お神楽などを、今後、どのようにデジタル化して保存していくかだと思います。そちらのほうについては、今後の研究課題とさせていただきたいと存じております。","voiceIndex":84,"id":"exchange-037"},{"speaker":"鶴委員","kind":"質問・要望","question":"だけれども、何となく昔の曲を聞きたいとか、そうしたこともあると思うので、そういう保存方法をしっかりと工夫していただいて、幅広い世代の方が、昔の曲とか、昔の映像とかに親しめるような整備も、ぜひ進めていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-038"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は、１８３ページの学校保健費に関連して、小学校のインフルエンザ流行時の対策について、お伺いいたします。インフルエンザ流行時に行われる学校における学級閉鎖、学年閉鎖、学校閉鎖など、臨時休業について、これは誰の権限で行われるものなのか、おおよそ何を目安に実施されているのか、この２点を、まずお伺いしたいと思います。","respondent":"和氣学務課長","answer":"学校長が判断するものですが、私どもと協議をしたうえで、罹患の状況、何名罹患をし、前日から当日からどのように増えているのか、それを考えていただいて、クラスの何％ということで、５名程度ということです。","voiceIndex":88,"id":"exchange-039"},{"speaker":"鈴木（博）委員","kind":"意見","question":"５名程度、大体１０％相当というふうに考えていいのかと、今ちょっと感じたんですが。次に、平成２４年４月２日に学校保健安全法施行規則が一部改正されまして、第二種感染症であるインフルエンザの出席停止期間が変更になりました。これは、どのように変更になったのか、ご説明をお願いいたします。","respondent":"和氣学務課長","answer":"５日というふうに考えているんですが、完全に治癒をしたと医者に言われて、熱が下がってから３日間と思います。","voiceIndex":90,"id":"exchange-040"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これに関しまして、インフルエンザ対策の中心になりますインフルエンザのワクチンに関してですが、学校現場で、インフルエンザワクチンの啓発は、現在、どのように行われているのでしょうか。それから、学校での流行は、しばしば教職員から生徒に感染が広がりますが、教職員のインフルエンザワクチンの接種について、現在、どのような体制が組まれているのでしょうか、お伺いいたします。","respondent":"和氣学務課長","answer":"保護者に対しては、最新のワクチンの情報について流して、事前に悪化する前にぜひワクチンを接種するようにお願いしているのと、教員については、基本的に義務として、全員接種をするようにということで、私どもは指導しています。","voiceIndex":92,"id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"確認","question":"次にまいります。したがって、インフルエンザでないことを確認するために、病院に行って検査をするよう、学校が生徒に、あるいは保護者に指導するということは、１回２,９４０円費用がかかりますし、この貴重な医療費と検査キットの浪費以外何物でもなく、全く意味がないのではないかと思います。このような学校の対応に対して、区の見解をお伺いしたいと思います。","respondent":"和氣学務課長","answer":"基本的に、かかったうえで、出席停止を解除するときに、たまにまだはっきりわからないことで、検査をして医者の証明を持ってくる保護者がいらっしゃいますけれども、基本的に、私どもで。","voiceIndex":94,"id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほど、お話ししたように、特に陰性の検査というのは全く意味がないものなので、小学校、保育園、それから幼稚園等で、保護者にも余分な負担がかかりますので、ぜひ徹底的に、不必要な検査をしないということのご指導をよろしくお願いしたいたいと思いまして、私の質問を終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-043"},{"speaker":"向委員","kind":"質問","question":"私からは、まず、成果報告書の１７４ページ、教職員研修に関連してになるかと思います、もしかしたら１８２ページ、防災ヘルメット購入にも若干かかわってくるかとも思うけれども、このあたりで。品川区の先生方の正規というか、常勤の先生と、非常勤と申し上げていいのでしょうか、毎日ではなく、短時間とか、いろいろな職種の方がいらっしゃると思うんですが、非常勤の先生方は、どんな形態があるのか。","respondent":"太田指導課長","answer":"何％かというのは、２３％です。","voiceIndex":98,"id":"exchange-044"},{"speaker":"向委員","kind":"質問","question":"今回、お伺いしたかったのが、この１年とか、被災地の視察とかも行って、学校が発災したときに、学校に残った先生方が避難所の運営とかですごく力になったというお話を、いろいろなところで伺ってきました。具体的なそういった先生方の動き方とか、マニュアル的なものは、今回の震災後とかに、見直しとかされたのでしょうか。","respondent":"鈴木防災課長","answer":"震災後の見直しに関してですが、ご存じのように、現在、地域防災計画、区の防災計画の見直しをしておりますので、その中で、避難所に関する分科会の設置をいたしまして、教育委員会とも連携をして検討をしている最中ですので、計画の中で。","voiceIndex":100,"id":"exchange-045"},{"speaker":"向委員","kind":"質問・要望","question":"おそらく、先生方からも、発災のときに、やはりこうするべきだったとかいういろいろな声が挙がってきていると思いますので、教育委員会と連携してまとめていっていただきたいと思います。続きまして、１７６ページ、熱中症指数モニター購入、３１１万円ぐらい、決算に載っていますけれども、この内訳を教えてください。","respondent":"和氣学務課長","answer":"熱中症モニターに対するお尋ねですが、これは各学校、５６１台を全てで配ってあります。","voiceIndex":102,"id":"exchange-046"},{"speaker":"向委員","kind":"質問","question":"大体１校に必ず最低１台はあるということで、よろしいのでしょうか。それから、１台当りの価格というか、製品の詳細、どれぐらいの大きさとか、持ち運びができるものなのかとか、先生方は、教室だったり、例えば体育館とか、持ち運びがどんどんできるようなものなのか、そこら辺を簡単に教えてください。","respondent":"和氣学務課長","answer":"価格は、最初に買ったときは６,０００円ぐらいだったんですが、２回目買ったときは、量が多かったので５,０００円ぐらいで買えるものです。大きさは、大体、２０cm角ぐらいでございましょうか、持ち運びは十分にできますし、壁につるすこともできます。","voiceIndex":104,"id":"exchange-047"},{"speaker":"向委員","kind":"質問","question":"聞いたところによると、多分日本製ではなくて、中国製みたいなことも伺ってはいるんですが、ＪＩＳの規格とか、そういった精度のところはどうなんでしょうか。今、多分、熱中症の指数のモニターの機械というのは、ピンからキリまでと申し上げるとあれなんでしょうけれども、やはり精度の問題というのは、ある程度きちんと見ていかないといけないのかなと思っています。","respondent":"和氣学務課長","answer":"学校は、これを使いながら、今の状況、そしてまた節電をして、みんなぎりぎり我慢するわけですが、警報が鳴ったりしますから、そのときにしっかりと水分を取らないといけないとか、運動をやめるとか、屋外での運動をやめるとか、そういうことを身をもって体験をする。","voiceIndex":106,"id":"exchange-048"},{"speaker":"向委員","kind":"質問","question":"わかりました。品川区内で、熱中症で病院に搬送されたとか、いろいろ報告というのは、１件、２件とか挙がっているものなんでしょうか。それとも全く挙がっていないのでしょうか、教えてください。","respondent":"和氣学務課長","answer":"残念ながら、１件挙がっております。１件だけですが、６年生の女の子が、体育の授業の後、１時間ぐらいして少し気持ちが悪くなって病院にかかったということで、その際、脱水症という診断だったんですけれども、熱中症の疑いもあるということで、１件把握しています。","voiceIndex":108,"id":"exchange-049"},{"speaker":"向委員","kind":"質問","question":"わかりました。品川区の教育委員会としては、そういった報告を受けて、カウントをする基準というのは、基本的に病院に行ってからということでよろしいでしょうか。保健室にただ寝ている方、ぐあいが悪くなったとか、いろいろケースがあると思うんです。","respondent":"和氣学務課長","answer":"基本的に、病院に行くに至るまでの症状が出たという方で、ちょっと暑くてつらいというので休んだ程度はカウントはしてございません。明らかに病院に行かなければならないという程度については、私どももしっかり掌握をしています。","voiceIndex":110,"id":"exchange-050"},{"speaker":"向委員","kind":"質問","question":"わかりました。資格を持った方、そうでない方、ボランティアの方とかいらっしゃるのかなという話を伺っているんですが、配置の数とか、勤務時間とか、有資格者がきちんといらっしゃるようであれば、有資格者を置くにあたってのきちんとした考え、どういった考えをもとに配置しているのかを教えてください。","respondent":"中元品川図書館長","answer":"人数につきましては、各学校お一人で、日数といたしましては、週に２日半という形で、基本的に仕様書に書かせていただいております。実際のところは、各学校の行事とか方針で、２日半というところを週によって調整されて使っていただいているところです。","voiceIndex":112,"id":"exchange-051"},{"speaker":"向委員","kind":"質問・要望","question":"時間もあと１分なので、今、情報をいかに調べて自分で精査していくかというのも、子どもたちにもすごく求められている時代になっていると思います。これは、別の機会にお尋ねしたいと思いますが、どうぞ今後ともよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"１７６ページ、学力テスト実施費、１７７ページ、学力向上プラン推進事業を中心に伺っていきます。学力テストですが、地域の声の中で、学力テスト、一つの目標であり、家庭にすれば、自分の子どもがどうなのか、とても関心事だと思います。そのような分析の仕方、学力テストをやってみて、それをどう活かしていくか。最初に目標設定と、そしてその後の活用の仕方について、お知らせください。","respondent":"太田指導課長","answer":"各学校がその結果をもとに、保護者や地域の方、区民の方に説明責任を果たすというようなところで、学校の様子を外に知らせる一つの材料ということもあります。今、ちょっと目標と活用が混同してしまいましたけれども、そのような形で、その各学力調査を活用しています。","voiceIndex":117,"id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、究極は、よく学校別の公表なんていうところもあるかと思いますが、この辺のめり張りというのは必要だと思いますが、その点はどうお考えかを、まず１点目。３点目で、さっき学校の傾向という中で、学校単位での差というか、地域差というのですか、昔から地域性ってあると思うんです。その辺の地域性の考慮なんかはあるものなのか、どうか、ちょっと伺ってみたいと思いました。","respondent":"太田指導課長","answer":"数値だけが並ぶということでは、なかなかわかりにくいところを、言葉で説明をするというところでの部分では、多少おわかりいただきやすくなっているのではないかなと思います。","voiceIndex":119,"id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問","question":"これは地域の方も、すごく理解しているし、保護者もすごく理解している。その中で、今、区のテストが４年生なり、７年生であると。全国も６年生、９年生にある。この合間の過ごし方というのですか、例えば４年生のときにテストをしました。この子たちが５年生になるまでの１年間だったら１年間はとても大事だと思うんです。極論を言えば、もう１回、１年後にやったときに、どう伸びているのか。","respondent":"太田指導課長","answer":"学力調査を４年生でする、７年生でする、その後の伸びしろですけれども、それは、それぞれ４年生、７年生で調査をした、そこで出た結果について、各学校では重点的に取り組んだりするわけで、各学校ごとに図っているということが一つと、あとは東京都の調査が５年生、８年生。","voiceIndex":121,"id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問","question":"学力向上プラン推進事業ということで、ちょうどこの年度で、日野学園の８年生ですか、勉強合宿をなされているかと思います。いろいろな注目があったと思いますが、決算を迎えての効果検証、どのような効果があったのか。そういう中で、今後、どう展開されているのか、この日野学園のケースはモデルなのか、あるいは、特色のある一つの形なのか、その辺の性格を教えてください。","respondent":"太田指導課長","answer":"今回の日野学園の勉強合宿ですけれども、８年生を対象としまして勉強の合宿を行って、主には勉強の仕方、そういったものを学ぶというところで実施しています。このためには、学校の教員もその合宿に参加しておりますし、そのための指導助手も、その予算で配置しています。","voiceIndex":123,"id":"exchange-056"},{"speaker":"渡辺委員","kind":"質問","question":"最後に、学力というのは一つの方法であり、一つの項目だと思っています。先ほど、私どもの山内委員のほうからも指摘がありましたが、競争というのは、私もすごく関心のあるところです。その中の一つの軸が学力であるとも思いますし、そのほかの集団生活だと思いますが、競争というのをキーワードに、さまざまなところにも共通するかと思うので、その辺の考え方を一つ、最後に教えてください。","respondent":"太田指導課長","answer":"学校の教育場面の中で、そういったような機会、全部が全部ということではなくて、それが子どもたちにとって資するものというところで、そういったような競争ということもしっかり意識をして、教育を進めていきたいと考えています。","voiceIndex":125,"id":"exchange-057"},{"speaker":"阿久津委員","kind":"提案","question":"私からは、１７８ページ、トイレ改修工事費、小学校１校と、あとは教育費全体になるのでしょうか、それとも教育指導費になるのでしょうか、いわゆるいじめの問題について、質問します。その点、どのような経過があったのか、教えていただければと思います。","respondent":"齋藤庶務課長","answer":"絵を書きたいという児童の希望があれば、それに沿った形で予算措置もするということで、学校にはお話をしております。学校生活を営む場で、トイレが大変重要な場所だということも含めて、学校にお伝えしています。","voiceIndex":128,"id":"exchange-058"},{"speaker":"阿久津委員","kind":"質問","question":"和式便器から洋式便器へというのは、いかがでしょうか。","respondent":"齋藤庶務課長","answer":"答弁漏れをいたしました。和式は一つ残します。それ以外は洋式ということで、今年度も、浅間台小学校、京陽小学校と設計をしております。","voiceIndex":130,"id":"exchange-059"},{"speaker":"阿久津委員","kind":"質問・要望","question":"そこでちょっとお伺いをしたいんですけれども、先ほどもほかの委員からも説明があったんですが、いじめへの対応、いじめへの気づきということで、教職員の方は一番身近にいらっしゃるということで、敏感力、特に学校や教職員の方の対処の仕方、行動力が非常に重要だと思うんですが、そういういじめる側の心理とか、いじめられる側の心理、そういう児童心理学等でやるのかもしれませんが、現在、教員の中で。","respondent":"太田指導課長","answer":"各学校には、スクールカウンセラー等も配置しておりますので、情報交換する中で、教員のほうが気づかないような見方とか、そういったことを知るとか、また逆に、保護者からご相談があった際に、改めてそこの視点で子どもに向き合うというようなところで。","voiceIndex":132,"id":"exchange-060"},{"speaker":"阿久津委員","kind":"確認","question":"これは、ちょっと素朴な疑問でお伺いしたいんですが、私も何度も読んだんですけれども、例えば遅刻、欠席が増えるとか、出席確認の際、声が小さいとか、いわゆるいじめを受けているのか、受けていないのか、気づきというか、そこから判断をしていく、推測ができると、そういう項目もあるんですけれども、例えば、椅子や机が壊されたり、所持品や机などに落書きされるとか、特定の子の運動着が破られたり。","respondent":"太田指導課長","answer":"そういった中で、特に明らかに椅子や机を壊されたり、所持品や机などに落書きされるであるとか、委員先ほどおっしゃったように、ばいきん、○○菌などの嫌がるあだ名をつけて呼ぶというような項目はまさにこれはもういじめですけれども。","voiceIndex":134,"id":"exchange-061"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私も何度も読み返しております。正直、これを読んだ子どもたちが、どう思うのか、どう考えるのかというところで、この表現でいいのかな思うところもあるんですが、これは答弁を求めても、なかなか答えられることではないと思いますので、ここではお聞きしませんけれども、それぞれどのような形でメッセージが、子どもたちと大人たちに届いたのか、教えてください。","respondent":"太田指導課長","answer":"委員おっしゃる、東京都の緊急アピールにつきましては、１０月４日に発信され、品川区教育委員会でも、１０月４日付で各学校に配付したところです。","voiceIndex":136,"id":"exchange-062"},{"speaker":"阿久津委員","kind":"質問","question":"私の友人で、これは品川区内ではないんですけれども、東京都下の中学校１年生の担任をしている教師がいまして、このことについて聞いたら、読み合わせをしたと。「みんなの反応はどうだったの」って聞いたら、「それほどの反応はなかったよ」ということだったんです。逆にそういう通報が常にあるのかどうか、そういうことも含めてお聞きしたいと思います。","respondent":"太田指導課長","answer":"地域の方々への発信ですけれども、地域の方々へは、保護者会、説明会、学校で行う会等、さまざまな機会を通じて、そういった機会を活用しまして、お知らせしていくという形をとりたいと考えています。","voiceIndex":138,"id":"exchange-063"},{"speaker":"阿久津委員","kind":"質問","question":"今までは、地域の方に対する呼びかけというのは、されたことがあるのでしょうか。地域からの見守りの成果というか、そういうものはあるのでしょうか、いじめに関してですけれども。","respondent":"太田指導課長","answer":"今後、この手引きの説明も通して、いじめについてのお話もさせていただきたいというところで、活用してまいりたいと考えております。","voiceIndex":140,"id":"exchange-064"},{"speaker":"阿久津委員","kind":"質問・要望","question":"具体的な事例はお伺いできなかったんですけれども、地域の力を活用していっていただきたいと考えています。最後になりますけれども、家庭向けのアンケートというのも配布されております。","respondent":"太田指導課長","answer":"これにつきましては、各ご家庭でチェックをしていただきまして、学校で三者面談とか、そういう折に、必ずこれを話題にして、この内容について話し合っていただくという形で活用していただくようになっております。","voiceIndex":142,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、１７５ページ、プラン２１推進事業に関係して、学校選択制について、お伺いします。私は、９月２１日一般質問で、人間を大切にする教育の実現こそいじめ克服の道、学校選択制など、競争教育からの転換を求める質問をしました。一般質問では、何よりも子どもの学ぶ権利を保障し、保護者、教員、地域が安心して話し合える信頼関係を築けるよう、区教育委員会に求めました。","respondent":"齋藤庶務課長","answer":"は家庭の教育力の低下への対応ということで、どういうふうに教育委員会はかかわっているかというお話をいただきました。その他といたしましては、独自教員の問題やすまいるスクールについてのお話をいただいたところです。","voiceIndex":145,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問","question":"私も、参加者の方から幾つか、何町会からかご意見を伺ったんですが、一番強烈だったのが、お祭りとか防災など地域に協力を呼びかけても、地域の学校に通っていないのでと協力を得られないことか多々あるということ。学校からは協力してほしいと言われるが、一体どう協力したらよいのか。学校選択制の問題との、地域からの指摘、どう受けとめているのか、お答えを願います。","respondent":"和氣学務課長","answer":"私どもとしては、それなりの理解をしていただいたと思いますし、また、そこで出た意見については、私どもも真摯に受けとめて、学校選択制の中で、また学校と相談をしながら、地域との結びつきをしっかりとつくってまいりたいと考えているところです。","voiceIndex":147,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すぐに近くの小学校を選ばなくて、遠くの小中一貫校を選んだお母さんに、どうしてそこの学校を選んだんですかと聞いたところ、地域でいじめに遭ったので、関係を断ち切るためにも、地域の学校ではないところを選んだといったお話を伺いました。いじめのない学校を選びたい、ほんとうに親御さんの気持ちであると思います。ほかの学校をまた選ぶのでしょうか。これでは解決をしないと思います。","respondent":"和氣学務課長","answer":"そうやって一旦解放して、そして新たに回復をしていく、そういう場を与えるということも、学校教育にとっては大変に必要なことであろうと考えていますので、私どもは、選択制を継続しながら、その中で、地域との結びつきも。","voiceIndex":149,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"私は、選択制の弊害についてお伺いをしました。２００９年度の中学校の選択においてです。そして、指定校変更と私立中学校選択と合わせると、何と５４.３％の生徒が地元の公立中学校から転出をしている。それから地元の中学校を選ばない生徒が５４.３％もいる、このような状況が公教育と言えるのかどうか。私は、正常に機能していないと思いますが、この点はいかがでしょうか。","respondent":"和氣学務課長","answer":"そうした部活を保障するという意味でも、選択制がなければ、子どもたちのほんとうに楽しい、そしてしっかりとした学校生活を送る機会を保障できませんので、私どもは、そうやって、子どもたちがよりよい中学校生活を送るためにも。","voiceIndex":151,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、公教育というのは憲法で保障されている、等しく教育を受ける権利、これを保障する、子どもの権利条約にうたわれる最善の教育環境をつくっていくことであると思います。そういった意味では、学校選択制を直ちにやめるべきと、強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"１７５ページ、スクールカウンセラー派遣費、１８０ページの学校管理費、借地料、学校環境整備事業の中で、屋上緑化を含めて校庭整備、これはまとめてお聞きます。しかしながら、スクールカウンセラーの性格上、守秘義務というのがありますので、その情報をどのような扱い方をされているのか、それとまた、専門家へのリファーというのは、どういう形でされているのか、お聞きします。次に、借地料です。","respondent":"太田指導課長、齋藤庶務課長","answer":"私からは、スクールカウンセラーについてのご質問について、お答え申し上げます。ただ屋上ですので、根の張るものに若干制限があるので、なかなかさまざまな種類のものは植えられないということですが、できる学校は引き続き継続して進めていきたいと考えております。","voiceIndex":155,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"守秘義務があるわけですから、校長であっても、守秘義務を守らなければいけないという決まりになっていると思うんです。それから、専門家へのリファーをしているということなんですが、これもやはり、スクールカウンセラー一人ひとり、ちょっと特徴があるので、これからの増員もあるかと思うんですけれども、その選定をどのようにされるのか、もう１点、お聞きしたいと思います。","respondent":"太田指導課長、齋藤庶務課長","answer":"倍率は、今のところ、３０倍ぐらいですので、よい人材を選んで採用することができている状況です。その採用にあたっても、特別支援教育の視点を重視して採用しています。人工芝の教育上の効果ですけれども、裸足でグラウンドを駆け回ることができる、寝ころがれるということで、解放感ですとか、遊び時間の充実ということで、子どもたちの学校活動は充実していると考えております。","voiceIndex":158,"id":"exchange-072"},{"speaker":"西本委員","kind":"質問","question":"次に、学校維持費、管理費です。学校選択など、教育改革というのが、品川区はとても進んでいると思っているんですけれども、それと同時に学校のあり方、また特に地域とのかかわり方が大きく変わってきたのではないのかと感じております。それについては、私は非常に評価をしているところがあります。それについては、どのように考えられていますでしょうか。","respondent":"齋藤庶務課長","answer":"そういう意味で言うと、品川区では、学校の施設の利活用を十分に図っていただくことで、学校に対する参加意欲というのは増進していると考えております。","voiceIndex":161,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"より地域に開かれた学校を目指していくということで、これは非常に大切なことだと考えています。二つに分けることはできないかもしれませんけれども、ただ、ここは、予算計上の中で、少し分けられるのであれば分けて計上するということもあっていいのではないかと思いますが、いかがでしょうか。","respondent":"和氣学務課長","answer":"例えば６時半まで部活動で使っていますから、それ以降の電気代というようなことになりますと、またメーターをどういうふうにつけるのか、もしくは、学校がまだ一方でほかの教室を使っているとかありますので、なかなか難しいところはあります。","voiceIndex":163,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"これから、いろいろな使い方があろうかと思うんです、学校施設は社会の財産という形になりますので。そうなると、学校を間借りしているという感覚ではなくなってくると思うんです。そういうあり方もいろいろ変化も出てくると思いますので、そこはちょっと十分に、今後、運営上検討していただきたいと考えています。なぜ今回、教育委員会から子育て支援課になったのか、理由をお聞きします。","respondent":"安井子育て支援課長","answer":"すまいるスクールを来年４月から子育て支援課のほうで所管するというようなことになっております。","voiceIndex":165,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"そういう答弁になると、別にすまいるスクールを教育委員会から子育て支援課に持っていく必要はなくて、連携をすればいいという話になると思うんです。しかも、そのために学童保育を統合という意味で、廃止したわけですよね。今回、変わったというのは、その考え方と何か大きな違いがあったのか、何か要因となる何かがあったのかということについて、お聞きします。","respondent":"安井子育て支援課長","answer":"職員を採用して育成していく段階の中で、全体的にうまくやっていくというようなことが、すまいるスクールも児童センターも含めて、これからうまく運営していけるような形になるのではないかというふうに考えているところです。","voiceIndex":167,"id":"exchange-076"},{"speaker":"西本委員","kind":"意見","question":"それは理由にならないと思います、これは絶対に理由になりません。指導員が少なくなったということであるならば、指導員を採用すればいい話ですよね。そういう意味ではなくて、そもそも学校の中に学童保育、放課後のそういうものを持ってきたというのは理由があったと思うんですよ。その中で、今回の移行というのは、指導員の育成という意味は答えになっていませんので、もう一度、ください。","respondent":"安井子育て支援課長","answer":"そういった意味で、また子育て支援の現場である児童センターのほうは、そこの部分を在宅子育ての部分であるとか、中高生の居場所という形で、広く新たな部分も開拓することができましたので、それを全体としてすまいるスクールと児童センターと二つの中心軸で。","voiceIndex":169,"id":"exchange-077"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど来、意見交換会の話が出ておるんですが、６回とか、８回、８地域センターというのですが、これの目的と、タイムスケジュール、例えば教育委員会がどのぐらい話して、質疑応答がどのぐらいあったかみたいな、タイムスケジュールを教えていただきたいと思います。そういうデータも大体出て来るだろうと思うので、その検討を、どういうふうにしていくのかというところを、ある程度教えていただきたい。","respondent":"齋藤庶務課長、太田指導課長、和氣学務課長","answer":"具体的な中身については、これまでさまざまな取り組みをしてまいりましたけれども、最新の情報をお伝えするです。学校における黄金比率というようなお話でございましたけれども、学校におきましては、黄金比率というものはないと考えております。その段階で、実は特に臨海部を中心に、教室不足が課題になっておりまして、まだちょっと、適正規模にいく前に。","voiceIndex":172,"id":"exchange-078"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば、教員の方々も、それはすごく一生懸命頑張っている方もいるけれども、やはりだめだなというのもあるのではないですか。だから、そこら辺のところを、どういうふうに捉えて、どういうふうにやっているのかということを教えていただきたい。御殿山小学校だったら、７割を超えて私立の中学校に行くわけですけれども、そうすると、成績で言う頭のいい子は、みんな抜けてしまうわけではないですか。","respondent":"田村教育次長、太田指導課長","answer":"スタートを切ったのは、もともと学校が現場に出ろと、地域に出ろといっていて、教育委員会はバックにいてなかなか地域に出てこないというのが発端ですから、送り迎えも、私も窓口に立ってやって、「田村さんよかったよ。委員おっしゃるように、いろいろな段階の先生がいて、そういった方が、例えば保護者に対してどういうふうに対応するのかとか、そういったところについては、学校は組織ですので、学校の中で。","voiceIndex":176,"id":"exchange-079"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１７５ページの生徒指導対策費になるんでしょうか、薬物、ドラッグのことについて伺いたいと思います。それから、１７７ページの発達障害児に係る研究委託、そして時間があれば、国際理解教育ということでお伺いしたいと思います。その点で、今、品川区における薬物に対する教育というか、指導はどのような状況になっているのか、お伺いしたいと思います。","respondent":"和氣学務課長","answer":"品川区では、４年前から薬育ということで、学校薬剤師さんに委託をしまして、まだ全校とはなかなかいかなかったわけですが、薬に関する教育をやらせていただいております。","voiceIndex":180,"id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"そのうえで、この前、ある雑誌で、脱法ドラッグで命を落とすといった方の写真とかが載っているのをちらっと見たりしましたけれども、生々しいものではありますが、これが現実ということで、最初はほんとうにちょっとした好奇心から入っていって、薬物は依存症の問題がありますので、最初はそんなつもりはなくても、どんどん泥沼というが、地獄に落ちてしまうみたいなことが、この薬物の怖さであるので。","respondent":"和氣学務課長","answer":"一人でも子どもがそういうところに流れないように、最大限の努力をさせていただきたいと考えているところです。","voiceIndex":182,"id":"exchange-081"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました、よろしくお願いしたいと思います。続きまして、１７７ページの発達障害児に係る研究委託ということで、２００万円、決算として計上されております。この事業について、どういうものかご説明いただきたいと思います。","respondent":"太田指導課長","answer":"内容につきましては、子どもたち一人ひとりの学び方の違いに注目し、学習のつまずきを、低学年、大体２年生ぐらいですけれども、そのうちに発見するというために、例えば担任による配慮は、どういうものがいいのかとか、あとは楽しみながら取り組める教材開発であるとか。","voiceIndex":184,"id":"exchange-082"},{"speaker":"塚本委員","kind":"意見","question":"小学校の３、４年生を対象とした国語と社会の授業において、読みの困難といったものを支援するソフト、ソフトバンクだということなのでｉＰａｄを使っているそうなんですが、こういったものを使って、読み書きの苦手な児童の基礎学力の向上を目指すと。このような考え方によって、さまざまなこういうツールを導入していくということについて、どのようなお考えをお持ちかお願いしたいと思います。","respondent":"齋藤庶務課長、和氣学務課長","answer":"１点、委員にご紹介いただいた大分県佐伯市につきましては、当該実施校の校長、すまいるスクールのスタッフで視察に行っておりまして、実際に現場を見ております。ただし、今、いろいろなところで研究はされているんですが、その機械を配備したら何か役に立つというよりも、教員の技術、もしくはその活用方法がかなり重要でございまして。","voiceIndex":186,"id":"exchange-083"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。こういった機材等を配ることに関して、一つは、不公平なのではないかとか、一部の方だけに配ったりするのは不公平なのではないかと、ちょっとこういう課題がややもすると出てきがちだと思うんですけれども、この点に関して、どのようなお考えをお持ちか、お聞かせいただきたいと思います。","respondent":"和氣学務課長","answer":"しかし、それぞれ使い勝手がございまして、何に一番適応されて、何が一番効果的かということがだんだんわかってまいりましたので、そこをしっかり説明をして、例えばアイパッドが発達障害の方に大変有効であるということを丁寧に説明しながら。","voiceIndex":189,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いしたいと思います。こういった中で、国際理解教育という中で、品川区の教育委員会としても、アジア、特に日中、日韓に対しても、さまざまこういった交流、相互理解、必要な重要性が増してきているのではないかと思うんですが、そういったことに、どのようなことがされているか、現状をお聞きしたいと思います。","respondent":"太田指導課長","answer":"本区独自の市民科でも、国際理解教育ということで、日中、日韓等、学習も進めているところです。","voiceIndex":191,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問・要望","question":"月並みではありますけれども、やはり相互理解のために、自国、または相手国の歴史認識ですとか、正しい知識とか、そういったものをしっかりと教育の中でも教えていくということが、今ますます重要になってくるかと思いますので、ぜひ、その点はよろしくお願いしたいと思います。これは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、１７４ページ、区教員経費、そして１８０ページの学校教育費、それから、ここには載っていないんですがスクールゾーンについて、お伺いさせていただきたいと思います。以前質問したところ、課長の答弁で、四つの警察署の交通安全課長と協議をして、これから詰めていくというご答弁をいただきました。そして、協議を行った中で、今現在、どうなっているのかを、教えていただきたいと思います。","respondent":"齋藤庶務課長","answer":"したがいまして、区といたしましては、本庁の交通規制課に働きかけて、第１と第３はスクールゾーンを設定できないかというお願いいたしましたが、東京都全域の仕組みなので、公安委員会としては。","voiceIndex":195,"id":"exchange-087"},{"speaker":"大倉委員","kind":"質問・要望","question":"今はできないというご答弁だったんですが、道路交通安全基準法でスクールゾーンを設定した過去は、スクールゾーンというのは、そこで指定できると思うんですけれども、指定した後が、道路交通法で、今、そういった部分では動かせないというところになっているのかと思うんですが、そうした部分で、現状、区としては、土曜日のスクールゾーンをどのように対応しているのでしょうか。","respondent":"齋藤庶務課長","answer":"安全対策を、規制の変わりに補完する形でシルバー人材センターに委託をいたしまして、各校危険な交差点について、旗振りという言い方をするとあれですけれども、指導している、あるいは、４署の警察の方も、交番の警察の方が可能な限り、土曜日。","voiceIndex":197,"id":"exchange-088"},{"speaker":"大倉委員","kind":"意見","question":"警察官とシルバー人材センター派遣で連携をされているということですが、ただ注意を促すだけになってしまうのだと思うんです。そうした中で、前回もちょっと土木のほうでも挙がりましたが、ハンプの設置とか、そういったお考えがあるのかどうか、お聞かせいただければと思います。","respondent":"稲田道路課長","answer":"そのようなスクールゾーンにおきまして、路面の構造を変えて設置するというところなんですけれども、そういう狭い道路におきまして、ハンプを設置することによって、振動や騒音という影響も出てきますので、今のところでは、構造的に入りにくくするということは考えておりません。","voiceIndex":199,"id":"exchange-089"},{"speaker":"大倉委員","kind":"質問","question":"わかりました。朝、登校時間中に、地元のボランティアの方たちが旗振り、交差点に立って、朝の挨拶などをしながら、子どもたちの登校を見送っているという方たちとちょっとお話をしたら、それは大変だから、私たちも土曜日にしようかなんていうご意見をいただきました。そうした周知とか、そういったことになっていますというようなことは、今後、していくんでしょうか。","respondent":"齋藤庶務課長","answer":"ボランティアの方につきましては、今後、土曜日の安全対策ということでお願いしてまいりたいと思います。","voiceIndex":201,"id":"exchange-090"},{"speaker":"大倉委員","kind":"質問","question":"区教員の経費について、お伺いします。事務事業概要に書いてあったんですが、平成２５年度までに３０人という目標があったかと思うんですが、間違っていたらすみません、指摘していただければと思いますが、その目標をどのように設置して、何で３０人という目標なのか、また、今、その目標に対して現状１２人ということですが、その現状をどう捉えて、どうお考えになっているのか。","respondent":"太田指導課長","answer":"ただ、区の中で、先ほど申したように、子どもたちの生涯の先生として、なるべく多くの子どもたちにかかわってもらうということを考えますと、多少、期間は延びるかもしれませんけれども、３０名の採用を目標に進めていきたいと考えております。","voiceIndex":203,"id":"exchange-091"},{"speaker":"大倉委員","kind":"質問・要望","question":"私も、そうした品川区の教育に対する熱い思いとか、夢を持った先生がぜひ増えていただきたいと考えています。そんな中、今回、募集期間が変わったかと思います。過去は、品川区で９月、今、６月になっているかと思いますが、その変わった理由。都が７月、８月で、東京都より先にということなんだろうかとは思っているんですが、その変わった理由を教えていただきたいと思います。","respondent":"太田指導課長","answer":"委員おっしゃるように、今年は６月１日から７月６日にかけて募集をかけまして、一次試験が７月２９日、二次試験が８月２５日、最終面接が９月９日、そして、最終的に９月１１日には合格通知を出すというような形で進めております。","voiceIndex":205,"id":"exchange-092"},{"speaker":"大倉委員","kind":"質問・要望","question":"９月はもう終わっていますが、やはり応募も増え、そうした優秀な先生方、熱意のある先生方が増えたという認識でよろしいのでしょうか。私もちょっとお話とかを聞いて、やる気のある先生がいっぱいいてすばらしいなという思いがあります。やはり、学校は、校長先生がトップですから、校長先生にいろいろアプローチをかけて、こういう学校にしていきませんかということができるのか、どうか。","respondent":"太田指導課長","answer":"その主幹教諭までは、制度上、品川区でも整えてまいりましたけれども、副校長、校長につきましては、これから取り組んでいかなければならないと考えているところです。","voiceIndex":207,"id":"exchange-093"},{"speaker":"大倉委員","kind":"意見","question":"校長、副校長には、今のところなれないということでしたが、ぜひ、今後、長い目で見て、そういった方々が他区に行かずに、品川区で育っていって、品川区をどんどんよくしていく、そのことを非常に強く望んでおります。ぜひ、そうした方も校長、副校長になれるような関係機関への働きかけという感じになると思うんですが、お願いして、以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":209,"id":"exchange-094"},{"speaker":"本多委員","kind":"質問・要望","question":"３点、質問いたします。最初に、教員、学校の先生についてなんですが、午前中に質疑が出ておりました、重複いたしますが、同じ思いで質問します。まさに、学校の先生にも、学年とか、そういう区別はありますけれども、守備範囲がない、フォローをし合うというようなところがどうなっているのか、その点をお聞かせいただきたいと思います。","respondent":"太田指導課長","answer":"ですから、学校での態勢も、例えば学年であるとか、それから二、三学年合同のくくりであるとか、あとはもちろん管理職も含めた全校で、ちょっと言葉が固いですけれども。","voiceIndex":211,"id":"exchange-095"},{"speaker":"本多委員","kind":"質問","question":"ぜひ、心配りをよろしくお願いいたします。２番目の質問なんですが、先ほど、午前中の質疑で、生徒が授業中に熱中症が起きたときに、病院に搬送をされたという対応を伺ったんですけれども、これは、保健室ですぐに処置ができないものか。","respondent":"和氣学務課長","answer":"それでもどうしても回復しないとか、もしくは見たときの状況ですぐに救急車を呼ばなければいけないというときには、そういたしますが、一義的には保健室でしっかりと回復を図るということで考えているところです。","voiceIndex":213,"id":"exchange-096"},{"speaker":"本多委員","kind":"質問・要望","question":"ほんとうに世の中が動いているなと感じるんですけれども、図書館の取り組みについて、質問いたします。この団体貸出しは品川区のみということですけれども、期間が３カ月間とかで、利用者はすごく長い期間で使いやすいと思うんですが、ほかのお客さんの順番待ちというか、その辺は大丈夫なのでしょうか。その辺の現況を教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"ほかの一般利用者の方々は、貸出し期間が長いのではというところでは、逆に、実は、９月１日から貸出し期間を、一般の方、３週間を２週間にという制度改正をさせていただいて、少しでも皆さんに本が早く回転率を上げられるようにということで、させていただいたところです。","voiceIndex":217,"id":"exchange-097"},{"speaker":"本多委員","kind":"質問・要望","question":"一般が、３週間から２週間に短縮ということで、わかりました。それから、国会図書館に行くと、日本中の本、全てがここに用意されていて、ないものがないという、しかもあれだけ多い中、書き込んで申し込むとすぐに出てくるんですよね。あれはほんとうに不思議だなと思うんですけれども、そういったスピーディな部分とか、その辺は何か参考になる部分があるのか、どうか、教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"すみません、手元にないので、数字まではお伝えできませんが。特に目黒区、渋谷区、世田谷区、大田区、港区につきましては、昔から城南６区で相互貸借という取り決めをしておりまして、相互に貸し出し、貸し借りをしております。","voiceIndex":219,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問","question":"先ほど、図書館のクレーム対応というところで、質問が出ていましたけれども、図書館の中で、床材がすごく気になるところがあるんです。多分、読書をしているお客さん、すごく人の足音が気になると思うんですが、ああいうのは、防音とか、そんな大げさなことではなくて、少し配慮することで、お客さん同士のもめ事が少しでも減少できないかなと思うんですが、そういった点はいかがでしょうか。","respondent":"中元品川図書館長","answer":"ただ、施設環境のほうを確認させていただきまして、できる範囲で、どのようなことができるか、通路にカーペットをしくとか、何かそういうことで、経費がかからない方法で解消ができる工夫に努めさせていただきたいと思います。","voiceIndex":221,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"これは指導課のほうになると思うんですけれども、活字離れがないようにいろいろ取り組みをされていると思うんですけれども、児童・生徒に。当然、日ごろ、いろいろやっているのはわかるんですが、習慣について、今後、どういうふうな対応をされるのか、教えていただきたいと思います。","respondent":"太田指導課長","answer":"各学校の取り組みといたしましても、図書の読み聞かせであるとか、ブックトークを実施するとか、目標とする読書量の設定をするとか、そういったような形で取り組んでおりまして、読書離れに歯どめをかけるような形での取り組みをしています。","voiceIndex":223,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いします。それから、いろいろなマンションとか、自治会で、古本を使って、みんなで回し読みとかしている動きが、かなり世論で始まっていると思いますので、できれば、そういった部分を把握していただいて、できること、本を活用するというところで支援をしていただければと思います、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"いじめ防止について、あるいは、いじめに関するこれまでのさまざまな教育委員会、また学校の取り組みについては、質疑の中で伺うことができました。そのことについての認識と、それについて、今回、命の大切さ等のことも指導されたと思うんですが、そちらも含めて、どのようなご指導をされたのかということを、お伺いします。","respondent":"太田指導課長","answer":"委員、先ほどおっしゃっていただいたように、今回の件につきましては、現在、調査中ということもありまして、その内容についてはお話しがなかなかできないのですけれども、ただ、自殺の連鎖といいますか、そういったことについて。","voiceIndex":227,"id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"品川区には市民科がありますので、市民科を十分に活用して、命の大切さを学校の中で伝えていっていただければと思います。次の話になりますが、これは、ちょっと款をまたいでしまうかもしれないですが、教育費の決算が１４７億、一般財源が８９億とあるんですが、初めにこの認識が正しいのかどうかお聞きします。","respondent":"本城企画財政課長、和氣学務課長","answer":"その中の一般財源の割合ということで、特定財源とかで確保できるものもありますが、２３区との比較の中でも、一般財源の充当率、一番高い形で。もちろん小中一貫教育か象徴的な話でございまして、そういう意味で言えば、ほかのところに先駆けて、新しいたくさんの事業をやらせていただいているです。","voiceIndex":229,"id":"exchange-103"},{"speaker":"高橋委員","kind":"質問","question":"２３区の中でも、一般財源の割合は最も高く、そして教育費にかけている。こういった財政力を持っているという裏打ちがあるんですが、逆に言うと、少しずつ今後の財政状況が厳しくなっていく中で、今、お話があった、これだけ教育費にかけているという方針は、どのように変わっていくのでしょうか。それとも変わらないで進めていっていただけるのでしょうか。","respondent":"本城企画財政課長","answer":"その中を見据えながら、計画的にやっているところですが、ただ、学校の改築等を含めて、その年度によって大規模なものが発生するときには突出したり、かなり波があるところですので、そのあたりは、基金等も計画的に積み立てることも含めて。","voiceIndex":232,"id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"ここで政策判断をしていらっしゃるので、今回は、大きくまた移管するということなので、先ほどもちょっとお話があったので確認なんですが、どのような政策選択、政策判断があったのでしょうか。区長部局の中で、組織改正をするのとはまた意味合いが、私は違うと思うんです。そういったことも含めて、今の政策選択、先ほどもご答弁がありましたけれども、もう一度お願いしたいんですが。","respondent":"安井子育て支援課長","answer":"すまいるスクールについて、教育委員会のほうで所管していただいているということで、そちらの施設を、基本的にはそのままうちのほうでお預かりするという考え方ですので、基本的に、中身を変えてどうこうということではなくて、担当する人間の問題であるとか。","voiceIndex":234,"id":"exchange-105"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、区立の幼稚園みたいに、地方自治法に基づく補助執行というやり方では不十分なんでしょうか。つまり、はじめのご答弁の中にあるように、教育施設を活用しての事業で、教育委員会の権限で行われてきた。これは重要なことだと思っています。その連携のところを、今の移管先と、それから教育委員会のほうでどのように積極的に連携をとっていくのか、その両方の所管の方のお考えを伺いたいと思います。","respondent":"安井子育て支援課長、齋藤庶務課長","answer":"連携につきましては、ご懸念がいろいろあるようですけれども、従来と同様な形で連携を十分にとらせていただくということで実行していきたいと考えているところです。この点につきましては、学校長の連絡会やさまざまな取り組みの中で周知をいたしまして、学校から教育委員会、教育委員会から区長部局に移管した後も、すまいるスクールに通う子どもたちは。","voiceIndex":236,"id":"exchange-106"},{"speaker":"高橋委員","kind":"質問・要望","question":"次に小中一貫教育推進経費ですが、小学校と中学校の情報の共有というか、連携について、ちょっとお尋ねしたいんです。それは小学校のほうから、何か申し送りのようなものがきて、それが中学校の先生方の指導の参考になっているのでしょうか。よろしくお願いします。","respondent":"太田指導課長","answer":"そのほかに、小中一貫教育を進める中で、例えばブロックの中で、連携型、分離型におきましても、小学校５年生ぐらいから、中学校の教員が積極的にかかわるというような形で、相互乗り入れを行っておりますので、そういった点では、小学生の情報というのは。","voiceIndex":239,"id":"exchange-107"},{"speaker":"高橋委員","kind":"質問・要望","question":"それからもう一つ、その管理なんですが、先日のニュースで、そのリストを、先生が教室に置き忘れてしまって、それが中学校の生徒に見られてしまって、いろいろ問題が起きたということで、その情報の管理も徹底していただきたいんですが、いかがでしょうか。","respondent":"太田指導課長、和氣学務課長","answer":"８、９年生になったときに、その小学校の情報が活かされる場が少ないのではないかというお話でしたけれども、確かに中学校に７年生で入りますと、目の前の子どもたちが１年間たって、中学生として生活するわけなので。これにつきましては、校務システムの中でも、１年間の情報が全部見えるような仕組みを、今つくっておりまして、小中一貫教育に合わせまして、子どもたちの情報をしっかりと共有できるように、セキュリティをしっかりしたうえで、今。","voiceIndex":241,"id":"exchange-108"},{"speaker":"高橋委員","kind":"質問・要望","question":"システムが今はなくて、つくっているということですね。今、お話がありましたので、そういった１年生からのさまざまな情報を活かして、小中一貫の教育に役立てていっていただきたいと思います。時間がなくなったので、最後、また別の機会に質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-109"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、１７４ページ、事務局費の中の就学相談員費、そしてまた時間があれば、１７６ページの特色ある教育活動経費について、お伺いしたいと思います。二人に増員したのは、どういうことなのか。相談員なんですけれども、どのような方が相談員になっていらっしゃるのか。そしてまた、その相談員は、毎年変わるのかどうか、その辺を教えていただきたいと思います。","respondent":"和氣学務課長","answer":"そのために、２名となっているです。相談員は、毎年変わりません。なるべく経験豊かな先生にやっていただきたいということで、なるべく継続して働いていただいているところです。","voiceIndex":247,"id":"exchange-110"},{"speaker":"山元委員","kind":"質問・要望","question":"７月から就学相談の申請がスタートして、８月の上旬でしたか、実際に就学相談がスタートするわけですけれども、ちょっと見ると、監察とか診療、面接云々と書いてありますけれども、実際にこの内容というのでしょうか、どのような相談なのか。それからもう一つ、年間を通して、相談に来る方が何人ぐらいいらっしゃるのか、この点を教えていただきたいと思います。","respondent":"太田指導課長","answer":"就学相談、先ほどお話しがありましたように、保護者より電話、あるいは窓口にて７月１日より申込みが始まっております。そして、就学相談は教育センターで行うんですけれども、子どもの監察を集団や個別対応にて、五、六名程度の集団にして行います。","voiceIndex":249,"id":"exchange-111"},{"speaker":"山元委員","kind":"質問・要望","question":"その結果、区内に特別支援学校、または通常学級へ通っていく人数というのでしょうか、それぞれの人数を教えていただきたいと思います。","respondent":"太田指導課長","answer":"昨年、小学校では、通常級へは４０名、そして特別支援学級へは２３名、そして特別支援学校へは９名、また、中学校は、通常級へは１１名、特別支援学級へは１４名、特別支援学校へは８名、入学しているということがあります。","voiceIndex":251,"id":"exchange-112"},{"speaker":"山元委員","kind":"提案","question":"その際、学校としては精いっぱいやるけれども、できないことがあることは承知してほしいと言われると。逆に今度、保護者がこういうふうにしてほしいと提案すると、特別支援学校への転学を勧められるということで、そんなお話をされましたが、実際、途中で特別支援学校への転校というのは、何人いらっしゃるのか。もしわかれば、教えていただきたいと思います。","respondent":"太田指導課長","answer":"学校でのご相談の際に、できる限りというところで、ご相談があるですけれども、途中で特別支援学級に移るという子どもは、年間で大体二、三名というふうに聞いております。","voiceIndex":253,"id":"exchange-113"},{"speaker":"山元委員","kind":"質問","question":"その際、先ほどの判断会がありますが、先ほど校長先生の人数も１５名とおっしゃっていましたが、そこに当該の校長先生が参加できれば、この問題が解決できるのではないかと思いますが、その辺はいかがでしょうか。","respondent":"太田指導課長","answer":"やはり、そういった中でご相談する中で、本人にとって最もいい方法というのが、年度区切りではなくて、途中でもご相談を差し上げたりすることができるのであれば、そういったような相談をした結果、先ほど、二、三名の方が移られたといったことだと考えています。","voiceIndex":255,"id":"exchange-114"},{"speaker":"須藤委員","kind":"意見","question":"１７４ページの事務局費、同じく１７４ページの教育指導費、１７５ページの小中一貫教育推進経費について、お尋ねします。事務局費では、福祉厚生のところで、教職員で、いわゆる疾病で休まれている方がどのぐらいいらっしゃるのか。特に精神疾患で休まれている教員はどのぐらいいらっしゃるのか。","respondent":"齋藤庶務課長","answer":"教職員、教員、これは都費の事務職員も含めてですけれども、病気休職、３０日以上病気休暇をとった後、復帰できないで休職に入った方は、平成２１年度で１２人、そのうち精神疾病が１０人。平成２２年度で、休職者が９人、うちメンタルヘルスが９人。","voiceIndex":258,"id":"exchange-115"},{"speaker":"須藤委員","kind":"質問","question":"教育指導費については、今年から武道、特に柔道が、品川区が数多く取り入れられているというので、危険性だとか、そういう話が出てきていますけれども、柔道自体、嘉納治五郎先生が明治１５年につくりまして、学校柔道というのは昭和６年に中学校で入ってきた、昭和１４年には、小学校で正課になったという戦前の歴史があって、昭和２０年の終戦後に廃止になって、平成２５年から復活して、各警察。","respondent":"太田指導課長","answer":"武道を進めるにうえにおいて、その教員の指導についての研修についてですけれども、教育委員会では、安全対策の基本方針の徹底、それから、主に柔道で言いますと、受け身の指導法の理解を狙いとした２時間の研修を年５回実施して、現在までに５、６年生の担任と。","voiceIndex":260,"id":"exchange-116"},{"speaker":"須藤委員","kind":"質問","question":"品川区の平塚学園の生徒が優勝しました。すごいなと思いました。区内の都立高校と連携をする仕組みを、今、考え中であるというような話をもらっているんだけれども、単に連携するのでなくて、そこから上に、進学がいいという成果が出てこなければ、なかなか小中高の一貫というのもすっきりいかないと思うんですけれども、そのあたりはいかがでしょうか。","respondent":"太田指導課長","answer":"具体的な姿というのは、ちょっとまだなんですけれども、ただ、区内を見渡しますと、例えばものづくりで都立産業技術高等専門学校とか、先ほど、連携の段階ではないとおっしゃったんですが、そういったような地道な形での積み重ねも、今、実施していますので、今後。","voiceIndex":262,"id":"exchange-117"},{"speaker":"須藤委員","kind":"質問","question":"いずれにしても、品川区の子どもたちが区立でしっかりすばらしい教育を受けて、いい大人になってもらえるような仕組みをつくってもらいたい。そのあたりを学校で、前にもこれはお願いしたと思うんですけれども、気をつけの形、かかとをそろえて背筋を伸ばして礼をするという姿勢は、体育の授業でやっているのかなと思うんですけれども、いかがでしょうか。","respondent":"太田指導課長","answer":"武道の授業におきましては、その時間も限られているということもありますし、乱取りということではなくて、主には心構え、それから礼法を重点に学ばせて、そういった礼法等を重視して、指導するようにということで、進めております。","voiceIndex":264,"id":"exchange-118"},{"speaker":"須藤委員","kind":"質問","question":"男の子もそうなんだけれども、やはり礼をするときには、きちんとかかとをそろえて礼をするという形が、外から見ても気持ちがいいし、やはりしつけ、体が美しいということをしっかり教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-119"},{"speaker":"南委員","kind":"質問・要望","question":"１７４ページの教育指導費について、伺います。学校で６時間授業を、実態として何年生からやっているのか。学校によっては小学校１年生から６時間授業を受けていると聞くこともありますけれども、そのような実態がほんとうにあるのかどうか、教えてください。そしてまた、学年ごとに、６時間授業は週何回あるのか。そのときの下校時間は何時なのか、教えていただきたいと思います。","respondent":"太田指導課長","answer":"先ほど申したように、土曜日授業で、年間３０時間超の授業をやっておりますので、その分も、月曜日から金曜日までの授業を一こま抜くというような工夫もありますし、そういった形で対応しています。","voiceIndex":268,"id":"exchange-120"},{"speaker":"南委員","kind":"質問","question":"６時間授業は各学年、１週間に何日やっているのかと聞いたので、時間数ではなくて何日かというふうに日にちで教えてください。","respondent":"太田指導課長","answer":"学校によって時間割の編成については違いますので、一概には申せませんが、先ほど申し上げたような、時数の割り振りです。","voiceIndex":270,"id":"exchange-121"},{"speaker":"南委員","kind":"質問・要望","question":"そうしますと、１年生から６時間授業があるという学校があるのかどうか。そのあたりも、さっき聞いたんですけれども、その点について、お答えいただきたい。それから、６時間授業が始まるのは、おおむね何年生からがメーンなのか、そのあたりを教えてください。","respondent":"太田指導課長","answer":"すみません、校数までは、ちょっと把握しておりません。大体、何年生から６時間授業になるのかですけれども、何年生からというよりは、１年生は若干６時間ではない日もありますけれども、２年生からは、おおむね６時間授業は続くという形です。","voiceIndex":272,"id":"exchange-122"},{"speaker":"南委員","kind":"質問・要望","question":"職員会議は１週間に何回やるのか、時間はどのぐらいか、あるいはまた学年会議というのがあるそうですけれども、それも１週間に何回か、そしてそのほか、さまざまな打ち合わせがあると思うんです、例えば行事を迎える時期は、行事に対する打ち合わせ等々、そういうさまざまな打ち合わせ、どんなものがどの程度持たれているのか、それを教えていただきたいと思います。","respondent":"太田指導課長","answer":"区教育委員会への報告のボリュームですけれども、どの程度というふうに申し上げたらいいのか、ちょっと迷うところなんですけれども、必要なことに関して、必要なときに報告を求めるというもので、ボリュームがどの程度というのは、ちょっと申し上げられません。","voiceIndex":274,"id":"exchange-123"},{"speaker":"南委員","kind":"質問・要望","question":"教育委員会への報告については、いろいろ種類があると思うし、そのときどきによって違うかもしれないけれども、日常的に、例えば１週間に１回は必ず何かしらの報告を、回数的に求めるものがあるとか、そういう状況をお知らせいただきたいと思います。そして、残業の実態も伺いたいんですけれども、月当り何時間なのか。","respondent":"太田指導課長","answer":"教員の残業についての質問ですけれども、基本的に、教員は、原則、残業はないです。最初から給料にその分が含まれているところもございまして、残業手当はないです。例えば、ノー残業デイを設けたりとか、そういう取り組みは、今は各学校でも進めているところです。","voiceIndex":276,"id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"私は、この質問で、何を質問したかったかというと、学校の先生方の勤務の実態の大変さというのが、ほんとうにあるのではないかというふうに思うわけです。今、残業代は支払われていないから、１時間も、２時間も、あたかもだれも残業していないみたいなご答弁だったんですけれども、実態はそうではないですよね。そういう実態は、教育委員会はつかんでいないんですか。","respondent":"太田指導課長","answer":"有給休暇の取得日数ですけれども、小・中学校平均で、平成２３年度で９日というデータがあります。","voiceIndex":278,"id":"exchange-125"},{"speaker":"南委員","kind":"質問・要望","question":"残業の具体的な実態について、体験されているのであれば、そういう感覚、認識は当然お持ちでしょうから、品川区の全ての教員の状況をしっかり把握するべきだと考えています。把握しているのであれば、お知らせください。それから、品川区の３３人、それぞれ年度で１０人、９人、６人、８人ですけれども、こういう実態は、全都から見て、どういう状況だと認識していいのか、それについて伺いたいと思います。","respondent":"太田指導課長、齋藤庶務課長","answer":"残業の実態について、残業ということではわかりませんけれども、居残りといいますか、残っている状況については把握しています。メンタルヘルスで休職をされている教職員の数ですけれども、２年、３年と継続されている方がいらっしゃいます。その内訳を、今把握おりませんが、延べで数えられると、ちょっと正確さを欠くかなということです。","voiceIndex":280,"id":"exchange-126"},{"speaker":"南委員","kind":"質問・要望","question":"ほんとうに痛ましい状況だと思います。大体が５時間授業だと、１年生から５時間の授業、２年生で６時間授業が週２回、こういう状況の中で、翌日の授業準備をするのがほんとうに大変だと、１日、朝からずっと仕事をして、休憩を取れるのは３時過ぎではないですか、４時過ぎぐらいだと思うんですよ、実態的には。そういう事態は、教育委員会はどういうふうに認識しているのか伺いたいと思います。","respondent":"太田指導課長、齋藤庶務課長","answer":"教員は、授業をやること、それから授業のために教材研究をすること、それから、保護者に対応すること、言うなれば、本来、教員としてやらなければいけない仕事ですので、それについて努力をするのは、ある意味、当たり前です。少し誤解があります。病気休職につきましては、例えば平成２４年度、８人がメンタルヘルスで休職をされておりますが、５人は２年、３年と継続されている方です。","voiceIndex":283,"id":"exchange-127"},{"speaker":"井上委員","kind":"質問・要望","question":"私は１７４ページの教育指導費全般でお伺いをいたします。先ほど、その連鎖について、ほかの学校でも臨時保護者会をされたということを伺いましたので、ここの部分も十分に気を使っていただいて、対策をとっていただきたいと思います。そこで、先ほど申しました同級生の心の健康のサポート、カウンセラーですが、複数配置は、既にされているのでしょうか。","respondent":"太田指導課長","answer":"スクールカウンセラーの配置につきましては、今回の件も含めまして、こういうような事態の場合には、複数配置をしております。","voiceIndex":287,"id":"exchange-128"},{"speaker":"井上委員","kind":"質問","question":"当該校には何人の複数配置で、小学校と中学校と違って、週２日、３日というような状況かと思いますけれども、今の現状のカウンセラーの仕事日数というか、その辺を教えてください。","respondent":"太田指導課長","answer":"先ほどのスクールカウンセラーの配置につきましても、そういったような対応ということにつきましては、２３区でもあまり例のない対応だと自負しております。","voiceIndex":289,"id":"exchange-129"},{"speaker":"井上委員","kind":"質問・要望","question":"特にこういった事象が起こっているので、２３区で例がないとか、そういう問題ではないと思いますので、少し認識を改めていただきたい。区教育委員会は、各学校のカウンセラーがどういった体制で働いていらっしゃるか、そういったところをきちんと把握されているのか、把握されているのであれば、どんなふうに、今、行われているのか、問題はないのか、ご意見を伺いたいと思います。","respondent":"太田指導課長","answer":"各学校のスクールカウンセラーですけれども、基本的には、例えば児童・生徒の心の悩みとか、そういった相談を受けるカウンセリングの対応、それから、各授業等を回って、気になる子どもを観察するとか、あとは子どもに対応について、教員からの相談を受けるとか。","voiceIndex":291,"id":"exchange-130"},{"speaker":"井上委員","kind":"質問・要望","question":"次は、暴力防止プログラムについて、お伺いいたします。改めて、暴力防止プログラム、ＣＡＰの意義と効果を伺います。事業開始は２００５年で、現在は３年生と５年生で続けられていると思いますけれども、現在の委託先がどこになっているのか、一緒にお答えください。","respondent":"太田指導課長","answer":"今、委員ご指摘のＣＡＰ、いわゆる子ども暴力防止のプログラムですけれども、これにつきましては、人権概念を通しまして、子どもたちがいじめ、それから誘拐、性暴力など、あらゆる種類の暴力から自分を守る方法を学ぶ参加、体験型のプログラムであると認識しております。","voiceIndex":293,"id":"exchange-131"},{"speaker":"井上委員","kind":"提案","question":"でも、続けることが必要だと思っています。２００７年の決算特別委員会で、私は中学校への拡大を提案いたしました。１９９９年に中学生プログラムも開発され、思春期の子どもを抱える身近な問題が盛り込まれています。改めて、中学校への拡大を提案いたします。２００９年には、ＣＡＰトレーニングセンターが全国２カ所に増えています。ぜひ、中学校への提案について、ご見解を伺いたいと思います。","respondent":"太田指導課長","answer":"そのスタッフをそろえるということも非常に難しいというふうに聞いておりまして、現在のところ、中学生への導入は難しいと考えております。","voiceIndex":295,"id":"exchange-132"},{"speaker":"井上委員","kind":"提案","question":"２００７年に、教育次長が、今、指導課長がお答えになられたような理由で難しいということは、言われております。だから、今私は、全国で、２００９年にはトレーニングセンターもできて、そういうスタッフもいて、子どもたちに対しても必要だということで、改めて提案をさせていただいたわけです。５年生の市民科でも、同様の趣旨を持った授業を実施しています。いかがでしょうか。","respondent":"太田指導課長","answer":"今回の事態も重く受けとめまして、そのご指摘の中身について、研究させていただきたいと思います。","voiceIndex":297,"id":"exchange-133"},{"speaker":"井上委員","kind":"質問・要望","question":"続きまして、先ほど、山元委員からも就学相談のことでお話があって、学校では困難であるというような事例を幾つか出されたということなんですけれども、校外授業で、付き添いを求められたというケースがあったのか。それから、宿泊場所での薬の投薬などは、どのように処理をされているのか、教えてください。","respondent":"太田指導課長","answer":"児童・生徒の健康状況というのは、宿泊行事等環境が変わると心配なところです。投薬については、宿泊行事でも、引率側で対応させていただいている状況があります。個別のケースに対応させていただいているという形で進めております。","voiceIndex":299,"id":"exchange-134"},{"speaker":"井上委員","kind":"質問・要望","question":"付き添いを保護者に求めたというケースはないということでよろしいでしょうか。","respondent":"太田指導課長","answer":"安全を確保するために求めたことはあるです。","voiceIndex":301,"id":"exchange-135"},{"speaker":"井上委員","kind":"質問・要望","question":"それ事態は、本来は、義務教育として、学校側がするべきことだと思うんですけれども、親御さんで、ついてきてくださいと言われて、情報を知らない方は、それに従わなければいけないと思ってしまうかもしれませんけれども、基本的には、付き添いは求めないという原則はあるのでしょうか、ないのでしょうか。","respondent":"太田指導課長","answer":"その子どもによって、状況というのは違うと思うんですけれども、医療的ケアができない場合に、保護者の同行を求めたということで聞いております。","voiceIndex":303,"id":"exchange-136"},{"speaker":"井上委員","kind":"質問・要望","question":"医療的ケアということについて言えば、そういったところに看護師が同行するとか、学校の態勢を整えれば可能だと思いますので、やはり公教育としてしっかりとそこは、心配なことはあるかもしれませんけれども、事前に親御さんと調整をして、原則、付き添いは求めないというところでしっかりと取り組んでいただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"私は、１７４ページ、教育委員会費と、教育指導費についてお聞きしたいと思います。先ほどもお話がありましたが、４名の教育委員の方々は、教育に対する指導を受けてきたのか、それとも、教員のように教育の勉強をしてきたのか、それについてお答えください。","respondent":"齋藤庶務課長","answer":"法制度上、レーマンコントロールという言い方をしておりまして、一定の識見のある方にお願いしております。したがって、教職の経験があるかないか、これは要件となっておりません。","voiceIndex":307,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"未来ある子どもたちに大きな影響を与える教育だと、私は思います。日々、子どもたちは成長して、小・中学生の時期には、体だけではなくて、人格形成にも大きな影響を与えております。でも、実際、子どもたちの今の日常生活、教育に対して、こういういじめ、自殺等も含めて、学習もそうです、生活指導もそうです、進路指導もそうです、大変な分野がある中で、そういう方たちで大丈夫なんでしょうか。","respondent":"齋藤庶務課長","answer":"率直に申し上げて、認識が違うかと考えています。その理由は二つです。一つは学校の現場に必要なこと、教育の現場に必要なこと、学校で何をやっているか、これは教育のプロである教育長が十分に把握しております。","voiceIndex":309,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしますが、この方たちに、子どもの成長過程、日々変わりますよね、子どもって。それから、学習指導、勉強のこと、今の実態はどうなんだ、受験のことはどうなんだ、それから、いろいろ子どものいじめのことはどうなんだ、わかるんですか。実際に、例えば、弁護士なら弁護士、調停云々はわかると思います。それが、バランス取るために一般の方を使っている、それでいいんですか。教えてください。","respondent":"齋藤庶務課長","answer":"そういう意味で言うと、識見のある素人だから、教員経験がないから、我々に対して斬新な意見をいただいているというふうに考えております。","voiceIndex":311,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"もっと前からどうしてやらなかったんですか。私、それを思うんです。ですから私は、やはりそこの選考にあたっては、きちんと考えてほしいと思います。そうではないんですか、例えば課長、部長はつかないかもしれないけれども、一般の方はつくのではないんですか。ですが、僕からすれば、子どもがいる我々からすれば、一人ひとりの子どもたちに、私はもっと触れ合う、向き合う時間に使ってほしいんです。","respondent":"太田指導課長","answer":"先ほど、お話があったように、教材研究をする、それから、地域へ出ていって地域と触れ合う、それから保護者へ対応する、さまざまなことがバランスよく整って、初めて子どもたちへのさまざまなかかわりというのも充実してくると考えています。","voiceIndex":313,"id":"exchange-141"},{"speaker":"須貝委員","kind":"意見","question":"今回の件ではないんですが、やはり教員が忙し過ぎる、それから管理者、校長、副校長、主幹も含めて、やはり忙し過ぎる実態は、なかなか子どもたちに目を向けられない。少なくとも十四、五年前までは、先生は放課後、子どもたちと外で遊んでいました。それは私はまだ鮮明に覚えています。ですが、だんだんそういう時間がなくなった。先生はどこにいるのか。それについては、どう思いますか。","respondent":"太田指導課長","answer":"そういった子どもの状況も踏まえたうえで、そういった放課後の対応等も考えないといけないのかなと思っています。","voiceIndex":315,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区のプラン２１について、お聞きしたいと思います。でも、本来、先生は受け入れた子どもを育てるということに対して十分な力を発揮していくことが、私は大切なことだと思うんですが、そういう多忙な学校をあおって、教員にもプレッシャーがいくというようなことで、もっと教員が子どもたちと向き合う時間をつくるべきではないかと思うんですが、その点についてお聞かせください。","respondent":"和氣学務課長","answer":"格差という言い方をしたくないんですが、学校間の教育力の差は縮まっていると考えております。これは、学校選択制を入れて、各学校が切磋琢磨をしていただいて、それぞれが自分たちの学校の教育力を高めた結果であると考えています。","voiceIndex":317,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"終わりに小中一貫校について、お聞かせください。小中一貫校、２０１２年７月に、文部科学省内の中央教育審議会で、創設はできないことになりましたと、書いてあります。では小中一貫校というのは、学校としては認められない。法に基づいた品川区の小中一貫校は、まだ当面つくれないんですが、それについて、どのようにご見解をお持ちなんでしょうか。その辺について、ご見解をお聞かせください。","respondent":"和氣学務課長","answer":"そういう意味で言いますと、別に違法な学校であるわけでもないですし、文部科学省からもしっかり認知された、そういう意味では先進的な教育として認知をされているものと認識しています。","voiceIndex":319,"id":"exchange-144"},{"speaker":"須貝委員","kind":"意見","question":"学校の設置基準も決まっていて、それに対して、教員免許法からさまざまな法律で縛られて学校というのは成り立っています。でも、現在は、校長１人、副校長３人。その中で、できるだけ早く国に審議してもらって、品川区にもきちんと義務教育校ということでの確立を早く目指してほしいんですが、その辺について、もう一つ、ご見解をお聞かせください。","respondent":"和氣学務課長","answer":"この先、あまりにも全国的な影響が大きいということで、なかなか前に進まない部分がありますけれども、しっかりとさらに要望してまいりたいと考えています。","voiceIndex":321,"id":"exchange-145"},{"speaker":"浅野委員","kind":"質問","question":"１７９ページ、図書館経費から、電算システム運営費、１８２ページ、学校管理費から電算システム・ネットワーク経費、１８６ページ、幼稚園費からは緊急時一斉メール配信システム導入について、質問します。これは、区立図書館と小・中学校の図書館を結ぶネットワークというふうに聞いておりますけれども、こちらのシステム構成と、それから具体的な業務内容について、簡単に教えてください。","respondent":"中元品川図書館長","answer":"学校図書館運営費のほうにあります電算システム・ネットワーク経費につきましても、学校図書館システムのほうのサーバーと、各小・中学校の学校図書館の中に端末を設置していますものと、通信回線等で構成されているものです。","voiceIndex":324,"id":"exchange-146"},{"speaker":"浅野委員","kind":"質問","question":"それなりのシステムだと思うんですけれども、平成２２年度の決算については７,０００万円で、平成２４年度がやはり７,０００万円の予算で、平成２３年度だけ３,０００万円ほど飛び出していますけれども、何か変化とか、そういうのがあったのか、教えてください。","respondent":"中元品川図書館長","answer":"こちらのサーバーにつきましても、普通サーバーというのは５年程度が利用期間ですが、１年更新をして、経費節減を図ったうえでリプレースをさせていただいたというところで、平成２３年度につきましては、その経費が突出していますが、また今後。","voiceIndex":326,"id":"exchange-147"},{"speaker":"浅野委員","kind":"質問","question":"この回数を聞きますと、１億円で、１回幾らぐらいかかっているのかという数字を出してもらえればありがたいんですけれども、こちらのシステムと、同じところで、資料等の運搬費とかありますけれども、図書に関しては、大井町行政サービスコーナーですとか、いろいろなところを回っていると聞いておりますけれども、そちらの業務との連携についても、教えていただければと思います。","respondent":"中元品川図書館長","answer":"貸出し冊数で申し上げますと、小・中学校での学校図書館での貸出し冊数は、平成１７年度は５万２,０００件程度だったところが、平成２３年度の数字で、小・中学校合わせまして６４万件程度の貸出し数というふうに爆発的に伸びているところです。","voiceIndex":328,"id":"exchange-148"},{"speaker":"浅野委員","kind":"質問","question":"例えばクラウドでやるとか、そういうようなことによって、また利便性の高い、使いやすいという、このような動きもできますので、ぜひとも、今後については、この１億円、通常ですと７,０００万円、少しでも低減できるように、またさらに使いやすいシステムなども検討していただければと思いますが、いかがでしょうか。","respondent":"中元品川図書館長","answer":"平成２５年１２月にリプレースを予定しておりまして、現在、サーバークライアント方式という形式ですが、今はもうそういうものはございませんで、ウェブ方式というもので世の中は動いているということで、そういう形での提案をされておりますので。","voiceIndex":330,"id":"exchange-149"},{"speaker":"浅野委員","kind":"質問","question":"ぜひとも使いやすく、また、コストも削減できるような取り組みをお願いしたいと思います。利便性だけは確保していただければと思います。すみません、款は飛びますけれども、幼稚園のことを伺いますと、保育園のほうも聞きたくなりますので、同じ質問を、保育園のほうも教えていただければと思います。","respondent":"立川保育課長","answer":"登録数なんですけれども、保育園・幼稚園含めまして、全体で、今，４,５９３件です。","voiceIndex":332,"id":"exchange-150"},{"speaker":"浅野委員","kind":"質問","question":"家庭数と登録の総数というふうに伺ったんですけれども、その数が、本来の家庭数とほぼ合致しているのか、それとも申し込まない方もおられるのかどうか、ということについてお伺いします。","respondent":"立川保育課長","answer":"ちょっと手元に合計の数字しかないんですけれども、公立保育園、公立幼稚園合計で、ほとんどのご家庭でご登録いただいているという状況です。すみません、ちょっと細かい数字を持ち合わせおりません。","voiceIndex":334,"id":"exchange-151"},{"speaker":"浅野委員","kind":"質問・要望","question":"実際に利用したケース、本来ですと、例えば、災害が発生したときとか、そういうことをある程度想定しながら、私も要望したものですけれども、実際に災害等で使われたことがあるのか。使われなかったとしても、それ以外にいろいろな場面で使われるケースがあると思いますが、ここら辺のことについては、どのようなケースをお考えなのか、教えてください。","respondent":"立川保育課長","answer":"使い方につきましては、保育課のほうから、園のほうから、あとは例えば不審者情報とかがありますと、該当する地域の保護者に、そういった情報を、ある意味ピンポントでお知らせしたりとか、そういうことで活用しています。","voiceIndex":336,"id":"exchange-152"},{"speaker":"浅野委員","kind":"質問","question":"不審者情報ですとか、そういうようなことにも、当然、使われていると思うんですけれども、それ以外に、普通の連絡というのでしょうか、そういうことでも活用されているのか、この点についてお伺いします。","respondent":"立川保育課長","answer":"原則は、あくまでも緊急時の対応ということで配信をしています。","voiceIndex":338,"id":"exchange-153"},{"speaker":"浅野委員","kind":"質問・要望","question":"たまに流さないと、これは何のメールかなということもあり得ると思いますので、ここら辺は、保護者のほうとうまく相談しながら、要望なども踏まえながら、さらにいいシステムにしていっていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-154"},{"speaker":"大沢委員","kind":"質問","question":"１７４ページ、教育総務費、それから教育指導費で、プラン２１推進事業、それから、先ほど向委員の質疑の中でやりましたことを、最初に１点、質問します。先ほど、学校の先生の避難所としての役割分担云々という話がありました。教育委員会みずからここのところは答弁すべきだと思うんですけれども、そこのところ、なぜああいうことになったのか、教えてください。","respondent":"齋藤庶務課長","answer":"平時、休日、三期休業期間、どのような対応をするか、こういったマニュアルはありますけれども、どういう役割分担、学校避難所を設営して、学校の職員にかかっていくか、こういった点を含めまして、現在、検討中でございましたので、防災課長よりご説明申し上げました。","voiceIndex":342,"id":"exchange-155"},{"speaker":"大沢委員","kind":"意見","question":"そこまで庶務課長がおわかりなのであれば、庶務課長がやはり答弁をすべきないかと思いますが、いかがか。","respondent":"齋藤庶務課長","answer":"行政には、司、司がありますので、防災課長よりご説明申し上げました。","voiceIndex":344,"id":"exchange-156"},{"speaker":"大沢委員","kind":"質問・要望","question":"司と来られれば、もうこれ以上のことはお話しできませんので、司で十分に理解をします。次に、プラン２１ということで、先ほど来、うちの会派でも、いろいろと質疑がありました。あえて、この２点、この短い時間では全ての説明はしがたい、不可能だと思いますけれども、簡単で結構ですので、公教育の復権ならびに信頼回復ということで、ちょっとご説明いただきたいと思います。","respondent":"和氣学務課長","answer":"その意味で、私どもは、どの公立学校に行っても、しっかりした高い水準の教育が受けられる、これを保障していく、このことを目標に頑張っているところです。","voiceIndex":346,"id":"exchange-157"},{"speaker":"大沢委員","kind":"提案","question":"高校におきましては、都立は重点校をつくったりと、いろいろな部分で、学力向上に向けた取り組みをしております。確かに、義務教育と高校は、教育のあれは違いますけれども、公教育の最終到達点、公教育の復権ということを、ぜひとも実現、まだ道半ばですけれども、教育委員会の方は皆さん協力をしていただいて、公教育の復権をお願いしたいと思いますが、いかがでしょうか。","respondent":"和氣学務課長","answer":"先ほども申し上げましたけれども、お金のある子は私立でいい教育が受けられるというような社会構造を、どうしても私どもは座視できないです。","voiceIndex":348,"id":"exchange-158"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひとも、お願いをいたします。次に、手引書について、ちょっとお伺いします。朝、長い朗読がありましたので、私の場合は、短く朗読させていただきたいと思います。ここの友達親子、友達先生、本区においては、教育委員会はしっかりと対応されていると思いますけれども、友達親子について、どのように受けとめて、どのように、今後対処をしていかれるのか、ご見解があったら教えてください。","respondent":"太田指導課長、若月教育長","answer":"そういうことを考えれば、友達教師というのが、ちょっとどういうことかというのが詳しくはわからないんですけれども、ただ、今申し上げたように、その場その場できちっと場をわきまえて対応するというような関係、それから。特に友達親子に対して、どうアプローチをしていくのかというご指摘でしたが、これは大変難しい。こちらが問題意識を持っていても、なかなかそこら辺を微に入り細にわたり介入していくことは、事実上困難であります。","voiceIndex":350,"id":"exchange-159"},{"speaker":"大沢委員","kind":"質問・要望","question":"教育長からご答弁をいただけるとは思わず、ちょっと。最後の質問にいきます。教育長に改めて問わせていただきたいと思います。いろいろな部分で、他から評価をされ、また評価の裏腹に、いろいろなものがあるとは思いますけれども、品川区の教育、教育長たるもの、パイオニアとして、そのポートレートをどのように描かれて、今後、品川区の教育行政を担っていかれるのか、改めてお伺いしたいと思います。","respondent":"若月教育長","answer":"そのためにやっています。これでいい、ここに到達したと思った瞬間に全てがとまる。したがって、常に慢心することなく、いつもみずからがみずから、まだ足りない、まだ足りない、こうした姿勢で、これからも品川区の教育行政を、教育改革を進めていきたい。","voiceIndex":353,"id":"exchange-160"},{"speaker":"大沢委員","kind":"質問","question":"款別審査の最後になりますけれども、今、さまざま起こっている問題、今日はプレスも聞いていますでしょうけれども、いじめをはじめとする教育に関する問題、品川区教育委員会、そして先生方、情熱を持っていると、僕は確信しています。必ずやこの問題は解決できることを確信して、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-161"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1366#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":110170,"voices":356}},{"id":"h24-20121016-4","meetingId":"h24-c-settlement","date":"2012年10月16日","dateIso":"2012-10-16","committee":"決算特別委員会","time":"午後５時１９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を108件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"都区制度の現状と課題について伺いたいと考えています。その中で改めて都区のあり方検討、そもそもどういう意義があって始めていたのか、これをまず伺いたいと思います。それから、都区のあり方検討委員会幹事会の協議で、区へ移管の方向で合意した５３項目の現状と特に児童相談所の移管に向けた協議の状況についても改めて伺いたいと思います。","respondent":"濱野区長","answer":"今石田秀男委員からのご質問のとおり、この都区のあり方検討委員会幹事会というのは平成１９年の１月からスタートいたしまして、都合２９回開催をいたしました。","voiceIndex":2,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"今お話を伺いましたけれども、そういう形の中で３月１６日に地方制度調査会が行われて、その中で特別区長会の会長の西川荒川区長が都区制度の現状について強く問題点を指摘をしたということでありまして、その中でも特に都は上から目線でいまだに区を内部団体と見ている感があるという形の発言をされていますけれども、その発言。","respondent":"濱野区長","answer":"区域の話が都区のあり方検討委員会の後半からどんどん出てきたわけでありますけれども、私も委員と同感で、これは論外なところでありますし、こういう都区のあり方検討委員会の中で議論をするようなたちのテーマではないのではないかと思って。","voiceIndex":4,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"まあ、これはちょっとだめだったわけだけれども、だけど、この精神というのは私は今こそもう一度、区長からも発言していただいたり、どこかでやっていくということを考えるのであれば、高橋区長は品川の前区長でもありますし、そこの今の考え方というのは、今も、今濱野区長としてやはりお持ちなのか、そういう考え方が生きているのかというところも改めてお伺いをしたいし、それから。","respondent":"濱野区長","answer":"この間、主要５課題、あるいは都区のあり方検討委員会の中で、東京都側の主張としては、これは東京都の条例で決まっていることだから、それは法定、要するに条例や法律で決まったことは、決まっている以上、都の財源なんだということでお話しされておりますけれども。","voiceIndex":6,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"後期の５年間の見直しとするのか、人口推計などを考えると、私はここから１０年ぐらいが非常に大切と思っておりまして、１０年を見通した改定も必要と考えますが、改めてお考えを伺います。区議会の意見反映についてもどう考えているのかも伺いたいと思います。あわせて実施計画も出されるわけですから、それとの整合性についてもどういうふうに今お考えになっているのかもあわせて伺います。","respondent":"日下部企画部長","answer":"検討の手順です。現在人口推計、それから世論調査ということで基礎的な調査を進めておりまして、今後は庁内の検討組織で、課題、それから論点の整理などを行いまして、来年度には改定のための検討委員会を立ち上げてまいりたい、このように考えております。","voiceIndex":8,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから長期基本計画でやはり区の考え方を出していただくのであれば、これは取り組んでいただきたいのは、区って必ず申請主義であって、手を挙げてもらうという形がもともとある方式だと思いますけれども、逆にすべての方に手を挙げてもらう場面をつくって、その中で逆に手を下げてもらう申請をしてもらう。","respondent":"日下部企画部長","answer":"せっかくの機会でもありますので、今ご提案のような形で今後また検討を進めていく、これも非常に重要なことだろうと、このように考えております。","voiceIndex":10,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。最後の部分だけ、手を挙げる方式と手を下げる方式、ここの部分だけ要望します。そういう発想に、今までの考え方は逆なもの、それも長期基本計画の中で、区としてはこういう形でいくんだ、そういうことを打ち出すことが１人でも多くの命が守れると私は考えておりますので、これは要望としますが、これはぜひ検討していただきたいなと思います。跡地活用について伺います。","respondent":"日下部企画部長","answer":"一時的な移転の場所の確保ということが非常に重要な課題になってまいりますので、これに適した用地をどのような形できちっと確保していくか。今後重要な課題として検討をしっかりと進めていく必要があるだろうと、このように考えています。","voiceIndex":12,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"そう考えると、もちろんこの点については、跡地活用をするということは財政負担も大きくなるということであります。それから、例えばこういう仕分けをもちろん行政側は今やっていると思うんだけれども、こういう部分の、やっているか、やっていないかの状況とか、もちろん考え方、これを改めて伺いたいと思います。","respondent":"日下部企画部長","answer":"跡地活用の仕分けですけれども、申し上げるまでもなく、それぞれの跡地につきましては、新しく取得することが非常に難しいというような区民の共有財産ですので、そういった点では、地域の特性とか立地条件はもとより、有効活用を図るべき時期とかタイミングにつきましても。","voiceIndex":14,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"提案","question":"有効活用を図る部分でいうと、今求められている二つだけ言います。そう考えると、私は以前から品川児童学園の複合化について提案をしていますので、それについての今後の見通しを伺いたいのと、老健施設も、これは必ず区も１カ所やるって公言しているわけで、条件がそろう土地があれば建設すると言っているわけでありまして、それの進捗状況もあわせて伺いたいと思います。","respondent":"日下部企画部長","answer":"老健施設につきましては、これは計画上の位置づけもありますし、その実現に向けて鋭意努力をしています。今後はできる限り速やかに計画の実現を図れるように、さまざまな角度からさらに検討を進めてまいりたいと、このように考えております。","voiceIndex":16,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"しっかり有効活用、まあ、跡地は限られているわけでありますから、ぜひ実現に向けてやっていただく、検討していただきたいなと考えています。次に、決算について伺います。そういう観点から、現在の決算をどう評価し、今後の予算編成に、こういう心配ごともあるわけですから、どう反映していこうとお考えになっているのか、お伺いしたいと思います。","respondent":"本城企画財政課長","answer":"このような決して予断を許さない財政状況の中で、予算編成に当たりましては、事務事業評価の徹底などを通しまして、役割を終えました事業については廃止、縮小し、コストを削減する一方で、新たな喫緊な行政ニーズには的確に対応していくという。","voiceIndex":18,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"その中でぜひこれだけは伺いたいんですが、将来の財政需要に備えた基金の積み増しが私は必要だと考えています。今後どの程度積み増すか、金額目標も含めて、私はやはり検討していくべきだと思いますので、そこら辺の考え方を改めて伺いたいと思います。","respondent":"本城企画財政課長","answer":"基金の積み立ての目標について、現在具体的な数値目標を設定しているものではございませんが、今後公共施設のあり方を検討する中で、将来の改築需要等を見込んで、それに見合った基金の積み立てを計画的に行ってまいります。","voiceIndex":20,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひよろしくお願いします。最後に受益者負担で伺います。私は現状に対する評価と課題、施設使用料のことについて伺いますけれども、あわせて減免制度の目的と基本的な考え方、それから、減免制度の現状と実績、そういうどのような団体でどのような施設でどのような減免対象になっているのか、現状に対する評価と課題、施設使用料でいいんで、そこだけ教えてください。","respondent":"日下部企画部長","answer":"したがいまして、減免制度の適用範囲があまりにも広いということになりますと、負担の公平を損なうということにもなってまいりますし、本来は区民の皆さん方にとってできるだけわかりやすく、誰から見ても納得の得られるような範囲に限定をするということが望ましいと。","voiceIndex":22,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最後にこれだけ伺います。減免制度を含む施設使用料の現状と課題とか問題点を改めて検証していただいて、あり方を検討するべきと私は考えておりますので、最後にその点の考え方だけお聞きかせいただきたいと思います。","respondent":"日下部企画部長","answer":"これらの点を含めまして、減免制度を含む施設使用料の現状についてしっかりと検証いたしまして、今後のあり方については検討を進めてまいりたいと、このように考えております。","voiceIndex":24,"id":"exchange-012"},{"speaker":"本多委員","kind":"質問・要望","question":"初めに教育について、いじめを中心に伺います。質問いたします。調査対策委員会の委員の構成は現時点でどのようになっているのでしょうか。委員会の構成で特徴的なことはあるのでしょうか。報告書の完成時期はいつごろを考えているのでしょうか。人の命が奪われたこのような場面で出席停止制度を適用しないのであれば、適用する機会が失われてしまうのではないでしょうか。","respondent":"若月教育長","answer":"その報告書についてのご質問ですけれども、事務局ではまず当該校の今回の件に関する第１次の報告をまとめていきたいと考えておりますけれども、この報告書を取りまとめていく、その手順等々につきましても、今後は。","voiceIndex":27,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"次の質問に移ります。次に民間活力の活用にかかる区の考え方を伺います。そして、事務事業評価結果の図書館窓口等業務委託については、評価結果Ｃの見直しで、質の高い図書サービスを効率的に提供できるように運営主体を含めた検討を進めるということですが、既に２３区でも導入しているところがあります指定管理者制度の導入も視野にあるのでしょうか、その点についてもお聞かせください。","respondent":"田村教育次長","answer":"現在２３区の中で品川区を含む１２区が窓口等の業務委託契約、１０区が指定管理者制度による運営形態を導入しております。それぞれの制度にはメリット、デメリットがあると考えますが、指定管理者制度を含めて、今後のあり方について検討してまいります。","voiceIndex":29,"id":"exchange-014"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ状況、伺いまして、ありがとうございました。次の質問に移ります。保育園について伺います。こうした取り組みの継続の先に幼児人口のピークが平成２７年度との推測があり、それ以降の福祉職としての人材のあり方や配置計画について現時点での見通しをお知らせください。","respondent":"桑村総務部長","answer":"毎年大体退職が三十数名出るのが普通ですので、基本的には採用抑制で対応するというのが基本だろうと考えています。なお、もちろん配置転換という形での福祉職としてほかの職場へ行くというようなことも必要に応じて対応してまいりたいと考えているところです。","voiceIndex":31,"id":"exchange-015"},{"speaker":"本多委員","kind":"質問","question":"福祉職としていろんな可能性があるということでいいんでしょうか。それと、平成２７年度のピークが過ぎた後のシミュレーション、細かい数字とかではなくて、シミュレーションと人のバランスというのは、計画的にやっているか、やっていないかだけで結構なので、その辺の見通しだけお知らせください。","respondent":"金子子ども未来事業部長","answer":"平成２７年度ピークというのは従前の見込みでありまして、先ほど企画部長からも話がありましたとおり、現在長期基本計画の改定を進めている中で、乳幼児人口動向の今後の見通しも調査しております。","voiceIndex":33,"id":"exchange-016"},{"speaker":"本多委員","kind":"質問","question":"人口の動向ですとか長期基本計画の見直しや事業の見直しによって一緒に考えていくというふうに受け取りました。次に、認証保育所を認可保育園に準じる児童福祉施設と位置づけ、認証保育所を利用中の保護者の経済的負担が認可保育園に通園した場合とほぼ同等となるよう、保育料助成金の交付がありますが、公私の格差について伺います。課題などについてもお聞かせください。","respondent":"金子子ども未来事業部長","answer":"公立の場合はありませんので、これを区負担ということで比較してみますと、これも粗い計算ではありますが、区立のほうが私立のほうよりも１.８倍ほど経費がかかるというふうな試算を出しています。","voiceIndex":35,"id":"exchange-017"},{"speaker":"本多委員","kind":"意見","question":"経費と人件費の本当にウエートが高いんだな、この辺はしっかりと常に着眼をしていきたいと思います。次に、子ども・子育て関連三法の中で、施設構成や運営方法などについて、今後の保育園のあり方についてどのようなお考えなのか。ぷりすくーる西五反田同様の指定管理者制度などの考え方についてお聞かせください。","respondent":"金子子ども未来事業部長","answer":"今後、待機児童対策とともに、保育園のあり方を含めて、この制度改正全体について区の進め方を検討していかなければならないと考えています。","voiceIndex":37,"id":"exchange-018"},{"speaker":"本多委員","kind":"質問・要望","question":"福祉人材の確保について伺います。そして、品川介護福祉専門学校の長所でもある少人数制で一人一人を大切にするアットホームな雰囲気、１学年４０名の少人数制で、学生アンケートで、少人数制がよい、明るく楽しい雰囲気と約６割の学生が回答していますが、現行の少人数制を用いての定員拡大や規模、キャパシティーなどの点について考え方をお聞かせください。","respondent":"早津健康福祉事業部長","answer":"今の学校の施設規模からしても、１学年４０名で２学年制の８０名というのが大体適当ではないかと考えているところです。","voiceIndex":39,"id":"exchange-019"},{"speaker":"本多委員","kind":"質問・要望","question":"この講師をお願いするケースなんですが、品川の介護に理解を示してくれるということは当たり前のことだと思いますので、その辺もう少し具体的に、こんな取り組みをやっているとかあれば教えていただきたいと思いました。それと、定員のほうは、学生のほうの定員については、現行どおりというふうな答弁いただきました。わかりました。その最初のほうだけ、講師のことだけもう一度お願いいたします。","respondent":"早津健康福祉事業部長","answer":"そういった方にもお声をかけて講師の中に加わっていただいているというような事情もあります。","voiceIndex":41,"id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"次の質問に移ります。品川区就学資金貸付制度で、最大で２年間授業料相当額１２０万円を借りることができ、３年以上品川区指定の施設で介護業務に従事すると、借り受けた就学金の返済義務が免除されます。この制度を約９割の学生が使っています。誰にでも介護のプロを目指せるこの制度の存続と、３年と言わず、品川での介護業務の継続的な取り組みについてお聞かせください。","respondent":"早津健康福祉事業部長","answer":"一つだけ項目を申し上げますと、介護の仕事を進める上で新しい知識、スキルの習得に役立ったということについて、８３％の方が役立ったというような答えをしております。かなりの成果が見られているのではないかと感じているところです。","voiceIndex":43,"id":"exchange-021"},{"speaker":"本多委員","kind":"意見","question":"成果があるということで、非常によかったなと思います。介護福祉専門学校でのケアマネジャー受験のための講座とＮＰＯ法人品川ケア協議会と品川区との協働により、ホームヘルパー２級講座の実施結果、成果や今後このようなＮＰＯ法人などとの活用、連携について考え方をお聞かせください。","respondent":"早津健康福祉事業部長","answer":"本年度も実施するものです。それからＮＰＯ等との連携ですが、ＮＰＯ法人につきましては、得意分野や、それから持っておられる能力等を見きわめた上で、どんなことが可能であるのかということを検討してまいりたいと考えています。","voiceIndex":45,"id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"やり方をどんどんどんどん工夫をして、ホームヘルパー２級講座ということで、こういう新しいやり方を活用して、あと、この民間活力の活かせる方法を常に考えていっていただきたいと思います。それで、現役で働くケアマネジャーの退職に伴う影響ですね。","respondent":"早津健康福祉事業部長","answer":"ケアマネジャーの退職の件ですが、まず実績のほうを申し上げますと、区内の在宅介護支援センターに約１５０名のケアマネジャーが勤務しております。","voiceIndex":47,"id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"人材の確保につきましては、先ほどから出ています人口動態ですとか、長期基本計画の見直しや事業の見直しと絡んでくると思いますので、ぜひ工夫をして進めていっていただきたいと思います。次にがん検診受診率向上について伺います。以前国民のがん検診受診率を５０％に引き上げるため、国家プロジェクトとしてがん検診企業アクション、厚生労働省の受託事業が発足しました。","respondent":"早津健康福祉事業部長","answer":"その事業を実施する中で得たノウハウ、ポスターやチラシの作成の方法とか、各種のノウハウをがん検診の啓発事業にもこれから使っていきたいと考えているところです。","voiceIndex":49,"id":"exchange-024"},{"speaker":"本多委員","kind":"質問・要望","question":"民間活力についてそれぞれお聞きしましたけれども、総括的に企画部のほうで感想や思いがあれば伺いたいと思います。最後に一つだけ聞きますけれども、指定管理者制度を用いるときに、プロポーザル方式と特定事業者を選定する二者がありますけれども、これはやはりプロポーザル方式を使っていただきたいと思います。その点についてお聞かせください。","respondent":"日下部企画部長","answer":"それから指定管理者の選定につきましては、基本的にはやはり選定に当たって公平を期すということもありまして、プロポーザル等の手法を私どもとしても最大限有効に活用していますので、今後ともその辺の基本的な考え方はしっかりと持って進めてまいりたい。","voiceIndex":53,"id":"exchange-025"},{"speaker":"阿久津委員","kind":"質問","question":"私からはいじめ問題と認知症対策の２点について質問いたします。初めに、いじめ問題について伺います。守ってあげられなくて、本当にごめんなさい。いじめ問題に臨むに当たっての品川区としての認識と決意を伺います。しかし、この世界にいじめられてよい人間が一体どこにいるのでしょうか。本区に伺います。本区のいじめに対する認識、またこの問題に対応するに当たっての決意をお伺いします。","respondent":"若月教育長","answer":"いじめにつきましてのご質問ですが、いじめといったようなものには、単にいじめがあるとか、ないとかという考え方をするのではなくて、その問題とされる行動が、人権侵害行為。","voiceIndex":57,"id":"exchange-026"},{"speaker":"阿久津委員","kind":"提案","question":"教育長の強い決意、伺いました。子どもたちへの日常のご指導よろしくお願いしたいと思います。次に、いじめに対する教職員の対応について伺います。あわせて、品川区の教職員がいじめの手法や心理についてさらに理解を深め、情報を共有するため、いじめ問題に対応した経験を持つ教員がいじめの実例と解決までのプロセスを報告する実践報告大会の開催を提案しますが、本区のご所見を伺います。","respondent":"若月教育長","answer":"したがいまして、この実践報告大会につきましては、今後の検討課題とさせていただきたいと考えているところです。","voiceIndex":59,"id":"exchange-027"},{"speaker":"阿久津委員","kind":"確認","question":"学校での信頼関係の醸成について伺います。教育の原点は信頼であり、信頼が存在しないところに教育は存在しない。その意味で私は品川区の学校が平和で安全な場所なのかどうか、再確認する必要があると考えます。教職員と児童・生徒の間に信頼関係を醸成するため、本区は今までどのような取り組みをされてきたのか、また今後どのように取り組まれるのか、ご所見を伺います。","respondent":"若月教育長","answer":"今年度、平成２４年度からですが、土曜日授業を実施いたしまして、そのことによって平日の６時間授業を減らすことで教員が子どもと触れ合う時間の確保をより多くしようというようなことも考えてきた、そして実践をしてきたところでもあります。","voiceIndex":61,"id":"exchange-028"},{"speaker":"阿久津委員","kind":"質問・要望","question":"教員の資質向上のためのさまざまな研修について伺いました。信頼醸成の取り組みについても今教育長から伺いました。ただし、事実関係の解明を待っている間にも、多感な思春期の真っただ中である児童・生徒の中には、ショックを受け、精神的、肉体的に不安定となっている子どもが多くいると考えられますので、早期のしっかりした精神的なケアを行っていただきたいと考えますが、本区のご所見を伺います。","respondent":"若月教育長","answer":"生徒の精神的なケアについてのご指摘がございました。教育委員会では都に臨床心理士の派遣を要請いたしまして、１０月３日から５日にかけまして当該学年の全生徒および被害生徒との関係のあった他学年の生徒に対してのカウンセリングを実施したところです。","voiceIndex":63,"id":"exchange-029"},{"speaker":"阿久津委員","kind":"質問","question":"私自身も認知症に関係するご相談やお話を伺う機会が大変多く、さらなる認知症対策の必要性を実感しております。品川区は成年後見センターの活用や本人の意思を尊重したケア手法であるセンター方式を先駆けて採用するなど、認知症に対して一歩進んだ取り組みをしてきたことは承知をしておりますが、改めてこれまでの主な取り組みと平成２３年度はどのような認知症対策に取り組んでこられたのか教えてください。","respondent":"早津健康福祉事業部長","answer":"在宅介護支援センターを２０カ所つくったこと、あるいは保健センターによる心の相談事業の実施等がこれに当たるかと考えています。平成２３年度の取り組みです。家族の方への支援といたしましては、介護者教室、あるいは介護者同士の懇談会の開催等を行いました。","voiceIndex":65,"id":"exchange-030"},{"speaker":"阿久津委員","kind":"質問・要望","question":"今後認知症サポーター、またサポーター養成講座の講師を努めるキャラバン・メイトを増員されるお考えはあるのでしょうか。数値目標があれば教えてください。品川区においても、地域の見守り、支援等の協力を行う認知症サポーターを活用した仕組みを新たに推進していただきたいと考えますが、本区のご所見を伺います。本区のご所見を伺います。","respondent":"早津健康福祉事業部長","answer":"ただ、制度化するということになりますと、役割をどうするかというような難しい面もあろうかと思われますので、まずは地域の子どもも含めた認知症高齢者への理解を深める機会を増やしていく、そのような工夫をしていこうと考えておるところです。","voiceIndex":67,"id":"exchange-031"},{"speaker":"阿久津委員","kind":"質問・要望","question":"次に認知症の相談窓口について伺います。品川区でも高齢者福祉課や在宅介護支援センター、また保健センター等で個別の相談を受けておられると思いますけれども、認知症の本人、家族の側に立ったモデル地区となるべく、例えば匿名の電話でもじっくりまたゆっくりと認知症の相談を受けられるような電話相談窓口の仕組みをつくっていただく、またその周知が必要だと考えますが、本区のご所見を伺います。","respondent":"早津健康福祉事業部長","answer":"認知症高齢者の増加に対応するために相談窓口についてもこの間さまざまな対応をしてまいりました。具体的には、先ほど申し上げました２０カ所の在宅介護支援センター、あるいは保健センターにおきましても相談等を行っているところです。","voiceIndex":69,"id":"exchange-032"},{"speaker":"阿久津委員","kind":"質問・要望","question":"最後に、これからの認知症対策について本区の考え方を伺います。先日現場のケアマネジャーから認知症の方の次のようなご意見をお聞きしました。それ以後、会話の中で無視をされてしまう。今後、高齢者の在宅支援策を進める過程で、認知症の方の尊厳を守るという、この考え方が最も重要であると考えますが、本区の見解を伺います。今後、認知症についてどのような対策をお考えなのか、本区のご所見を伺います。","respondent":"早津健康福祉事業部長","answer":"今後の認知症への対策ですが、介護保険事業計画第五期を作成いたしましたが、この中でも認知症高齢者ケアを総合的に進めていくために、福祉、保健、医療の連携の推進以下、５項目の方策を掲げております。この方策を確実に着実に進めてまいりたいと考えております。","voiceIndex":71,"id":"exchange-033"},{"speaker":"阿久津委員","kind":"意見","question":"必ず必要となるこの認知症対策、ぜひ拡充のほう、よろしくお願いしたいと思います。以上で、私の総括質疑を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-034"},{"speaker":"浅野委員","kind":"提案","question":"阿久津委員に続いて総括質疑をします。初めに、燃え広がらない、燃えないまちづくりについて質問します。そこで、現時点における都との整備プログラムの協議状況についてお伺いします。都としては５０地区程度を想定していると伺っておりますが、この募集についての考え方についてわかる範囲で教えてください。以上、この質問につきましてのお考えをお伺いします。","respondent":"松代防災まちづくり事業部長","answer":"３点のご質問ですが、まず現時点での整備プログラムに関する東京都との協議状況につきましては、９月から２週間に１回の頻度で都と区の実務者レベルで連携を図り、区が提案した支援メニューにつきまして、さまざまな面から検討している状況です。","voiceIndex":75,"id":"exchange-035"},{"speaker":"浅野委員","kind":"質問・要望","question":"今ご答弁いただきました積極的に進めていくという言葉をぜひとも信じておりますので、積極的な取り組みをお願いしたいと思います。本区として木密地域の改善のために、この制度、三項道路の制度を検討したことがあるのかどうか、お伺いします。燃え広がらないまちづくりのために積極的にこのような三項道路などの活用を求めますけれども、本区としてはどのように考えているのか、お伺いします。","respondent":"片田都市環境事業部長","answer":"品川区のほうとしては、確かに荏原地区を含めて、二項道路多くありますけれども、現時点でこれを過去において検討してきた経過はございません。ただ、東京都などでは、細い街路に面して歴史的な価値を有する街並みを保全するという目的で入れているところもあります。","voiceIndex":77,"id":"exchange-036"},{"speaker":"浅野委員","kind":"質問","question":"空き家対策およびごみ屋敷対策について質問します。区内の空き家につきましては、平成２０年の総務省住宅・土地統計調査によりますと、一戸建ての老朽空き家は５９０戸あるとされていますが、本区として調査などを実施して把握をしたことはあるのか、お伺いします。空き家の実態調査を早急に実施すべきと考えますが、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"行政として私有財産にどこまで介入できるかといった課題もあります。区としては全般に実態調査を行うということではなくて、引き続き区民の方から寄せられた情報を参考に個別に慎重に調査をしていく考えです。","voiceIndex":79,"id":"exchange-037"},{"speaker":"浅野委員","kind":"提案","question":"空き家対策については、公明党としてもこの条例の制定などを提案してきました。そこで、これらの支援策の実施に合わせて、改めて仮称空き家の適正管理条例の制定を要望します。その際には、先ほどの支援策を区の中の木密すべてで実施をするように都に要請するとともに、条例の実効性を高めるために、行政代執行の可能性も含めたこの条例の制定を要望しますが、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"条例化しても問題の根本的な解決は困難と考えておりますが、既に条例化した自治体もありますので、それぞれの成果を見ながら、見据えながら、関係課とも連携を図りながら区としても研究を図ってまいりたいと、このように考えております。","voiceIndex":81,"id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"この空き家と同じように、ごみ屋敷、こちらについても対策が必要だと考えております。なお、最近では、やはり足立区ですけれども、ごみ屋敷改善の支援および行政代執行を含めた対策として、足立区生活環境の保全に関する条例案を来年１月からの施行に向けてこのたびの定例会に上程したと伺っております。あわせて、区民の安全・安心のために踏み込んだごみ屋敷対策を求めますが、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"ただ、踏み込んだ対策ということにつきましても、ごみではなく自分にとっては価値のあるものだとおっしゃるような方もありますので、いろんな考え方があると考えていますので、区としては、条例化を定め。","voiceIndex":83,"id":"exchange-039"},{"speaker":"浅野委員","kind":"質問・要望","question":"今ごみ屋敷が６軒、また５軒というお話を伺いましたけれども、私の頭の中で見ますと、その半分ぐらいはすぐ思いつく次第でございまして、少ないと見るか、またそれが多いと見るかというのは、近くの方はとんでもないと思われているわけでありますので、その住民の身になって、今ご答弁いただいたように、しっかりと粘り強く、まずは話し合いから、そして何とか理解をしていただいて、片づけられるような。","respondent":"松代防災まちづくり事業部長","answer":"昨年度の住宅・建築物耐震化支援事業の予算執行率が低かった点についてです。主な原因としましては、助成金額が高額なマンションの耐震改修の実績がなかったことや４月から制度を始めた耐震除却助成の申請がなかったことなどによるものです。","voiceIndex":85,"id":"exchange-040"},{"speaker":"浅野委員","kind":"提案","question":"改定に当たりましてしっかりとしたこの目標と、そしてそれを断固やり切るという、そういう姿勢で臨んでいただきたいと思います。マンションの耐震化につきましては、述べ床面積が１,０００平米以上、かつ３階以上との制限があります。この制限も撤廃して耐震化を推進することを提案してきましたが、これらの施策についても耐震改修促進計画に明記して推進することを要望いたしますが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"区内緊急啓開道路の小規模マンションの件数調査を行い、助成制度および耐震改修促進計画への明記について検討してまいります。","voiceIndex":87,"id":"exchange-041"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも実効性のある耐震改修計画、進めていただければと思います。耐震化の推進に当たっての都と区の役割分担について教えてください。対象となる建築物の棟数と現在までの進捗状況についてお伺いします。都と協力してさらに耐震化の周知に努めるなど、積極的に推進することを要望しますが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"都と協力した助成制度の周知徹底および耐震化の積極的な推進につきましては、周知についてこれまでも区と東京都で連携して個別訪問を行っているところです。今後も協力して耐震化にしっかりと取り組んでまいります。","voiceIndex":89,"id":"exchange-042"},{"speaker":"浅野委員","kind":"質問","question":"こちらのほうも道路は重要な生命線ですので、しっかりと進めていただければと思います。震災時には道路に看板や電柱等の倒壊など、障害物が散乱することが予想されます。改めまして、この緊急啓開道路の果たす役割についてお伺いします。緊急啓開道路の点検整備などは他の一般道路以上に手厚く実施しているのかどうかについてもお伺いします。","respondent":"松代防災まちづくり事業部長","answer":"緊急啓開道路の路線数と総延長についてですが、国道が４路線１５キロ、都道１６線約２６キロ、区道１６路線約１６キロです。緊急啓開道路の点検整備につきましては、主要な区道の路線の中に含まれており、基本的に１カ月に一度程度点検を実施しています。","voiceIndex":91,"id":"exchange-043"},{"speaker":"浅野委員","kind":"質問・要望","question":"さきの一般質問でも公明党が、道路下の空洞により震災時に道路が陥没することによって通行できなくなってしまうことを避けるため、特に緊急啓開道路の空洞調査を実施することを要望しました。道路の陥没の危険性についての本区の認識を改めてお伺いします。あわせて、早急に緊急啓開道路の空洞調査を実施して、必要に応じて対応することを要望いたしますが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"区道の緊急啓開道路に関する空洞調査は、予防的対応としての一つの手法であると考えております。したがいまして、この調査手法について調査検討を現在行っているところです。","voiceIndex":93,"id":"exchange-044"},{"speaker":"浅野委員","kind":"質問","question":"ぜひとも予防的な観点から道路を守る取り組みをこれからもしっかりと進めていただければと思います。今回は、木密対策、空き家、ごみ屋敷対策、また、道路の件について質問させていただきました。まだまだ多くのこの耐震に向けては項目があります。以上をもちまして区議会公明党の総括質疑を終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在全国で流行している風疹についてお尋ねいたします。７月１２日付で東京都福祉保健局からも都内における風疹患者の急増についてという注意の呼びかけが行われました。潜伏期間は２週間から３週間と長めです。以上、簡単に風疹をまとめてみましたが、まず２点質問いたします。品川区の風疹の流行状況はいかがでしょうか。第二に、重症になることが少ない風疹の流行がなぜ今問題になっているのでしょうか。","respondent":"矢野品川区保健所長","answer":"風疹の流行ですが、風疹につきましては、診断した場合、全数報告することが義務づけられております。２月、５月と１例ずつ報告がございましたが、７月には週に三、四人の発生が見られました。現在は少し落ちついてきておりまして、週に１名発生するか、しないような状況です。","voiceIndex":98,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私のところでもことしはまだ１例も風疹の経験はありません。しかしながら、一方、大人がかかると、高熱が１週間ぐらい続いたり、発疹がひどかったり、血がとまらない紫斑病や脳炎を合併することがあります。そこで質問いたします。今回の風疹の流行の特徴は何なのでしょうか。患者の年齢、性別などはいかがでしょうか。第２に、その原因としてはどのようなことが考えられるのでしょうか。","respondent":"矢野品川区保健所長","answer":"なぜこの年代に多いかですが、この年代の男性の方は予防接種制度の転換期に当たり、ワクチンを受ける機会がなかったり、あっても接種率が低かったことが考えられます。","voiceIndex":100,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回の流行の特徴は、男性患者に多く、特に３０代を最多に、２０代、４０代が続いているということです。実はこの世代の男性は風疹のワクチンの接種を受けていません。１９７７年から風疹ワクチンの定期接種が始まりましたが、当初は中学３年生の女子のみに集団接種が行われ、男子の接種はありませんでした。そこで質問いたします。今回の風疹の大流行を抑えるにはどのような対策が必要なのでしょうか。","respondent":"矢野品川区保健所長","answer":"風疹にかかったことがなく、ワクチンを受けていない方々に接種を進めていくことも重要であると考えております。","voiceIndex":102,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ご答弁ありがとうございました。風疹には治療法はありません。日本産婦人科医会も、妊婦本人は風疹ワクチンを妊娠中は残念ながら受けることはできませんが、家族はすぐに風疹のワクチンの接種を、さらに１９７９年４月２日から１９８７年１０月１日に生まれた女性、２０代から４０代の男性すべて、妊娠希望の女性はすぐにワクチンを受けてほしいということを呼びかけております。","respondent":"矢野品川区保健所長","answer":"風疹の流行に関しましては、流行時にはホームページ等を使用して、また各関係機関に流行情報を提供しておりますが、それに加えまして、ＭＲワクチンに関しましてですが、定期接種対象者のうち、接種を済ませていない方々への個別接種勧奨を行っていくとともに。","voiceIndex":104,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"インフルエンザ予防対策の中心になるインフルエンザワクチンの啓発について、小学校、幼稚園、保育園、あるいは介護施設等高齢者施設などでもしっかり勧奨を行うことを要望して、この質問は終わりたいと思います。ここに差が出てきてしまいます。当然それに対して保護者の混乱が起こることが予想されます。この辺の啓発指導はどうなされているのでしょうか、お聞きいたします。","respondent":"金子子ども未来事業部長","answer":"今後につきましては、ご指摘のように、日数等々の違いがありますので、少し明確に保健だより等で啓発していくというふうな考えです。","voiceIndex":108,"id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"最後に、保育園における食物アレルギー児の対応について、ことしの春の予算特別委員会でもお聞きしましたが、引き続きお尋ねいたします。本年も８月ぐらいから例年のごとく私のところにも品川区の保育園食物アレルギー疾患生活関連指導表をお持ちになって、記載を求めていらっしゃる園児の保護者の方が増えてきました。それと食物アレルギーの原因の食物の内訳と頻度はいかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"保育園における食物アレルギーの現状ですけれども、まずその総数ですが、品川区の区立保育園におきましては、給食に配慮を要する食物アレルギーのある園児の総数が本年の９月現在で２０６人です。在園児の総数が４,４２６人ですので、率にしますと４.７％になります。","voiceIndex":110,"id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ご答弁ありがとうございました。全国レベルでの食物アレルギーの有病率は品川区とほとんど同等だということは理解しました。どうもありがとうございました。品川区の現状が認識できました。２００１年、２００２年の品川区保育園の保育中のアナフィラキシー事例に関して、保育中にアナフィラキシーショックを起こした園児はいらっしゃったのか。以上に関してお伺いいたします。","respondent":"金子子ども未来事業部長","answer":"本年と昨年のアナフィラキシーショックの事例ですけれども、品川区の保育園におきましてはそのような症状を起こした事例はございませんので、ご理解いただきたいと思います。","voiceIndex":112,"id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"指導表作成のねらいと意義等、それとあと、これで指導表の中にＩｇＥ抗体等検査陽性結果についてという項目がありますが、準拠されているとされる厚生労働省の保育所におけるアレルギー対応ガイドラインには、保育所の食物アレルギーの生活管理指導表にはアレルギー検査のデータは記載する必要はない、３７ページに書かれておりますが、あえて担当医に記入を求める理由は何なのでしょうか。","respondent":"金子子ども未来事業部長","answer":"品川区では従来からこういった対応をしておりましたが、平成２３年３月に厚生労働省で初めて作成しました保育所におけるアレルギー対応ガイドライン、これに基づきまして、医師の指導をより的確に受けとめられるよう改善したものです。","voiceIndex":114,"id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"意見","question":"現在食物アレルギーの診断は、詳細な病歴の聴取とそれから経口負荷試験で決めるものでありまして、特異的ＩｇＥ抗体の検査というのはあくまでも補助的な診断にすぎない。これはあくまでも参考値で、これで診断をしてはいけないということがたびたび最近強調されております。特異的ＩｇＥ抗体の検査結果というのは毎回必ず記載する必要がないということでよろしいわけですね。","respondent":"金子子ども未来事業部長","answer":"ですので、私どもとしましては、保護者に対しまして、必ずこの検査が必要であると伝えてはおりませんけれども、今後とも誤解を与えないよう、これについても施設長会により徹底していきたいと考えています。","voiceIndex":116,"id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"よくわかりました。保育園のアレルギー児がより安心・安全な環境のもとで元気に成長していけるように、職員の方々の十分な研鑽と、ご両親をはじめ、医師会、小児科医会、それに小児アレルギー専門医などの先生方とも綿密なネットワーク化、連携をさらに強化し、進めることを要望いたしまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"私からは２点の項目について質問いたします。一つは、青少年育成に関して、二つ目は協働事業についてお聞きいたします。最初に青少年育成についてお聞きいたします。青少年問題協議会、地域健全育成運営協議会、それぞれの設置目的、現状の運営がどうなっているか、実績、そしてそれの評価をお聞きいたします。さらには、それぞれの地域の現状がどうなっているのかについてもお聞きいたします。","respondent":"金子子ども未来事業部長、田村教育次長","answer":"このために年２回の会議を開催しておりまして、この会議の中でも、連絡調整、連携を図るための連絡調整はきちっとされており、会議の実績としては上がっているかと考えているところです。この活動は、ＰＴＡ活動支援のうちの一つでございまして、特に各中学校、年間３回を限度として、ＰＴＡへの委託事業として実施しているものです。","voiceIndex":120,"id":"exchange-056"},{"speaker":"西本委員","kind":"提案","question":"今聞いてみますと、情報交換という意味では、それぞれの委員会、協議会の中でされているというご答弁でした。せっかく地域の方々が集まっているわけですから、その地域の方たち、率先して具体的な行動として、会議だけではなくて、具体的な行動として何かをしていくということを提起しながら進めていくというのが非常に大切な視点ではないかと思いますが、この運営の仕方についてのご見解をお聞きします。","respondent":"金子子ども未来事業部長、田村教育次長","answer":"今年度はこういう取り組みをしておりますけれども、今後ともさまざまな取り組みを通じて関係団体との連携を深め、青少年が健全な環境の中で人間性を豊かに育てていけるように、そのような取り組みに努めてまいりたいと考えております。委員ご指摘のように、やはりまだ学校間で差があるというのも実態ですので、特にメンバー的には、警察以外も、保護司だとか、さまざまなそれぞれの地域で活躍している、ノウハウを持っている方が大勢いらっしゃるということなので。","voiceIndex":123,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"今回これが移管されたということなんですが、どういう経緯で、目的で、まずは、当初教育委員会に所管になったという経緯、そして、来年から子ども未来事業部に移管することになったのはなぜなのか、理由をお聞きします。さらに、あわせまして、児童センターの役割の変化、これからどうなっていくのか、成果、それから反省、今後のあり方についてもお聞きいたします。","respondent":"田村教育次長、金子子ども未来事業部長","answer":"私のほうからすまいるスクールがなぜ教育委員会で所管になったのかと、その辺の経過についてご説明しますが、もうかれこれ１０年以上前になるんですかね、平成１０年、平成１１年、ちょうど私も企画の長期計画担当やっていて。今回、このすまいるスクールを子ども未来事業部に移管するということの理由ですけれども、このすまいるスクールは、今ご説明申し上げたとおり、放課後の全児童対策事業であるとともに、当然この年齢から、青少年。","voiceIndex":126,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"指導員、先ほどのご答弁の中でも、指導員のほうの担当をかえたり、いろいろするということで、人的なところの問題もあるんだというお話でしたが、かねてから私のほうで主張させていただいているのは、新しい人材、育成するためにはそれなりの人材が必要だ、指導員の増員が絶対必要なんだということで、採用を推進してほしいということを申し上げておりますけれども。","respondent":"金子子ども未来事業部長","answer":"特別な支援を必要とする児童については、養護教員、あるいはスクールカウンセラーと連携しまして、具体的な指導計画に基づいて活動し、保護者の迎えがあるまで児童を見守るなどの対応をしていきたいと考えております。","voiceIndex":129,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"増員の考えはないというお話なんですが、ここは職員の定年のこともありますし、その人材については今後検討していただきたいとこれからも要望してまいりたいと考えています。一つ、今のご答弁の中で、子ども未来事業部側としては、学校側と協働しながらやっていきますよということなんですけれども、では、学校側ではどうなんだと。","respondent":"田村教育次長","answer":"当然学校の中にすまいるスクールが、所管が変わりますけれども、残りますので、学校と一体でやっていかないと、地域の保護者から見ると、学校の中の所管がすまいるスクールで区長部局にあっても、あるいは庶務課にあっても。","voiceIndex":131,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"ぜひよろしくお願いいたします。外部団体ですけれども、チャイルドラインであるとか、保護司であるとかという、そういう方たちの活動の場というのも必要になってまいります。青少年育成にかかわる人的財産を統括するような総合連携が図れるような事業、もしくはそれを統括するセンター的な、そういう施設も必要ではないかと思いますけれども、それらのご所見をお伺いいたします。","respondent":"金子子ども未来事業部長","answer":"青少年健全育成にかかわるセンター的な施設ということのお尋ねですけれども、先ほど私のほうからも、また教育次長のほうからもお答え申し上げましたとおり、さまざまな会議体に出ていらっしゃる青少年健全育成にかかわる団体というのは非常にさまざまな方々がいらっしゃって。","voiceIndex":133,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"地域の人的財産、たくさんあります、品川区にはですね。それを大切にしていただいて、健全育成に人力を尽くしていただきたいと思います。次に協働事業についてお聞きいたします。この協働という意味ですが、どのような意味があるのか。実際にどういう行動をとるものなのか。区の役割というものも含めてお考えについてお聞きします。現在までの取り組みの成果と課題などがございましたら、お答えください。","respondent":"中川原地域振興事業部長","answer":"活動紹介展を実施することによって、活動していらっしゃる団体の出会いの場を創出して、ネットワークをつくっていただく、そういったこともしております。四つ目としましては、地域振興基金を設置し、それを活用した資金の助成。","voiceIndex":135,"id":"exchange-062"},{"speaker":"西本委員","kind":"提案","question":"この区の事業の、その移管された事業を見ますと、どうも区の、あたかも区がやっているよと、区の事業のように見受けられていると私は感じるわけですけれども、そもそも協働事業というのは、当初の考えとしては、育成という意味、自主的な活動を重視するということを考えれば、それぞれの団体が自立して運営すべきではないかと考えますが、その考え方と、先ほどのご答弁を含めながら、この区民提案型。","respondent":"中川原地域振興事業部長","answer":"それは依存というのは、団体の力が相手の、一緒に協働する団体に頼ることで、その本来の団体が持つ力が鈍ってしまって十分な活動ができないという、そういうことを意味することと思いますが、区がこの協働提案事業を通じまして選んだ団体とはしっかり審査を行い、やれること。","voiceIndex":137,"id":"exchange-063"},{"speaker":"西本委員","kind":"提案","question":"行政評価の中でも、この協働事業提案制度はＣ、見直しとあります。今のご答弁の中でも、区民提案型は廃止になりましたということのご答弁でしたけれども、非常に私はこれはもったいないと考えています。それがこの区民提案型のこの事業がなくなるということについては、何か方法はないのか、手立てはなかったのか、その経緯、なくなった経緯について再度ご質問したいと思います。","respondent":"中川原地域振興事業部長","answer":"ただ、これは決まったことではありません。区民の方の状況を見ながら、この協働提案についての支援はいろいろなことを模索して運営していこうと考えているところです。","voiceIndex":139,"id":"exchange-064"},{"speaker":"西本委員","kind":"提案","question":"この二つありますね、区民提案型と行政課題型。行政課題型というのは非常にわかりやすい。その要請に対してフレキシブルに対応できるためにも、やはり区のほうがもっと間口を広げて、そして時期も年中申し込みを受け付けるというようなことをして、この自主的な活動を支えていきますよというような告知をされてはどうかなというふうに考えますが、その点についてお考えをお聞きしたいと思います。","respondent":"中川原地域振興事業部長","answer":"それで、気運の醸成のために五つの支援をしていまして、これはこの協働の仕組みをつくる前に、区民と区との協働を進める懇話会というのをつくりまして、２年ほど区民の方にどういう支援が必要かということを検討していただいています。","voiceIndex":141,"id":"exchange-065"},{"speaker":"西本委員","kind":"提案","question":"行政課題協働事業についてですけれども、これを考えていくと、確かに、行政側の課題に対していろいろな提案があって、それによって予算を立ててということで進めていくというのはわかりますけれども、では、この従来の業務委託であるとか指定管理者制度というものとの違いは何だろうか、協働であるという意味というのはどこにあるんだろうかということでちょっと疑問がありますけれども。","respondent":"中川原地域振興事業部長","answer":"これが採択されますと、協定を結びまして、そこでもう１回目的とそれから役割分担と成果を確認しまして、翌年に所管、関連の所管につなげるという、そういった作業を丁寧に１年かけて行った上で業務委託という契約を結ぶという、そういう手続をしているものです。","voiceIndex":143,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問・要望","question":"行政がどこまで縁の下の力持ちになって区民の方たちの自主的な活動、やる気といいますか、それをそがないように進めていくには、これからも研究していただきたいなと考えています。地域の活性化というのは、やはり区民の方々が輝いて活動できるというところにあると思いますので、これからも推進をお願いいたしまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-067"},{"speaker":"大倉委員","kind":"質問","question":"民主・改革ネットを代表して、井上委員とともに総括質疑をします。私からは、学校のいじめ問題の取り組みについてお伺いいたします。質問に当たりまして、過日亡くなられた生徒のご冥福をお祈りするとともに、ご遺族の皆様には心よりお悔やみを申し上げます。そこで、品川区では、いじめの予防策、深刻化する前の解決策、深刻化してしまった際の対処策、それぞれどのように考えているか、お考えを伺います。","respondent":"田村教育次長","answer":"それと、なかなかアンケートでも書けないという事例がありますので、この手引書にも、６ページにあるように、学級担任のいじめの早期発見チェックポイントというのがありまして、これは例えば遅刻、欠席が増えるだとか、筆圧が弱くなるだとか。","voiceIndex":147,"id":"exchange-068"},{"speaker":"大倉委員","kind":"質問・要望","question":"私も考えてみまして、予防というところでまずお話をさせていただきたいと思います。こうした記載を周知していくことが大変必要かと思います。あわせて、周知方法をお伺いいたします。そうした観点から、２４時間窓口、２４時間受付の窓口をトップに記載するか、もしくは、品川区でも窓口を２４時間化するということが可能なのか、お聞かせをいただきたいと思います。この２点お願いします。","respondent":"田村教育次長","answer":"それと、順番ですが、やはり２４時間、利用する側は２４時間と考えるかもしれないですが、やはり学校の設置者は品川区ですから、品川区長であり、学校に責任を持つのも教育委員会ということで、教育委員会あるいは学校に直接言ってもらうほうが一番迅速で。","voiceIndex":149,"id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"それで、そういった例えば相談が来た際の相談窓口、今、伺っていても、さまざまいろんなところである中で、充実しているのかなという思いは多少ありますが、そうした中で、相談窓口、品川区、例えば都でもいいですし、さまざまな国の相談窓口等あると思いますが、その周知率についての調査等は行っているでしょうか。そういった区での周知率やアンケート調査を行うお考え、取り組みはありますでしょうか。","respondent":"田村教育次長","answer":"それと、中学生の行動ですけれども、なかなか、何かを見なければ行動できないという、中学生ですから、頭に入れて迅速に行動すると、いじめを目撃したり何かした場合にはそういう迅速な行動をもう中学生は身につけることが必要なのかと考えています。","voiceIndex":151,"id":"exchange-070"},{"speaker":"大倉委員","kind":"意見","question":"生徒の目撃した際の対応も、そういったものが書いてあるんだよと、生徒手帳を見ればわかるよ、こういうところに電話してねということがあれば、例えばそれはスクールカウンセラーでもいいと思いますし、そうしたものへの促しというのを必要と考えておりますが、もう一度お願いいたします。","respondent":"田村教育次長","answer":"委員ご指摘のように、工夫する余地はあるということなので、ちょっと工夫してみたいと考えております。","voiceIndex":153,"id":"exchange-071"},{"speaker":"大倉委員","kind":"質問","question":"深刻化する前の解決策についてお伺いしたいと思います。こうした傍観者、加害者側の、被害者以外からいじめを解決するアプローチという考え方をお持ちかどうかと、そして、そのアプローチの手段としてスクールカウンセラーが、先ほども少し言いましたが、非常に有効と考えておりますが、区としてはどのようなお考えか、伺います。","respondent":"田村教育次長","answer":"スクールカウンセラーですが、まさにスクールカウンセラーは、学校のヒアリング、あるいは調査、アンケート以外に、またそれを学校の担任には言いづらいけれども、スクールカウンセラーにはお話しできるというケースも当然ありますので。","voiceIndex":155,"id":"exchange-072"},{"speaker":"大倉委員","kind":"質問・要望","question":"来年度よりすべての公立中学校へスクールカウンセラーが配置されるに当たり、そうした品川区でスクールカウンセラーの利用とその周知、また環境整備に関する明確な方針、マニュアルがありましたら、教えてください。そしてまた、そうした中学校での増員による変更点があれば教えていただきたいのと、そして、今後どのように活用していくか、構築をしていくかというのをお伺いしたいと思います。","respondent":"田村教育次長","answer":"例えばこの間ある学校に行ったんですが、朝礼でスクールカウンセラーを全員紹介して、それで名札を見て、この名札を見ていつでも相談に来てねというやり方をしていたり、教室を回るというやり方もしていますけれども、やはり何らかの形で、学校の特徴もあるかもしれないですが。","voiceIndex":157,"id":"exchange-073"},{"speaker":"大倉委員","kind":"質問","question":"最後に、深刻化した後の対処について伺います。そういった不幸な出来事を防ぐためにも、徹底した対処策を構築するべきと考えます。いじめの最悪な結果に至ってしまった場合、情報を学校間で共有したり、過去の事例に学ぶというような、学び合いというような、そういった情報の共有などをされたほうがいいと考えるんですが、区としてのお考えをお伺いします。","respondent":"田村教育次長","answer":"それと、出席停止の関係ですが、やはりおっしゃるとおり、各学校、ちょっと温度差がありますが、各学校の地域との連携のとり方というのは差がありますが、基本のパターンはある程度形ができますので、その辺はちょっと校長会とも相談しながら。","voiceIndex":159,"id":"exchange-074"},{"speaker":"大倉委員","kind":"質問","question":"区としても、ゲートキーパー研修は、自殺予防だけではなくいじめ対策としても有効ではないかと考えておりますが、どのようにお考えでしょうか。有効であると考えるのであれば、学校教職員等の皆様に早期にまた積極的に研修を受けていただくことが有意義だと考えますが、最後に区のお考えをお聞かせください。","respondent":"矢野品川区保健所長","answer":"今後も誰もがゲートキーパーを目指し、学校教職員も含めた職員向けの研修および区民向けの研修を工夫しながら継続して進めてまいりたいと考えております。","voiceIndex":161,"id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひそうした意味でゲートキーパー研修広めていっていただきたいと思います。以上で質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは、子どもの居場所についてと福祉オンブズの仕組み構築についてお伺いをいたします。なぜ教育委員会事務局だったのか、その目的を改めて伺います。そして、この間７年の間に教育委員会事務局の中で、教育改革担当、指導課、庶務課と所管を変えていますが、その効果は何だったのでしょうか。もう１点は、今回子育て支援課に移行しなければならなかった課題が何だったのか、お伺いいたします。","respondent":"金子子ども未来事業部長、田村教育次長","answer":"私からは、まず児童センターのあり方検討会設置に至った課題ですけれども、まず児童センターにつきましては、平成２２年度。私のほうからすまいるスクールを教育委員会で、その目的はですが、すまいるスクールは、平成１０年、平成１１年ぐらいですかね。４点目の質問の子育て支援課に今回移行するとした課題についてのご質問ですけれども、すまいるスクールは今教育次長からも答弁申し上げましたとおり。","voiceIndex":165,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"この判断を現状ではどう認識しているのか、また、今後見直す考えはあるのか、伺います。今まで教育委員会所管であったために、教育施設を活用するのには問題がなかったと思いますが、子育て支援課で教育施設を借りるという発想に今後変わるのでしょうか。今年度区立小学校では１８学級も増えています。第一日野小学校では連日１３０人を超える利用があり、現状２部屋で厳しいのに、来年は１部屋になる。","respondent":"田村教育次長、金子子ども未来事業部長","answer":"それと城南第二小学校も、もともと普通教室３教室入っていたんですが、１回は、子どもが増えたので、２教室になったんですが、別棟で旧学童クラブに使っていた建物がありますので、その中に入るということで。これを学校の中で行うということから、最近見られますように、安全の面、それから安心の面ですね、つまり、不審者の対策の面であるとか、あるいは震災の対策の面から。","voiceIndex":169,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"再び区長部局に移行して、関係が壊れては困るという不安であろうと想像するのですけれども、開設当時の困難とはどういったことだったと認識しているのか、伺います。それから、この中で事故対策等の対応について指示命令を出すのはどこなのかということがちょっと心配になるんですけれども、それはどういうふうに位置づけられているのでしょうか。","respondent":"田村教育次長","answer":"苦情のある保護者等に謝罪に行ったり、事情を説明に行くのも、必ず指導員だけで単独で行くのではなく、学校の担任あるいは副校長、校長と一緒に同席して対応してくれということで、繰り返し繰り返しやっていて、それが一定の形ができました。","voiceIndex":172,"id":"exchange-079"},{"speaker":"井上委員","kind":"確認","question":"で、区長部局になっても、今までと変わらないということを確認をさせていただいたんですけれども、今、教育次長がおっしゃったように、学校では校長先生や教職員の異動がありますので、経緯を知らない教員だけになっても困らないような具体的な運用基準が必要ということで考えておりましたけれども、今の答弁で、そういったマニュアルも含めて、きちんと整備をするということだったんですが。","respondent":"田村教育次長","answer":"既にマニュアルは何冊もできています。それで、毎年そうなんですが、所管が変わる前も、新しく転任の校長先生、副校長先生が来ると、必ずすまいるスクールの担当がマニュアルを含めて説明に行っています。","voiceIndex":174,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"学校によっては教室確保さえ困難という状況です。子ども一人一人が持つ多面性を尊重して、安心できる居場所ならどちらに行ってもいいんだというメッセージを発信すべきです。両方を活用して、自己肯定感を育てる子どもの居場所にすべきと思いますが、見解を伺います。利用者である子どもの意見を反映するために聞き取りは行っていくのでしょうか、伺います。２点についてお答えください。","respondent":"金子子ども未来事業部長","answer":"ただし、もちろん子どもが児童センターに来た場合には、拒む考えはありませんので、それはそれなりにきちっと対応していくというふうに考えているところです。","voiceIndex":176,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"児童センター運営費は１１億円ですが、２０１１年度決算では、建物２５館の維持管理費が２億円で、センター事業費は２億７,０００万円です。先ほどの２点を課題として挙げている理由を伺います。そして、品川区の児童センター職員は、多様な資格を持つ集団ですから、さまざまな事業も工夫して行われてきたという実績は評価できます。経費縮減には慎重にあるべきと思いますが、区の見解を伺います。","respondent":"金子子ども未来事業部長","answer":"児童相談所の虐待の話がありますけれども、なかなか移管は進まないということですけれども、私どもでは、子育て支援課、また児童センターが日々こういった子どもを対応している施設でありますので。","voiceIndex":178,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"権利擁護救済と苦情処理の仕組みについて伺います。品川区ではこの助成金を活用して苦情処理機関を開設されたのか、まず伺います。２０１２年に品川区社会福祉協議会では成年後見センターで成年後見事業等についての苦情処理の窓口を開設しておりますが、区との関係はどうなっているのか、あわせて伺います。","respondent":"早津健康福祉事業部長","answer":"今年度からの成年後見センターへの苦情の窓口ですが、これは社会福祉協議会の中で成年後見にかかわる部分での苦情の窓口を新たに設置したということでございまして、区との関係で申し上げますと、区と成年後見センターは全面的な連携のもとに対応しておりますので。","voiceIndex":180,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"そうすると、高齢者福祉、障害者福祉、精神保健における福祉サービスの苦情処理機関というのが今のお話でもあると思います。それぞれどのような運用で苦情処理が行われているのか、伺います。その相談件数と解決件数を２００９年から３カ年というところでお知らせください。","respondent":"早津健康福祉事業部長","answer":"苦情処理の機関ですが、苦情処理につきましては、高齢者ならびに障害者におきましては、各サービス事業者がまず責任を持って苦情の窓口を設置するということになっておりまして、そこが一義的に対応していくということになります。","voiceIndex":182,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"率直に言って、数が少ないなというふうに思いますけれども、今の答弁で三つ伺います。一つ目は、区としては数が少ないという認識があるのかどうか。二つ目は、現状の相談および苦情処理の仕組みで十分であると思われているのか。三つ目は、課題としてとらえていることが何かあるのか、お伺いします。","respondent":"早津健康福祉事業部長","answer":"現場で対応したものについては区のほうには特に報告は上がってまいりません。現場での対応に納得できなかった場合に区に上がってくるといいますか、来る場合のものをカウントしておりますので、この件数について少ないという印象は私は持ってはおりません。","voiceIndex":184,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問","question":"どうしたらいいかとても悩むと思います。施設内の風通しの悪さが人権侵害の温床になっていることが少なくありません。お世話になっている立場でなかなか言えないというときに、特に施設ではどのような窓口で解決の道が開かれているのか、体制を伺います。区への報告義務など、区の関与も伺います。そういった中でなかなか困難ではないかと思いますが、いかがでしょうか。","respondent":"早津健康福祉事業部長","answer":"各施設での苦情対応ですが、先ほども申し上げましたが、第三者的な機関、名称は例えばサービス向上、苦情解決委員会というような名称のもので、名称は多少違っておりますが、３名から５名の方がそこに従事をしていただいております。","voiceIndex":186,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"実際に施設内で４０代後半の男性の利用者がベッドから落ちて、ご本人が痛みを訴えなかったけれども、医師の診断で骨折がわかったというケースがあります。７０歳を超えた両親は、退所を言われたら、家庭では診られないと心配して泣き寝入りをしたという事例も過去にありました。オンブズマンは代理人、代弁者というスウェーデン語の由来です。改めて見解を伺います。","respondent":"早津健康福祉事業部長","answer":"このとき、利用者と事業者と区ということを考えたときに、区の立場は第三者性を有しているということになります。さらにオンブズマンと比較をいたしますと、こういう場合の区の対応というのは、恐らくオンブズマン対応よりも素早い対応をしているだろうと考えています。","voiceIndex":188,"id":"exchange-087"},{"speaker":"井上委員","kind":"意見","question":"生活者ネットワークの組織のある３４自治体の調査でも、福祉オンブズや類似した仕組みが条例に基づいて設置されているところが１２自治体ありました。検討委員会を設けてこういった協議も必要と思います。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-088"},{"speaker":"南委員","kind":"質問・要望","question":"去る９月２６日、品川区立中学校の生徒がいじめを受けて自殺をするという痛ましい事態が起こりました。亡くなられた生徒に心から哀悼の意を表します。二度と再び繰り返させないために、原因究明を徹底的に行い、万全の対策を講じるよう、強く求めたいと思います。そこで質問します。変えた理由は何だったのか、教えてください。第１次報告に終わらせず、全事実を報告すべきと思いますが、いかがでしょうか。","respondent":"田村教育次長","answer":"初めに、亡くなられた生徒のご冥福をお祈りするとともに、残されたご遺族に対し深く哀悼の意を表します。一つ目の調査対策委員会ですが、当初、９月２７日の未明に緊急対応としまして教育委員会事務局と学校とで構成員とする委員会を立ち上げしました。","voiceIndex":193,"id":"exchange-089"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ客観的に透明性を持って区民の信頼を損なわないように徹底的に追及をし、今後の教訓に活かしていただきたい、こういうふうに思います。さて、８月２０日の文教委員会にいじめの問題について資料が提出されました。この品川区立小中学校のいじめ等の状況について、この資料についての説明をお願いいたします。","respondent":"田村教育次長","answer":"先ほどの４月１日から７月２０日までは一緒ですから、８０件、中学校が４６件、合計１２６件。先ほど話したいじめ月例報告と加えると合計で１７６件という説明を文教委員会で説明させていただきました。","voiceIndex":195,"id":"exchange-090"},{"speaker":"南委員","kind":"質問・要望","question":"今確認をしたんですけれども、今、教育次長がご説明していただいたものが、平成２３年度がこれですね、合わせて４２件。そして、１７６件に対して区はどういう取り組みをしているのか、ここも伺いたいと思います。深刻な実態を区がつかめていなかったということ、区はどういうふうに考えているのでしょうか。アンケートにあらわれていないいじめについて、今後どう把握しているのかを伺いたいと思います。","respondent":"田村教育次長","answer":"先ほどもご説明したんですが、件数が少ないから学校が荒れていないんだとか、件数が多いから学校の指導力が不徹底なんだということを、基本としてこの数字で判断するということは教育委員会はしませんよというふうに学校に話しています。","voiceIndex":197,"id":"exchange-091"},{"speaker":"南委員","kind":"意見","question":"教育次長はそういうふうにおっしゃいますけれども、しかし、現実に子どもが３人亡くなっておられる。こういう現状をどう見るかということが大事だと思うんです。その状況の中で、教育委員会はどういう対策をとるのか。二度と再び、あるいはみずから命を絶つという、そういう痛ましいことを絶対にさせない、そういう対策がどういうふうにとられているのかということを聞いているんです。答弁してください。","respondent":"田村教育次長","answer":"それで、今回のこの対策の状況ですが、ここの入ってきた数値については、深刻ないじめで、即出席停止その他の事案というのはこの中には特に入っていなかったと考えておりますので、委員ご指摘のように、今回の事件がこの中に入っていなかったということは事実ですが。","voiceIndex":199,"id":"exchange-092"},{"speaker":"南委員","kind":"質問・要望","question":"深刻な事態があるとしたら、それをしっかりと、何ていうんでしょうか、手当てをする、そこのところが大事なのに、なかなかそこは見えないではありませんか。説明もないではありませんか。どうなっているんですか。教育委員会が学校教育に携わる先生を全面的に支援することなしには、こういういじめの実態、子どもが置かれているつらさ、そこをつかめないのではないでしょうか。そこを伺いたいと思います。","respondent":"田村教育次長","answer":"中学校についても、大筋１０校中６校が８時１５分始まりで、１６時４５分と、ほぼ小学校と同様と考えております。当然休憩時間は取得しているという状況です。","voiceIndex":201,"id":"exchange-093"},{"speaker":"南委員","kind":"質問","question":"先ほど質問した教育委員会の具体的な対応、これについては答弁漏れですので、後で必ず答弁してください。引き続き、先生たちの休憩はとれているという話でした。しかし、大体６時間授業、どこの学校でも行われていますが、６時間授業が終わるのが、低学年が１５時４５分、高学年は１５時５５分という、こういう状況です。私も自分の地域もそういう実態をつかんでおります。この点についても教えてください。","respondent":"田村教育次長","answer":"いじめの防止対策ですが、やはり今回９月５日にいじめ防止に関する手引書の説明会というのを全教職員、日野学園に集めてやりました。","voiceIndex":203,"id":"exchange-094"},{"speaker":"南委員","kind":"質問・要望","question":"甚だ先生たちの実態をしっかり掌握して、子どもたちに目が行き届く、そういう状況をつくるように私はするべきだと思うんです。うなずいているからそういうふうに理解をいたしますけれども、しかし、取れていても、よく聞くと、夏休みだとか、冬休みだとか、そういう長期休暇のときにあわせて取っているという、こういうふうに聞いていますが、その事実はつかんでいるかどうか、それだけちょっと伺います。","respondent":"田村教育次長","answer":"ただ、ですから、できるだけ教育委員会のほうも、研修だとか、そういう形で休みづらいようなものは夏の時期には持っていかないような工夫も配慮もしているという状況です。","voiceIndex":205,"id":"exchange-095"},{"speaker":"南委員","kind":"質問","question":"私はやはり先生の多忙化、土日もなく出勤しなくてはいけない、翌日の授業の準備をする時間がそういう時間しか確保できない、こういう現状を改めるべきだと思うんです。なぜならば、先生が忙しくて、子どもと十分に向き合って、子どもの状況をつかむ、そういう努力ができない。もっとほかに質問したかったんですが、時間がきましたので、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"共産党区議団の総括質疑を続けて行います。まちづくりマスタープランの防災まちづくり、特に防災の名で進める新たな都市計画道路づくりと沿道開発の中止を求めて質問をします。なぜ明記しないのか、お聞きします。三つ目、東京都が特定整備路線として指定した放射２号線と補助２９号線、品川区が同時期に進める補助３１号線の３路線について伺います。","respondent":"片田都市環境事業部長","answer":"それと、木密不燃化１０年プロジェクトの関係ですけれども、特に特定整備路線、延焼遮断帯という考え方についてまずご説明申し上げますと、特に東京都が発表した木密不燃化１０年プロジェクト、これはこれまでもの密集地域の中で、重点整備地域を基本として。","voiceIndex":209,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも明記するよう強く要望をしたいと思います。改めて名前を挙げていただきたいと思いますけれども、これをたった８年間で進めるという、本当に乱暴な計画だと思います。区長は私の一般質問で、車両火災の数値は必要だと認識していると。車両火災の検証の必要性を認めながら、その検証もないまま道路づくりを進めるのか、これでなぜ安全と言えるのか、どうやって区民の安全に責任を持つのか、伺います。","respondent":"片田都市環境事業部長","answer":"それとあと交通量調査については、これについては、今後道路構成等含めて、東京都のほうが基本的には進める事業ですので、交通量を予測して検討されるものと考えていますので、これについては事業者である東京都が行うものと考えています。","voiceIndex":211,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"しかも神戸市長田区という１区画の１事例にすぎません。これだけで、たったこれだけでなぜ６キロメートルもの巨大道路の根拠と言えるのか、改めてお聞きします。車両火災の想定もしないで、巨大地震で渋滞した車の連続車両火災が起こったら、想定外でしたと言うんでしょうか。改めて、車両火災について検証せずに道路づくりは進めるべきではないと思いますけれども、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"それともう一つ、車両火災のお話ですけれども、やはり緊急時、大地震に見舞われれば、当然道路への進入も規制されるでしょうし、今回の３.１１のときについても、いろんな制限が出されて、被災地への物資を運ぶというところにもいろいろ支障が出たわけですけれども。","voiceIndex":213,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は３.１１を思い出してみていただきたいと思います。車両火災の検証もせずに交通量もわからない道路づくりは進めるべきでないと強く指摘をしておきます。質問します。そこに住む人たちの暮らしと地域のコミュニティーが壊されることに対して、区はどう考えているのか、お聞きします。そして、都や区が説得しても納得しないという、こういう人はどうなるのかについてお聞かせください。","respondent":"片田都市環境事業部長","answer":"ただ、３.１１を経験して、やはり東京のまちづくり、特に密集地におけるまちづくりというのはすごく大事なことですから、これがやはり延焼遮断としての効果があるということであれば、やはりまちづくり、耐震化もそうですし、不燃化についても、いろいろなあらゆる角度から。","voiceIndex":215,"id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に２９号線について、続いて質問します。地域から都市計画道路を廃止してほしいという大きな運動が３回にわたり区議会に請願が上がって、３回とも全会派一致で採択がされて、区議会として東京都に対して計画道路の廃止を求める意見書を上げてきました。これを進めるというのであれば、私は町会ごとに全住民を対象にした説明会をやって、住民の意見を直接聞くべきだと思いますけれども、いかがでしょうか。","respondent":"片田都市環境事業部長","answer":"ただ、逆に、私どものほうとしては、東京都のほうにきちっと要請をしつつ、区としても連携をとって、粘り強く丁寧に説明をしていくということが実際の使命だと思ってありますので、そのような進め方を私どもはしていきたいと考えています。","voiceIndex":217,"id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は道路計画上にある、少なくともそこの町会に対しては、町会ごとに説明会を、全住民を対象にした説明会をやって、住民の意見を直接聞くべきだということを強く求めたいと思うんですけれども、そこの答弁をお願いしたいと思います。","respondent":"片田都市環境事業部長","answer":"それと、その前に、１１月１０日ですけれども、まちづくり講演会ということの中で、策定委員長のほうからの講演を含めて、品川区のまちづくりの取り組みといいましょうか、それについても区民を対象に行うということで、広報も予定していますので。","voiceIndex":219,"id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことではなくて、私が求めたのは、大きな犠牲を強いるこの都市計画道路の道路上、沿道の方のところに対して直接入って説明会を持ってやるべきだということで求めましたので、強くそれは要望しておきたいと思います。３本の道路だけで、我が党の試算では、少なくとも１,３００億円の税金です。交通量の予測もしない。こんな都市計画道路づくりはやめるべきだと主張して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-103"},{"speaker":"大沢委員","kind":"質問・要望","question":"本決算特別委員会で我が会派が指摘、提言をいたしました将来の幼児人口の動態を踏まえた保育園の運営費と保育料についての課題、公教育の復権に向けたプラン２１のさらなる充実、放射第２号線、補助第２９号線等の特定路線整備事業について、都区の密接な連携のもとに行われる区民への周知、小中学校でのいじめの防止、撲滅に向けた取り組みの徹底、図書館のあり方など、これらの諸課題を前向きにとらえ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-104"},{"speaker":"浅野委員","kind":"提案","question":"最後に、本決算特別委員会にて、我が会派の委員が提案、要望した中で、特に喫緊の課題であるいじめ問題への誠意ある対応と再発防止を強く求めます。その他、木造住宅密集地域の不燃化促進や空き家対策などの防災、減災対策、認知症、孤立死防止などの高齢者福祉の充実、難病、障害者対策などの意見を来年度の予算編成はじめ、今後の各事業に十分反映されますよう要望し、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":226,"id":"exchange-105"},{"speaker":"須貝委員","kind":"質問・要望","question":"みんな・無所属品川による平成２３年度品川区各会計歳入歳出決算に対する意見表明をいたします。首都直下型大地震や原発事故に備え、区民の生命、財産、健康を守るために万全な備えを早急に構築するとともに、教員にゆとりを与え、個々の子どもと向き合える時間をつくることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-106"},{"speaker":"石田（慎）委員","kind":"提案","question":"民主・改革ネットを代表して意見表明を行います。これらを高く評価しますが、利用料金改定の際には、表面的な受益者負担にとどまらず、政策の本質を見据え、さまざまな視点による検討と丁寧な説明を求めます。さらなる効率的な財政運営に取り組むとともに、本委員会における我が会派の指摘、提案が次年度予算や今後の施策に反映されますよう要望して意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":230,"id":"exchange-107"},{"speaker":"飯沼委員","kind":"提案","question":"一方、住民税、国保料増税など負担増の中、命と暮らしを守るサービスの削減、受益者負担を強調し、利用料の値上げなど、負担増を求め、福祉を増進させる自治体の役割を投げ捨てています。子どもは社会の宝です。必要とする人が受けられない実態を直視し、憲法第２５条と生活保護法に基づく健康で文化的な最低限度の生活を求める国民の権利の周知徹底が必要と思います。原発ゼロを一刻も早く実現してほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":232,"id":"exchange-108"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1368#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":114081,"voices":237}},{"id":"h24-20121018-10","meetingId":"h24-cm10","date":"2012年10月18日","dateIso":"2012-10-18","committee":"議会運営委員会","time":"午前１０時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２４年陳情第１４号、区民に開かれた品川区議会運営を求める陳情","agenda":"平成２４年陳情第１４号、区民に開かれた品川区議会運営を求める陳情","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"陳情項目１についてです。１点目なんですが、第２回定例会で試行、第３回定例会で実施ということで、再質問時間制限が行われたことで、何が起こったのかを検証していかないといけないと思います。２点目、皆さんは、今回のケーブルテレビの放映をご覧になったでしょうか。４点目、本会議で傍聴できない区民に、この本会議場でのやりとりをありのままに伝える、そういった放映であってほしいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"中身に入る前の指摘なんですけれども、前回の議会運営委員会でも指摘をさせていただきましたが、この陳情に、第３回定例会から実施と書かれているんですが、私どもが品川区議会で出したものの中には、そんなことは書いていません。そうすると、議会・委員会運営に関する申し合せ確認事項の中で、共産党にも賛同していただきましたけれども、議会運営に係わる審査は公開しないとなっているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-002"},{"speaker":"浅野委員","kind":"意見","question":"２番、３番につきましては、今言われたとおり、あらかじめ傍聴者が何人来るのかということは、想定できない部分であると思うんです。これについては、今後また、議会としても論議するべき内容だと考えていますので、そういう意味では、これについては、今の意見という形で、私どもは考えているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"これは、我々区議会の中で議会運営委員会で、本会議の再質問のケーブルテレビの放映ですとか、我々議会運営委員会のメンバーが意識をして改善をしてきたんです。その辺、もし、飯沼委員にご意見があれば、聞かせていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"確認","question":"議会の中身が漏れたということは、どういうことなんでしょうか。私は、質問しましたが、この申し合わせ確認事項を確認しないままにやってしまうのかどうか。あり方検討会の中間報告は載っていました。でも、これがどう実施されるかが、どこにも表示されない。そのこと自体に反省なくして、どうして漏らした漏らさないの議論になるんでしょうか、私は大変おかしな議論だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"ほんとうに我々、この議会運営委員会の意思で、第２回定例会でこうしましょう、第３回定例会から実施しましょうとやっているときに、この第３回定例会が始まる前にこの陳情が出たということが、どうしてという疑問を、率直に、素朴に思うんです。第３回定例会実施前に、何でこれが出るんですか。おかしいでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"第３回定例会をやる前にどうして出るのか、実際に第３回定例会に係る大事な事項を、区民に知らせないまま実施すること自体が問題じゃないですか。私は、議会運営委員会のあり方の問題だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-007"},{"speaker":"本多委員","kind":"提案","question":"議会運営委員会のルールを改善しましょうと提案してくださいよ。何も言わないじゃないですか。そのルール自体を変えろということでしょう。だったら、それを提案すればいいじゃないですか。そういう提案ゼロ、それでこういうふうに先にやるのがおかしいって言っているんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"質問","question":"今、いろいろと話を聞いていまして、まず、再質問を１０分の１とするという部分は、あり方検討会でいろいろ議論をした中で、中間が出され、その後、議会運営委員会として第２回定例会での試行と第３回定例会で、というような流れだったと思います。３点目なんですが、これもたしか、あり方検討会のほうでも少し話が出ていたかと思いますので、あり方検討会の中で議論を行うべきものではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"いろいろ議論を重ねて、第２回定例会、第３回定例会ではどういうふうにしていきましょうというのを決めて、そのルールにのっとって、こういう形になっているということは間違いないわけですよね。それから、区民として、こういうふうに陳情を挙げてくるという権利もあるはずですよね。ですから、もう採決を早めにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-010"},{"speaker":"須貝副委員長","kind":"質問・要望","question":"そうすると、今、品川区議会がこれに対してお金をかけるということが、果たして妥当なのかと考えたときに、大勢の委員が、いやそれはちょっと自重すべきではないかということになりました。多くきてもらえば、我々も嬉しい。どうぞ、その辺は理解くださいまして、我々のやっている、議長を含めて品川区議会が動いている中を、動きを見ていただきたいと思います。言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-011"},{"speaker":"本多委員","kind":"提案","question":"３番目なんですけれども、区議会各委員会を傍聴する際、傍聴者に、委員会資料を配布してください、ということで書かれているんですが、以前、私が区議会議長をやらせていただいたときに、やはり傍聴者のためにも資料を配ったらどうですかと提案しました。そういった途中経過の審議のものを、傍聴者にも、その辺よく配慮して見せて、そのかわり、持ち帰ってはだめですよという提案を、私はしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"３点目のことを、述べていいんですね。区議会各委員会を傍聴する際、傍聴者に委員会資料を配布してください。審議中という中身においては、注釈をつければよろしいのではないですか。ほとんど、中身が変わるということはないじゃないですか。あらゆる場合においては、取り扱いご注意をつければ十分に解決することであると思いますけれども、解決しませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"提案","question":"今、いろいろご意見をお伺いしていますけれども、ちゃんと議会には取り決めがあります。今、問題の提案としては、審議中のものを、つまり議会として判断する前のものを、区民の皆さんに提示するというのは、議会の責任として、やっぱり無責任だと、私は思う。議会の意思が形成されて、はっきりとこうだとわかれば、それは出せるかもしれないけれども、途中のものを何で出せるんですか。それは理解してほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"ルールがあるんだったら、ルールをやっぱり精査する必要がある。今のルールは、全て資料が全く渡らないわけですよね。区民に係わる大事なことが議論されていて、傍聴にお越しくださいと言って、傍聴者に全く資料がないということ自体、改善が必要ですよ。〔「見せようと言ったら反対した」と呼ぶ者あり〕ここの場ではありませんので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問・要望","question":"１番なんですけれども、再質問の時間については、議会運営委員会の中でも、皆さんいろいろな意見を闘わせた部分でありますし、最も議論が活発に行われた部分ですので、そのうえで、さまざまなことを検討して、今の形に落ち着いた。すみません、ちょっと話が戻りますけれども、陳情項目の１番で、再質問の時間を制限することなしにという表現は、私はちょっと引っかかります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"決定事項、申し合わせ確認事項を変えないままに、実際に実施してしまったこと、区民に知らせずに実施してしまったこと自体が、私はルール違反であると思っています。それから、内容のことなんですが、私はぜひ、開かれた議会を求めているんだったら、区民の知る権利を最大限保障する議会になってほしい。１、２、３、当然な区民の要求なので、ぜひ、近づけるように議会も努力をしていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"あまり議会運営委員会の内容を言うのもあれだけれども、私の記憶するところ、試行をした、その試行した結果、その枠内にほとんどの方が収まっていたから、それじゃあ、第３回定例会からは、そういうふうにしていきましょうと言って、多分、議長も、じゃあ１０分の１を超えたから、そこでいきなりとめるなんていうことは、私の感覚ではしてないし、今後も。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-018"},{"speaker":"本多委員","kind":"提案","question":"今日、結論を出していただきたいと思います。区議会費の来年度予算要望を、この議会運営委員会で各会派が出したときも、こういった要望、工事費を挙げてくれとか、予算計上してくれとかいう意見はゼロでした。そういった意味もありまして、もし、そうなれば提案をしていただきたいと思いますし、我々自民党としては、この限りがあることには無理だと思っています。我々が提案していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-019"},{"speaker":"浅野委員","kind":"質問","question":"本日、結論を出すということでお願いします。理由につきましては、１番につきまして、今まで、議会の中で今までるるやってきたということ。２番、３番につきましては、先ほどの論議の中でもお話ししましたけれども、物理的な問題というのが解消されない。それは、傍聴者が果たして何名来るかというのは予測ができない。そういう意味では、これについては反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"１番については、非常に議論がなされたと思いますが、やはりルールというのがあると思うんです。そして、議会の中で統一した見解のもとに外に出していくというのが当然のルールでありますので、この入り口論になりますけれども、それがなぜここに出てきたんだろうと。２番目、傍聴者ですけれども、これも要求がどういう要求がよくわからないんですが、ただ、毎回、平均的にどれだけの傍聴者がきているのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-021"},{"speaker":"阿部委員","kind":"提案","question":"それはあえて出さなかったわけではなくて、むしろ、タイミングとして、提案されなかったまま当日を迎えてしまったという側面があると思いますけれども、とにかく発信するということは、私たちの姿勢としては、今後、考えていってもいいかなとは思います。２番については、先ほど申し上げました。今、この陳情の中でどうというのは、逆に議論の順番としてずれてしまうかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"１点目が、区民の皆さんの知る権利をどう保障していくのかということで、とても重要な議論であったと思います。それが１点目です。それから、２点目ですけれども、物理的な問題、現状において、委員会室がありますけれども、大きなところに変更すれば、十分に吸収できる部分もある。３点目、変更があったらどうするのか。今までほとんど変更する事項はなかったじゃないですか。賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5134#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":13571,"voices":33}},{"id":"h24-20121023-8","meetingId":"h24-cm10","date":"2012年10月23日","dateIso":"2012-10-23","committee":"建設委員会","time":"午前１１時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、報告事項を行います。 初めに、(1)第２３回東京都道路整備事業推進大会","agenda":"の１、報告事項を行います。 初めに、(1)第２３回東京都道路整備事業推進大会","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つは、今、マスコミでも、復興予算がさまざま復興と関係ないところに流用されているということが問題になっていますけれども、その中でも沖縄の道路に使われたということもマスコミの中で報道されていますけれども、そういう点では、例えば今回の都市計画道路ですとか、都内の道路にそういう復興予算が充てられていたり、またこれから充てられようとしているとか。","respondent":"藤田都市計画課長","answer":"復興予算の関係等ですけれども、区のほうとしては、あくまでも財源というよりは、道路整備をきちんとやってほしいんだということをお願いするものですので、その辺の予算がどういうふうになっているかまでは把握はしてございませんけれども、繰り返しになりますけれども。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"復興予算がいろいろなところに利用されるということが本当に大きな問題で、被災地のところの復興がそれで全く進んでいないというところが大きな問題になっていますので、そこら辺のところはぜひ区としてもつかんでいただきたいと思います。そして、私は今回の道路大会に対しては、三環状道路にしても、また都市計画道路にしても、進めるということには賛同していませんので、道路大会には参加しません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"品川区まちづくりマスタープラン（素案）","agenda":"品川区まちづくりマスタープラン（素案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民がこれをいただきたいというときには、提供できるようなことでぜひしていただきたいと思うんですけれども、それが１点です。ぜひこのまちづくりマスタープランについて、少なくとも１３地域センターで説明会をしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"１３地区の説明会ですけれども、本マスタープランの方針に基づいて策定される計画でありますとか都市計画の決定の段階でありますとか、そうした細かい事業を展開する中で、説明会等々については、その事業単体で必要に応じて丁寧な説明をしてまいるということで考えてあります。","voiceIndex":17,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の説明で、パブリックコメントをするに当たり、この冊子を素案の段階で図書館や文化センターや地域センターに置いていただくということでよろしいんでしょうか。そのためにこれを見たいというときに、お金を取って、その冊子を区民に提供するということになるんでしょうか。そのことをお聞かせください。","respondent":"山崎マスタープラン担当課長","answer":"ということで、前回もそうですけれども、そうした部分についてのニーズや要望については、一定程度有償頒布の概念も入れて、そうした販売も行うということで、今のところ考えているものです。","voiceIndex":19,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が要望していますのは、これからパブリックコメントをするわけですよね。パブリックコメントで意見を言えるようにしていただきたいということなんです。そして、これを見て意見を言う人は、やっぱりそれに対して本当に関心のある、どうしたいという思いがある人だと思いますので、そういう方に提供できるようにしていただきたいと思うんですけれども、その点、お答えいただきたい。","respondent":"山崎マスタープラン担当課長","answer":"資料の配布につきましては、あくまでも素案の段階ですので、区民の皆様の希望によって冊子をお配りするようなことは考えてございません。","voiceIndex":21,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、素案の段階で地域センターや図書館、文化センター、こういうところに置いていただけるということで確認させていただいていいでしょうか。その確認をお願いしたいと思います。ぜひ区民の方に、これはカラーでダウンロードするのはかなりのページ数があって大変なことですので、提供できるようにという要望をさせていただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"繰り返しになりますけれども、素案のほうはご覧いただくようなことで、素案は置かせていただきます。","voiceIndex":23,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１回だけでは、なかなかこれを理解するということも大変ですし、また限られた１２０人という会場ですので、ぜひとも１３地域ごとに説明会を開いていただきたいと強く要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":10116,"voices":39}},{"id":"h24-20121105-6","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"区民委員会","time":"午後１時００分～午後２時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の区民集会所の利用状況","agenda":"の区民集会所の利用状況","exchanges":[{"speaker":"山内委員","kind":"提案","question":"もちろん利便性が悪いとか、いろんなそういったことはあると思うんですけれども、このまま１０％で推移していくということであれば、やはり今後のことを考えますと、いろいろと議会に提案していくなりしていかなきゃいけないんじゃないかなと思うんですが、その辺というのはどういった話を庁内でされているのか教えてください。","respondent":"久保田地域活動課長","answer":"そういった意味では、どういった利用ができるかというところも含めまして検討を進めているといったところです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問","question":"検討されるということは、この数字を見れば明らかなんでしょうけれど、いつごろからそういうことをしているのか、どれぐらいの期間でやっているのか。例えば、これはスクエア荏原ができるとか、そういった施設が近隣にできるというところを一つのめどとして考えているのか、どれぐらいの期間、庁内で検討しているのかというのを伺いたいんですが。","respondent":"久保田地域活動課長","answer":"こちらの施設の耐震上の課題等もございまして、区では耐震改修促進計画ということで、平成２７年度末までに区有施設の９割を超えるものを耐震化しなければならないというところもありますので、タイムリミットという意味では。","voiceIndex":10,"id":"exchange-002"},{"speaker":"武内委員","kind":"意見","question":"今のに関連するんですけれども、そうすると、荏原西区民集会所なんですが、地域の方が運営などをやっていらっしゃるのかなと思うんですけども、予約システムには載っていないということなんですが、運営している方は、限られた方にしか貸さなくて、ほかの方に貸し出しとかはしていますか。","respondent":"久保田地域活動課長","answer":"施設予約システムには載ってございませんけれども、特定の団体だけに貸しているということではなくて、荏原第三地域センターで申し込んでいただくような形をとりまして、いろんな、ホームページにも載ってありますし、あとしながわガイドとか。","voiceIndex":12,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"わかりました。ちょっとそこが気になっていたんです。同じ荏原西区民集会所なんですけど、耐震上の問題ということで、保育園があるわけですね、併設されているんで、そうすると、今保育園のほうも併設なんで、まだ耐震の課題があると、そういうことなんでしょうか。","respondent":"久保田地域活動課長","answer":"保育園については、既に耐震補強は終わってありますので、そうした心配はございませんが、荏原西区民集会所につきましては、構造上の問題とかがありますので、上には乗っている施設ですけれども、荏原西区民集会所には課題があるです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"全体を見すると、減額と免除がありますけども、地域によって、例えば品川第一区民集会所とか品川第二区民集会所とか、荏原第二区民集会所もそうだし、荏原第五区民集会所とか、減額よりも免除のほうが多いところが幾つかあるんですけれども、これはどういう見方をしたらいいんでしょうか。例えば、免除が多いということは、それだけ高齢者の団体が使う率が多い、そういう考え方でいいんでしょうか。","respondent":"久保田地域活動課長","answer":"減額というと、一般的には集会所として利用される方が登録していただいて、区民の団体だと２分の１の減額をさせていただいてあります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"わかりました。今後どういうふうにしていくかというのは別にしても、それにしても、所管では、この年度の割合がそれぞれ、町会がどれぐらい、高齢者がどれぐらい、障害者がどれぐらい、そういうのはあるということで、今全部細かく聞きませんけど、押さえてはいるということなんですよね。それとも、ここはちょっとあくまでも推測ということなんでしょうか。","respondent":"久保田地域活動課長","answer":"私が今お話ししたのは、規定上、減額はこういう団体、免除はこういう団体ですので、そうした中から実際の窓口等で対応している人、担当者の話、また自分の経験等に基づいてご説明をさせていただいたところです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"これは行革の観点になっちゃって、ちょっと違うのかもしれないんですけど、今後のいろんな施策の考え方とか、これがいいかどうかまた別の判断だと思うんですけど、免除とか減額の扱いはどうするのかとか、いろいろやっていく中では、そういう統計は多分必要になってくるんじゃないかと思うんですよね。要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"大倉委員","kind":"意見","question":"平成２１年度、平成２２年度、平成２３年度で、平成２２年度の利用率が、大体平成２１年度から見ると下がって、また平成２３年度に上がっているところと下がっているところがあるんですが、平成２２年度の利用率が全部の傾向として下がっているのはどういう理由なのかというのと、もしわかれば、また利用率がその後に増えているところもあれば、下がっているところもありますが。","respondent":"久保田地域活動課長","answer":"すみません、平成２２年度はご指摘のように全体的に利用率が下がっているということはあります。ただ、利用率が下がるような要因がこの年にあったかということであると、平成２２年度において特別利用率が下がるような要因となる出来事はなかったというふうに認識しています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"大倉委員","kind":"質問・要望","question":"利用率が下がった原因というのが、分母のお話もありましたけど、あまり明確にはなっていないということなんですが、そういった検証というのをしっかりやっていくことで、今後もっと利用しやすい環境であったり原因がはっきりわかると思うので、ぜひその辺は成果というか、調べていただいたほうがいいのかなと、これはぜひ調べていただければという要望で終わります。","respondent":"久保田地域活動課長","answer":"大崎第一区民集会所なんかも企業等の利用で、例えばちょっとした研修とか、会社の説明会とか、会社の会議とかで利用されているですので、大崎第一区民集会所、大崎第二区民集会所については、そういったところの分析をしています。","voiceIndex":23,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"４月から９月という形で半年のこういう資料を出してきていると思うんですけれども、区民委員会において、毎回こういう形で、例えば１０月から来年の３月までなんていう半年おきにとか、たしか毎回こういう率とかというような状況については、報告がなかったかなと思っているんですが、していたら申しわけないですけど、なぜ今の時期にこういう報告を出したのかをまずお伺いします。","respondent":"久保田地域活動課長","answer":"なぜ今年、この時期にということですけれども、やはり荏原第三区民集会所と荏原第五区民集会所が新しくオープンしましたので、それで３カ月という形ですけれども、半年たってとなると、来年とまた一緒になってしまいますので、できるだけ開設後どうなったかと。","voiceIndex":25,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"報告してくださって、ありがとうあります。各集会所について、区が決めている稼働率というか、何パーセントというのは、このぐらいを目標にしていれば、みんな同じではないと思うんですけれども、各集会所において利用率の設定というのはしているんでしょうか。","respondent":"久保田地域活動課長","answer":"利用率、稼働率の目標ということは、例えばこの施設は何割という明確な目標設定はしてございませんけれども、私ども、よく考えているのは、例えば利用率が高くて８割、９割の利用率ということになりますと、施設の利用状況としてはかなり使っていただいているので。","voiceIndex":27,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"極端に少ない利用率１２.３％というのは置いといて、ということは、逆に利用率をただ上げるために努力するんじゃなくて、利用率が逆に高いところはセーブをして、地域の人が借りられる６割ぐらいまでに下げとかなきゃいけないという考えもあるんですか。","respondent":"久保田地域活動課長","answer":"できれば、先ほども言いましたように、高い利用率のほうがいいんですけれども、すべての施設が８割、９割ということになりますと、１週間後の何曜日にとりたいといっても、とれないような状況になりますので、地域の方の活動を阻害する可能性もあるということで、６割程度ですと。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"限りなく１００％に近いとか。１００％に近いほうがいいわけで、だから、あいていると、夜間とかを安くするとかいろいろ努力をしているわけですけど、区としては６割ぐらいがちょうどいいんじゃないかという考えがあるわけですから、大体６割行っているところに関しては、利用率を上げるために人も入れて、またお金も使ってやって、上げるという努力はあまりしない方向でいるんですよね。","respondent":"久保田地域活動課長","answer":"できるだけ高い利用率は目指していますけれども、今おおむね６割というところの評価ということであれば、そういった柔軟な利用もできるですので、努力はしてまいりますけれども、そういった評価をしているということのご説明、我々としては６割程度であれば。","voiceIndex":31,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"例えば、町会会館ができると、毎月やっている一つの町会が、月例で使っていた各部会が仮に三つあったとしたら、月に４回借りている町会が、全部自前の会館でやるとなれば、４×１２で４８減るわけですから、大体免除団体の数を見ると、大体減っていますよね。そのところをどう思うのか。多分、町会会館は相当な要因の一つだと思いますので、その辺はいかがでしょうか。","respondent":"久保田地域活動課長","answer":"確かにそういった傾向もこの中には含まれているとは思うんですけれども、町会会館もここのところ急激に整備されている状況でもございませんので、例えばある年間に１０個、２０個の会館ができているというところでもございませんので。","voiceIndex":33,"id":"exchange-014"},{"speaker":"本多委員","kind":"意見","question":"それと、八潮がどうしても利用率が横ばいなんですが、その辺の何か工夫というか、ないのかなと、ちょっと一つだけ取り上げるというのもあれなんですが、八潮について、この横ばいの数字はどうとらえていますか。","respondent":"久保田地域活動課長","answer":"例えば、されたとしても、大井第一地区のほうからの利用というようなことで、地区を越えて利用はなかなかされないということの傾向があると思われますので、こうした中で、利用率は大体横ばいの推移になるのかなというふうに思っているところです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"意見","question":"それと、利用率が低いところの話がありましたけれども、こういった実績に基づいた改善というところでも、会議みたいな、こうしていこうかというようなものというのは開かれているのか、開かれていれば、どれぐらいのペースでやられているのかというのをお願いします。","respondent":"久保田地域活動課長","answer":"この利用率が低い施設を検討する会議というものですけれども、何とか検討会議というもので設置はしてございません。これは地域活動課が主管ですので、地域活動課の中で所管する私どもが主体的に検討して、分析しながら検討しています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、集会所からの、毎日見ていくということは難しいと思うんですけど、報告なんかを受けているということなんですか。","respondent":"久保田地域活動課長","answer":"利用実績等につきましては、毎月集計をしていますので、各施設から報告は上がってきてあります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"利用率以外に何かこういった声が多いとか、こうしてほしいという区民の声があるということなんかもあわせて報告されているんでしょうか。","respondent":"久保田地域活動課長","answer":"各施設において、そういった声があれば、きちんと地域活動課に報告していただいてあります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどあった荏原西区民集会所ですけども、利用率が低いというところでは、施設が使いづらい、あと耐震もしていかなければいけないというのがいろいろ出されていましたけれども、利用率が低いと、今の品川区の行革の路線でいくと、なくしていってしまうのかなというすごい不安があるんですけれども、使いやすくしていくという改善。","respondent":"久保田地域活動課長","answer":"荏原西区民集会所ということであれば、この施設は使いづらい状況にあるというのは変わりございませんので、ここの施設の中でやろうとなると、なかなか難しいところはあろうかと思いますけれども、もうちょっと広い範囲で、面でとらえて検討をしているということはあります。","voiceIndex":43,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、先ほどから分母が違うからちょっとパーセンテージが違うんじゃないか、違ってくるということだったんですけど、例えば荏原第一区民集会所で、平成２２年度が計で２,１０９回の使用で、６４.４％の利用率になっているんですけど、片や平成２３年度で２,０９４回、ほとんど変わりないのに７６.２％の利用率になっている。","respondent":"久保田地域活動課長","answer":"利用率につきましては、実際に使ったものを利用可能な回数で割ってありますので、その年によって分母の数が若干、休館日とか、そういうものは除いた数になりますので、休館とかがあったり、施設が利用できなかった期間があれば、その分は分母から除きますので、そういう意味では。","voiceIndex":45,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"特に品川第一区民集会所なんかは昭和４５年ということで、この間改修した荏原第五区民集会所とか荏原第三区民集会所は古いんですけども、そういうものも、あと３年ですからやっていかなきゃいけないんじゃないか。とりあえず、どこを改修しなきゃいけないのか、わかっていれば教えていただきたい。","respondent":"久保田地域活動課長","answer":"こちらは民間のマンションと併設ですので、区単独で耐震化ができないということで、こちらが残っているという状況です。荏原西区民集会所が先ほどご説明しましたように、まだ耐震化が終わっていないです。","voiceIndex":47,"id":"exchange-021"},{"speaker":"井上副委員長","kind":"質問","question":"二つ、先ほど来の議論の中からお伺いをしたいんですけれども、分母の話なんですけれども、区で地域センターを使っているところがあると思うんですけれども、それは分母から、初めから除いているのかどうかということと、区がやるときは当然免除ということで利用されているのかどうかをお伺いしたいと思います。","respondent":"久保田地域活動課長","answer":"そんなに数がたくさんあるということではないというふうに私はとらえてあります。それと、あと区が使うときは免除と、利用料はないということです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"井上副委員長","kind":"質問・要望","question":"それから先ほどの荏原西区民集会所なんですけれども、保育園の３階部分ということで、保育園は耐震を早急に進めなければならないということで、別にやっていたというところは理解をしているんですけれども、保育園の側と、これをずっとこのまま置くということにはならないと思うので、所管が違うということではないと、庁内での検討の中で、保育園側の要望とか、そういったものというのは。","respondent":"久保田地域活動課長","answer":"ただ、我々この施設をどうやってやっていこうかというところで、関係する部署、例えば耐震化の問題がありますから施設整備課とか、あとは保育園が併設していますから保育課とかとは打ち合わせ等を行いながら、今後の方針は検討しています。","voiceIndex":54,"id":"exchange-023"}]},{"id":"topic-02","title":"の平成２４年度、協働事業提案制度の審査結果","agenda":"の平成２４年度、協働事業提案制度の審査結果","exchanges":[{"speaker":"武内委員","kind":"意見","question":"２団体からの応募ということですが、防災ということでいえば今非常に意識が高い中で、もうちょっと何か来なかったのかなという気がちょっとするんですね。その辺をどう感じていらっしゃるかということと、あと、もともと採択、いわゆる何件ぐらいを目指していたのかということとか、その辺の状況をどう認識しているのか。","respondent":"今井協働・国際担当課長","answer":"テーマに対する提案の件数ですが、今回は２団体ですが、説明会には４団体６人の方にご出席いただきまして、ご説明をしたところですけれども、最終的には２団体となりました。","voiceIndex":61,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"そうすると、例えばＣＳＲ推進協議会とか、そういうところでいろんな、防災だけじゃないんでしょうけれども、いろんな連携をかけてきたと思うんですけれども、こういうところにも呼びかけられたりしたんでしょうか。それから、そういうところは既に逆に都の、また地域との防災の連携は、ある程度できているので、こういうところに来なかったということなのか。その辺をあわせてお伺いします。","respondent":"今井協働・国際担当課長","answer":"ただ、やはり年に１回程度の訓練という形になりまして、継続的な取り組みが少ないということから、今回企業に主体的な取り組みを求めたところですけれども、それぞれの企業としては、地域というよりも、今はＢＣＰといいますか。","voiceIndex":63,"id":"exchange-025"},{"speaker":"井上副委員長","kind":"提案","question":"そこで、どういうふうにこれはなくなって、要領で昨年の２月に変更した決定をどういうふうに区民に周知をされてきたのかということが１点と、この中で、自由提案というものを活かしきれなかったところの評価というのをどうされているのかということをお伺いします。","respondent":"今井協働・国際担当課長","answer":"平成２２年度の事務事業評価の中で、平成２２年度に区民からの自由提案につきましては採択事業がゼロ件というふうな形になったときに、私どもは検討いたしまして、区からの課題を提起する事業に今は一本化して実施するということで。","voiceIndex":65,"id":"exchange-026"},{"speaker":"井上副委員長","kind":"提案","question":"せっかくこれは、大きな意味を持って寄付もいただき、つくられたものですので、そのところは検討するに値する内容であるというふうに思っていますので、ここは進めていただきたいと思いますが、今の状態はほかのほうで力を入れていくということだったんだけど、並行して改めてというふうに思いますけど、いかがでしょうか。","respondent":"今井協働・国際担当課長","answer":"一方、この協働事業提案制度は、やはり区の喫緊の行政課題を区民の皆様と一緒に考えて実施していくということを今集中的に考えておりますので、やはりもう少し課題がわかりやすい、逆に言うと、わかりやすい課題をもう少し庁内の中で練っていくのか。","voiceIndex":67,"id":"exchange-027"},{"speaker":"井上副委員長","kind":"提案","question":"提案の中に、今回企業に向けてというようなメッセージで提案をしているので、やっぱりそういう項目になると区民は企業向けだなというふうにとらえてしまうと思いますので、わかりやすいとか、そういう意味では区が投げていく提案についても工夫をしていただいて、単年度で行うということが、先に進みにくいというふうに思いますので、この辺は検討していただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-028"},{"speaker":"山内委員","kind":"質問","question":"採択の理由、注意事項、何度となくこれをずっと読んでいるんですけど、全く具体性がなくて、何があるのか、そもそもがわからないですよね、正直なところ。これは、今回我々、委員のためにつくって、これを提出しているんですか。この内容、この理由というもの。","respondent":"今井協働・国際担当課長","answer":"この「採択理由および注意事項」と「理由」につきましては、区民委員会への報告ということではなくて、団体の方々に区として今回の事業に対する採択理由および不採択の理由としてお知らせしているところです。","voiceIndex":70,"id":"exchange-029"},{"speaker":"山内委員","kind":"意見","question":"不採択のところでは、何となくなんですけど、わかる理由がある。だから、我々にもわかりやすく説明してもらわないと、どうやってとらえていいのかわからないし、団体の人はわかるのかなと思うんですが、例えば団体じゃない、専門家ではない我々が、これを見てどうやって理解するのかというのが見えてこないので、ちょっとその辺はちゃんとしてほしいんですけど。","respondent":"今井協働・国際担当課長","answer":"２行目につきましては、提案団体は地域に実際に実施していますけれども、協働する所管課が防災課ですので、ただ単に防災課やこの企業が一方的に事業を進めるわけではなくて、事業を進める中でも役割分担といいますか、企業への働きかけ。","voiceIndex":72,"id":"exchange-030"},{"speaker":"山内委員","kind":"質問・要望","question":"ですから、もう少しわかりやすい言葉で書いていただけると、今後はありがたいかなと思うので、そのあたりをちょっと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"}]},{"id":"topic-03","title":"の地域と在住外国人との交流事業","agenda":"の地域と在住外国人との交流事業","exchanges":[{"speaker":"武内委員","kind":"質問","question":"どの辺の今状況なのか教えてください。","respondent":"今井協働・国際担当課長","answer":"地域と在住外国人との交流促進につきましては、平成２１年度長期基本計画が実施されたことに伴いまして実施しました。最初に八潮で実施したときには、実は中国の方とイギリスの方で、実際にはほとんどの方がいらっしゃいませんでした。","voiceIndex":80,"id":"exchange-032"}]},{"id":"topic-04","title":"の区立荏原平塚総合区民会館の予約開始と開館記念式典等","agenda":"の区立荏原平塚総合区民会館の予約開始と開館記念式典等","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"裏面のほうのオープニング記念なんですけれども、そちらは、やはり有名な方がいらっしゃるということで、それはオープニングのために区のほうでお呼びしたと思うんですけれども、単純にチケット販売だけでやってもらうのか、それとも何かお願いするに当たっての(1)、(2)、(3)、それぞれ招聘のためのお金を払っているんでしょうけど、その辺はどうなんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"表面のところの登録団体などの話です。大きく分けて、5)のアリーナと、それから1)から4)まですが、まず、区民登録団体と書いてありますが、戸越体育館、総合体育館につきましては、体育館登録団体制度というものを設けています。","voiceIndex":87,"id":"exchange-033"},{"speaker":"武内委員","kind":"意見","question":"それともう一つ、品川区の商店街を取材するということなんですけど、題名が「品川区商店街物語」ということで、そういう取材をして脚本をつくるということなので、どれくらいの頻度で取材するか、どういう取材をするかわからないんですが、せっかくなので、有名な方が品川区の商店街にある意味では入ってもらうわけなので、どこに入るかわかりませんけども、何か商店街振興の角度から。","respondent":"安藤文化スポーツ振興課長","answer":"そして２点目は、地域の取材ですが、これから、題材に合わせて地域に入っていって取材をしていくと思います。委員ご指摘のように、せっかくやるところですので、大きく商店街を巻き込んだ地域との連携にしていければというふうに考えてあります。","voiceIndex":89,"id":"exchange-034"},{"speaker":"井上副委員長","kind":"質問・要望","question":"予約のほうなんですが、１月１１日の広報でというお話だったと思うんですが、今説明を聞いて理解するような、もしこれであったら非常にわかりにくいなというふうに思いますので、その辺の周知の方法、団体の方たちとかは割と情報が早く行かれると思うんですが、そうではない方、広報だけで知る方もいらっしゃると思いますので、区民に知らせるというだけではなくて。","respondent":"安藤文化スポーツ振興課長","answer":"この申し込みにつきましては、まずここで、区民委員会で報告させていただきました。そして、順序として、その次にスクエア荏原がある荏原第一、荏原第二、荏原第三の町会長会議におきまして、同じような形でご説明をさせていただきたいと思っています。","voiceIndex":93,"id":"exchange-035"}]},{"id":"topic-05","title":"の文化センターの改修工事","agenda":"の文化センターの改修工事","exchanges":[{"speaker":"山内委員","kind":"質問","question":"旗の台文化センターと東品川文化センター、非常に古いと思うんですけれども、それぞれ何年の開設ですか。","respondent":"安藤文化スポーツ振興課長","answer":"旗の台文化センターは昭和４６年の開館です。それから、東品川文化センターは１年おくれて、昭和４７年です。ですから、４０年、４１年ほどたってあります。","voiceIndex":100,"id":"exchange-036"},{"speaker":"山内委員","kind":"意見","question":"これは古い建物ですけれども、耐震というのはどうなっているのか。","respondent":"安藤文化スポーツ振興課長","answer":"東品川文化センターの耐震につきましては、平成２３年度、これも東京都とあわせて実施済みです。","voiceIndex":104,"id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"東品川文化センターとシルバーセンターは、工事中も利用可能ということですね。それと、今の山内委員の関連なんですけど、平成２３年度に耐震工事をやったときに、文化センターの外壁とか、その辺は一緒にやるという考え方はなかったのか、２点。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、工事の業者の進め方等によっては、１日とか、ほんとうに単発的ではありますが、少しご不便がかかるところがあろうかと思いますけれども、基本的には東品川文化センターとシルバーセンターは、クローズなしで進めします。","voiceIndex":106,"id":"exchange-038"},{"speaker":"武内委員","kind":"意見","question":"難しいというのは技術的に難しいのか、今の話を聞いちゃうと、先に部署が違うからと言われちゃうと、何か縦割で、予算の出ぐあいとか、いろんな関係で難しかったんだなと思っちゃうんだけど、決してそうじゃないんだと。技術的に難しいということで理解しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-039"},{"speaker":"井上副委員長","kind":"質問","question":"１０月１日からきゅりあんの駐輪場の料金改定等が行われていたようなんですけれども、そのことについて事前に報告がなかったので、詳しくは次回資料をもとにということで構いませんけれども、ちょっとその概要を説明いただけるのであればお願いしたいなというふうに、区民生活に随分と影響しているので、その辺、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"今ご指摘の駐輪場につきましては、さきの決算特別委員会にも西本委員長からご意見をいただきまして、お答えをしたと思いますけれども、大井町再開発ビル周辺の駐輪場、一体的な見地から、大井町再開発ビルも、駐輪場については何とかする方向でずっと検討していたところです。","voiceIndex":112,"id":"exchange-040"},{"speaker":"井上副委員長","kind":"質問","question":"前回、観光事業についての資料をいただいているんですけれども、平成２２年度、区の負担が１６０万円ということなんですけど、その辺はまた今回も変わらないのかということと、大体３,０００名の先着ということで、どのぐらい、抽選なのか。では予算の、しながわ観光協会の支出もあったりとか、協賛団体の支出等は区だけなのかどうなのか、改めて、その辺はどうなっているんですか。","respondent":"米田商業・観光課長","answer":"観光まち歩き事業としては、年に３回行っていただくようになっております。","voiceIndex":120,"id":"exchange-041"},{"speaker":"井上副委員長","kind":"質問","question":"今回のこの企画に対しての区の予算は幾らなのかということと、先日テレビを見ていたときに、商店街で月に一度とか、１００円均一でという商店街のイベントがあって、そういう形でそれのときはすごくあって、その先もそれで終わらないというような報道があって、この参加費の無料というのは、主催がしながわ観光協会であっても、区の負担でその商店にということなんですけど。","respondent":"米田商業・観光課長","answer":"この辺については、気軽に参加していただくということを踏まえて、その後、実をとっていただくというようなことも一つの流れかと思います。その中である種区の負担を減らしていくということにつきましては、今後の検討課題とさせていただければというふうに思っております。","voiceIndex":122,"id":"exchange-042"},{"speaker":"山内委員","kind":"意見","question":"すごく細かいことだけど、主催がしながわ観光協会で、なぜ問い合わせが横浜なのかというのがよくわからないんですけれど。","respondent":"米田商業・観光課長","answer":"もちろん区の広報紙等ではしながわ観光協会の電話番号等を出しておりまして、そちらのほうでも十分対応ができるようにということは努めておりますが、第一義的な問い合わせ場所というようなことは東急電鉄です。","voiceIndex":124,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":35691,"voices":127}},{"id":"h24-20121105-7","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"厚生委員会","time":"午後１時００分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区立高齢者住宅入居登録者の募集","agenda":"区立高齢者住宅入居登録者の募集","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。大井林町なんだけれども、これは今、再度募集もかけたというのもあるので、当初から。今、全部埋まっているということで考えていいのか。それから、そうすると、３月３１日までにあいた場合は、予備の今年の登録の人はたくさん待っていらっしゃる方がいるのかなというのだけ教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"２人用の世帯用のほうですけれども、こちらの方については１０組、今、待機をしていらっしゃるという状況です。来年３月３１日まで、あきが出た場合には、優先的にこちらの方、待機者の方から入居していただくです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それと、大井林町にも関連するんですけれども、今待っている方は３月３１日までという話ですけれども、４月以降は、要するに、新たにもう一度申し込みをするということなのか、いわゆる積み上げ方式というんでしょうかね、できるだけ申し込まれる方の負担感をなくしたいなという思いなんですけれども、その辺についてどういう考え方、対応なのか、伺いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"次の募集案内の中でもって、やはり優先順位、いろいろと立ち退きですとか、あるいは住宅の劣悪さによりまして、優先順位がおのずと決まってくるわけなんですが、やはり、こういったところから漏れられた方については、住宅あっ旋等のそちらのほうのご案内もあわせて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"若林委員","kind":"質問","question":"１点だけ。大井林町のほうで、例年、年に１回の募集が今回から始まるという認識なんですが、今回、単身用が２０戸、２人用が１０戸、この設定の仕方、どういう根拠で設定されたかだけ教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"このようなことを考え合わせまして、単身用２０戸、２人用１０戸というような設定です。","voiceIndex":9,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":4517,"voices":19}},{"id":"h24-20121105-8","meetingId":"h24-cm11","date":"2012年11月5日","dateIso":"2012-11-05","committee":"建設委員会","time":"午後１時００分～午後４時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、報告事項を行います。 はじめに、(1)木密地域不燃化１０年プロジェクト「特定整備路線」候補区間の全ての区間選定","agenda":"の１、報告事項を行います。 はじめに、(1)木密地域不燃化１０年プロジェクト「特定整備路線」候補区間の全ての区間選定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新たな選定ということですけれども、この補助２８号線の計画路線上の建物の棟数ですとか商店街、影響を受ける公共施設、町会がどういうところなのか、ちょっと名前で教えていただきたいんですが。","respondent":"藤田都市計画課長","answer":"補助２８号線に絡む建物棟数等ですけれども、今回の路線は基本的に、今ある現道の拡幅ということになります。その中で、棟数としては約９０棟に関係が出てくるかと考えています。それから近くの公共施設としては、特にはございません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"道路の今の幅がどれぐらいあって、どれぐらい拡幅になるのかということと、商店街の片側がずっと道路によって削られていくということになると思うんですけれど、そういうことの商店街への影響ということに対して、どう考えているのかということと、それからこの１ページに「詳細に整備効果の検証を行い」ということで、行ってその路線を選定したということですけれども。","respondent":"藤田都市計画課長","answer":"それから商店街への影響ですけれども、計画線と現在の道路の関係なんですけれど、おおむね両方に関わるような形になっておりまして、そのために延長と、先ほどおおむねかかる９０棟というお話をさしあげましたけれども、そういう数になってきているということで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひつかんで、この委員会にも納得いくような形での説明をしていただかないと、９０棟とかなり大きな、商店街にも大きな影響を与える道路になりますので、なぜやるのかというあたりは説明をきちんとできるような形にしていただきたいと思うんですけれど、いかがでしょうか。","respondent":"藤田都市計画課長","answer":"区のほうとしては木密地域の安全、安心のために補助２９号線、放射２号線と同様に整備を進めていくことが、区民の皆さんの安全、安心につながると考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、今回の検証の中には車両火災というのが入っていたのかどうかということと、やはり区としても車両火災ということを求めていくべきだと思うんですけれども、その点が一つです。やはり道路ができると、震災になるとかなり渋滞になるということがあると思うんですね。その点についてもお聞かせいただければと思います。","respondent":"藤田都市計画課長","answer":"私は実際に３・１１のとき、道路を直接見に行ったわけではありませんけれども、聞いている話の中では、相当な渋滞があったと聞いているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで木造住宅がそのままということになると、それが４０カ所にわたる出火という想定もされていますから、そこで火災が起こり、渋滞が起こり、そこに車両火災ということになったら、本当に大惨事になると思うんですけれど、そういう想定も含めて、この渋滞の状況、車両火災の状況というのは避けて通れないのではないかと思うんですけれど、その点についてお伺いします。","respondent":"藤田都市計画課長","answer":"そういう面で考えると、今回、都市計画道路を整備することで、被害を少しでも少なくするということと、もう一つは渋滞にならないように、その後の消火活動ですとか物資輸送がスムーズにいくような防災計画の中での交通規制等。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年の３・１１は、私たちが実際に経験した初めての大きな地震だったと思うんです。私もこの間、荏原消防署にお話を伺ってきましたけれど、実際に常時動ける、出動できる消防車は６台だと言われたんですね。だから消防車が通れるようにということで道路を整備しても、その消防力の向上ということを同時に進めないと、そういうことにはならないと思うんですけれど、そこら辺はいかがでしょうか。","respondent":"藤田都市計画課長","answer":"そういう意味でトータルな面で消火力の強化、これを進めているところです。はといいますか、私の立場で申しますと、どうしても基盤整備の話が中心になってしまいますけれども、区としてはそれらの対策を総合的に進めているところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、３・１１のときに品川区内の幹線道路の渋滞の状況がどうだったのかというのは、区としても把握してほしいという、その質問なので、それは多分いろいろなところからデータはとれると思うので、ぜひ把握をしていただきたい。そういうことがないと、実際にどういうふうになるのかということは想定できないと思いますので、それをつかんでいただきたいということに対しての答弁をお願いします。","respondent":"松代防災まちづくり事業部長、藤田都市計画課長","answer":"３・１１の際の交通渋滞です。基本的に車のさばき、交通等の件に関しては、警視庁が交通管理者として対応するという形になっております。東京都としては、これまでの繰り返しになりますけれども、生活再建のための支援策が出てきた段階で説明に入りたいということを言ってあります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこにまちが形成され、そして周りとの関係を築き、生活しているわけですから、そこを全く離れる、追い出されることになるのが数千世帯という規模になっていくわけですから、それは私は地域の合意なしには進められない計画だと思うんです。そして、その人たちの暮らしそのものがどういうふうになっていくのかということも合わせて。","respondent":"藤田都市計画課長、片田都市環境事業部長","answer":"それから生活再建の支援策は、今現在、東京都が検討していますので、具体的な中身がお話しできないのはちょっと私も心苦しいんですけれども、そういう支援策は通常の都市計画道路の整備とは違って。現在そういう中で、いろいろな支援策という部分で、東京都としても今年の秋口、もう秋口に入ってきておりますけれども、できるだけ早く沿道の方への支援策というものを今、検討しているですので。","voiceIndex":22,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"延焼遮断帯ということをまず最優先に進めようということだと思うんですけれど、まちづくりというのは、そこに住んでいる人の合意によって進めなければ、本当のまちづくりというのはできないと思いますし、先ほど部長から、周辺のまちづくりも検討していくということですけれど、その周辺のまちづくりも含めて、道路も含めて、私はそのまちの皆さんが、本当にここに道路が必要だということになって初めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"沢田委員","kind":"意見","question":"今回、補助２８号線が追加ということですけれども、先ほど部長からもお話がありましたけれど、補助２９号線と放射２号線が、秋口に生活再建を含めたプランが出るというお話でしたけれども、１１月中ということかと思うんですけれども、その辺の変更はその後ないのかということと、今回、補助２８号線も追加になりまして、同様にこの秋口ということで同じように生活再建策が出たとき。","respondent":"藤田都市計画課長","answer":"この間いろいろ聞いている中で、秋口という話だったんですけれど、１０月、１１月、１２月が第３四半期ですので、そういう大きなくくりの中では変更にはなっていないと考えています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"沢田委員","kind":"確認","question":"前回のときもそうでしたけれど、建築確認をどうされるのかということとか、補助２９号線のときもあったかと思うんですけれども、今回の補助２８号線も、商店街のほうでいろいろ、これからのまちづくりということで考えられていた部分があったり、都とか区に助成を申請しようとしている段階だった事業等もあったんですけれども、そういったことに対して、区としてこの間。","respondent":"藤田都市計画課長","answer":"個別に何かまちの動き等があるようであれば、教えていただければ、また東京都のほうにもそういう情報を流しながら、対応できることがあるのかどうか、その辺については考えていきたいと思ってあります。","voiceIndex":28,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"先ほどの課長の話だと、東京都と一緒に連携をとってやるから、しっかりした話が来たら、そういう説明に行きますということだけれど、遮断帯にしますよということはもうできているんですから、少なくとも町会長とか商店会長というあたりには区として独自に、こういうことになります、そして今後は東京都がしっかりした数字を出したりした後、改めて地域の方々へ説明会を行いますというぐらいは。","respondent":"藤田都市計画課長","answer":"そういった決算特別委員会のときのお話も受けて、東京都の第二建設事務所のほうには、オール都庁としてはなかなか町場に対しての説明は、先ほど申した生活再建のための支援策がないと、というふうには話をしておりますけれども、一日でも早く説明ができるようにということで。","voiceIndex":30,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"ただ、そういう意味で、我々にもきちんとした情報が早く欲しいんですと。ですから、少なくとも東京都がこういう計画を立てていますという今わかっているあたりだけでも、私は重立った地域の責任者には、個別にお話をしていってあげるべきだと思うんですけれども、改めてもう一度。それをやっていると今言い出したんですけれど、きちんとできているかどうか。","respondent":"藤田都市計画課長","answer":"その中のワーキンググループの中で、第二建設事務所も入り、地域センターとかそういったところのメンバーも入れながら具体的な検討を進めて、少しでも不安を解消できるようなことを、これについては区のほうとして考えながら、今、進めているところです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"これは改めて要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の特定整備路線ということで、これが最後の追加分ということで伺っておりますけれども、今回追加されたこの路線ですけれども、これと似たような路線はほかにあるのか、例えば同じような環境下で、同じように危険度が高いような路線というのはほかにあるのかということと、今回、区のほうでは、じゃあ次はどこが来るのかなということで。","respondent":"藤田都市計画課長","answer":"東京都から、ここを指定しますというような形での説明があったというものです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"今お伺いしたのはまさにそこの部分で、あそこの先も密集しているという、いろいろな意見も、公明党の会派の中でも論議をしたところなので、一緒にやるというのはなかなか難しいかもしれないですけれども、やはりあそこまで道路が太くて、先がまた細いというんでしょうか、そういう大きな違いが出てきてしまうというのも、私も非常に気になるなと。","respondent":"山崎マスタープラン担当課長","answer":"今回の補助２８号線につきましては、地区別のほうでは大井地区に該当します。それで、急遽動きがありましたので、特定整備路線として指定されて、整備を推進していくというようなことを加筆したバージョンで、今後のパブリックコメントに対応してまいりたいと考えています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"浅野委員","kind":"意見","question":"これも結構長い期間、マスタープランというのは続くと思いますので、ぜひとも、都市計画審議会でもいろいろあったと思いますけれども、何とか入れられる方向でお願いしたいと思います。それと、さっきの南側のほうの説明会とかそういうことについて、答弁願いたいと思います。","respondent":"藤田都市計画課長","answer":"これも東京都の指標だという、別になってしまう答弁になりますけれども、東京都のほうと相談をしながら、逆に言うと、皆さんのところは指定しなくても安心なんですよというような形での説明が、必要になってくる場面があるかと思いますので。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうまつりの問題ですとか、町会の活動のやり方、また地域のきずな、そこら辺のところについて、区としてどう考えられているか。それが５分の１ぐらいにわたる町会に影響を与えるということについては。","respondent":"藤田都市計画課長","answer":"先ほど来、６路線と言われているものの中には、区のほうとしてこれから整備を進めていくということで、今すぐ着手するようなものでないものも含まれているかと思いますので、ちょっと先にその説明をします。","voiceIndex":41,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"両脇に二、三十メートルずつ高層化をしていくということになると、合わせて６０メートル、８０メートルということになるわけですから、そういう形で大きな道路と両脇の沿道の高層化ということになると、本当にまちが変貌してしまうので、きずなはそれでは壊されないだろうでは済まされないと思うんですね。私はそこら辺のところもしっかりと目を向けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"}]},{"id":"topic-02","title":"品川区まちづくりマスタープラン（素案）","agenda":"品川区まちづくりマスタープラン（素案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中身に入る前に、１０日に行われるまちづくり講演会なんですけれど、もう申し込みが、１２０人の定員が満杯になったというのをお聞きしたんですけれど、まだ参加したいという方は、若干それを超えても受け入れられるのかということを、ちょっとお聞かせいただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"先着ということで１２０名を募集にかけまして、ちょうど１２０名に今のところ少し欠けるぐらいで、まだ少し枠はありますけれども、そうした人数で推移しております。申し込まれても当日急遽ご都合ができてというようなこともありますので、柔軟にその辺は対応してまいりたいです。","voiceIndex":49,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回も欲しい方にはぜひ資料を提供してほしいということでお願いしたんですけれど、そこはなかなかできないというご答弁だったんですが、その場で例えば自分の地域の、これは地域ごとに分かれていますよね、で、荏原地区のところだけコピーしていただけないかとか、そういう要望にはぜひ応えていただけないかと思うんですが、そこら辺はぜひ柔軟にやっていただきたいと思うんですが。","respondent":"山崎マスタープラン担当課長","answer":"冊子のほうは非常に分厚いものですので、例えばまちづくり講演会のほうでは、概要をスライドなどを使って工夫して説明する予定で、そのスライドをコピーした資料編というか、そういうものを来場した方に配布する予定です。","voiceIndex":51,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"概要を配っていただけるというのは一歩前進で、よかったと思います。ただ概要だけでなく、自分の地域をもうちょっと詳しく知りたいということで、荏原地区とか大崎地区とか、それぞれの地域ごとに章立てになっているので、そこのところだけでもコピーしてもらいたいという要望には、ぜひ応えていただきたいと思うんですけれども、その点はいかがでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"メーンの問い合わせは都市計画課ですから、都市計画課に来ていただいていろいろやりとりをさせていただいて、お住まいの地区の今後のまちづくりを教えてほしいということで、先ほどご説明をしたメーンページ、あれ１枚で概要はわかるようになっていますので。","voiceIndex":53,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この決定というのは、都市計画審議会とかの機関で決定されるというのではなくて、策定委員会という、そこが決定機関になるということで確認をしていいでしょうか。そのことは後でお願いします。それと「防災性の向上等も勘案した周囲と調和したまちづくりを進めていく」、これは具体的にどういうことを考えられているのかということについて、まずお聞かせいただきたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"それで、もちろん都営住宅のほうと、東京都交通局の都バスなども敷地を使っておりまして、そうした意味では東京都の公共施設ということですので、このエリアとしてのポテンシャルの高さを活かした、誘導する考えを東京都のほうにいろいろ。","voiceIndex":55,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして続けてお聞かせいただきたいのが、２２９ページの５番の3)のところですが、「災害時の本部機能を補完する防災機能拠点の検討」ということで、「荏原地区での災害時の活動に即応し、迅速な情報収集や伝達、ボランティア活動の展開、支援物資等の受入・管理などの各機能を持った防災機能拠点の整備について、公共施設の建て替えなどにあわせ検討する」ということで書かれているんですが。","respondent":"大串住宅担当課長、山崎マスタープラン担当課長","answer":"都営住宅の配置といったものはあくまでも東京都のほうの考えですので、区のほうでなかなか、都にどういった形というのを申し上げるのは難しいかと考えています。そうした観点から、区役所を補完する機能を、例えば災害上いろいろな予測がされる荏原エリアに、ここに書かれているような区役所の本部機能を補完して、現地で災害時の活動に即応できるようなものが一定程度必要で。","voiceIndex":57,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都営住宅についてなんですけれど、たしか都営住宅は耐震化の目標って、平成２７年までに公共施設の耐震化をしていくという方針があると思うんですけれど、ここのところの耐震化の計画というのはどうなっているのか、ちょっと教えていただきたいのと、都営住宅は今までも大井林町と西大井と２カ所で１４２戸でしたか、既になくなって、本当にこれがあったらなと思うときもたくさんあるわけですけれど。","respondent":"山崎マスタープラン担当課長","answer":"それから道路の部分ですけれども、特定整備路線で整備を推進していくということで、補助２９号線については、先ほどの池上通りも含めまして、そうした整備を推進する柱になる道路に接道するというか、そういう部分については非常に防災上の効果が。","voiceIndex":60,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとその補助２７号線なんですが、これも木密の防災上の観点から、ほかの路線と同じような目的で整備をしていくという考え方なんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"「区役所の災害対策本部の機能を補完し、現地で災害時の活動に即応し、迅速な情報収集や伝達を行うとともに、ボランティア活動の展開、支援物資等の受入・管理および医療・福祉活動の実施といった各機能をもった防災機能拠点の整備について」、今。","voiceIndex":62,"id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"それがある中で、右の上のほうを見ますと、環境の中で「再生可能エネルギー設備の導入やエネルギーの面的利用の促進」と、言葉はこのように書いていますけれども、メガソーラーか何かかななんて思わず勘ぐってしまうんですけれども、まだ長期にわたっての３番の東京貨物ターミナルの展望かなというふうに思えるんですけれども、今、現状このようなものがある中で。","respondent":"山崎マスタープラン担当課長","answer":"いろいろ貨物の物流の中心網を担うエリアで、こちらのほうは２４１ページの３番のほうにも少し書いてありますけれども、東海道貨物支線の、人を乗せる貨客併用が、国の運輸政策審議会のほうでも検討を要すべき路線だということで。","voiceIndex":66,"id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"どうもありがとうあります。確かに何も考えていないと、何も考えていないじゃないかと言われることもあるかと思います。この時期ですので、可能かどうかは別といたしまして、最新情報を載せていただいたほうが、私はいいのではないかと思いまして、これは意見ですので、できる、できないというより、検討しなければならないことはあるかと思いますので、ぜひとも検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"このマスタープランの素案自体についてお伺いしたいんですけれど、前半のまちづくりの現状と課題に対しては、とても詳しくまとめていて、人口、土地利用などすごく詳しく上げていただいて、区民目線で見せていただくと、今の品川区の現状がよくわかると思うんですけれど、これを踏まえてのまちづくりの課題等に入っていきまして、整備が必要であるとか、効果的に進めていくとか。","respondent":"山崎マスタープラン担当課長","answer":"ちょっと手前みそですけれども、本編のほうがなかなか、最初から見るのはということであれば、先ほどの地区別方針の、品川地区にお住まいの方は、ご自分の住んでいるところがこの先どういう方針でまちづくりが進むんだろうということで、品川地区だけ見ていただくと。","voiceIndex":69,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば、今はわからない、完成予定がわからなかったり、またこれから外とのすり合わせとかあると思うんですよね。それがこれから先わかってきたり、または計画が進んでいくに当たって、このマスタープランに対してはどのように読みかえていくのか、そのことに関してはどのように周知を、区民の皆さんにしていくのかを教えていただきたいんですが。","respondent":"山崎マスタープラン担当課長","answer":"今後１０年あるいは２０年先を見据えたまちづくりの方向性ですので、例えば整備なり開発も時間とともに具体化していって、ということは当然想定しておりまして、このまちづくりの方針に則して、いろいろな計画が体系的につくられていくというような関係になっておりますので。","voiceIndex":71,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だからここは「自助・共助・公助の役割分担」ということだけが書かれているんですけれど、そこに災害対策基本法の精神をしっかりと明記をして、常にその立場で進めていただきたい。そういう意味からもそれを明記してほしいと思うんですけれど、いかがでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"あくまでもまちづくりマスタープランにつきましては、都市計画法に基づきまして区がいろいろ定めする、都市計画に関する基本的な方針という位置づけです。したがいまして、防災も含めたまちづくりに関する各分野を包括した、総合計画というような位置づけです。","voiceIndex":74,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自助・共助・公助ということは書いてあるわけですから、ぜひそういう立場でしていただくということで、その姿勢を明記していただきたいと、これは強く要望させていただきたいと思います。耐震化をして一撃から命を守り、そして燃えにくいまちをつくり、財産を守る、そういう耐震化というのがまず位置づけられることが重要なのではないかと思うんですけれど、そのお考えについてもいかがでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"素案の８４ページに、防災まちづくりの整備方針体系図ということでお示ししているものですが、まず課題として、品川区の抱えている地域特性、いわゆる木密地域における防災性向上のためには、課題が７つありますよということです。","voiceIndex":76,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひとも基本的な立場として生命、身体、財産を守るという、その姿勢を貫いていただきたいということからも、ここに明記をしていただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-033"}]},{"id":"topic-03","title":"の大崎駅周辺地域イベントの開催等","agenda":"の大崎駅周辺地域イベントの開催等","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"特別点灯ということでバレンタインの日にちとちょっとずれているんですけれど、どうしてでしょうか。","respondent":"溝口都市開発課長","answer":"本来、ご指摘のとおり２月１４日がバレンタインということですが、今回は平日ということなので、よりお客さんに来てもらうために、金曜日から土曜日、日曜日の３日間を点灯するということで考えております。","voiceIndex":84,"id":"exchange-034"}]},{"id":"topic-04","title":"環境経営セミナーの開催","agenda":"環境経営セミナーの開催","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"講師の方は、今回はクール・ネット東京からの派遣ということで、第二部に出ているんですけれど、第一部と第三部の講師、助言者、この方についてはやはりクール・ネット東京からの派遣というんでしょうか、そういうルートで来られるのかどうかということ。","respondent":"野呂瀬環境課長","answer":"延長したとしても期間が近々ですので、集まらなくても今現在の約６０事業所で、開催は考えております。２点目の派遣の形式ですけれど、これは基本的には私どものほうで、クール・ネット東京からの派遣でなくて、私どものほうでお願いをして来ていただくという経緯です。","voiceIndex":91,"id":"exchange-035"},{"speaker":"沢田委員","kind":"質問","question":"この環境経営セミナーですけれども、区がやっている環境ＩＳＯの助成事業とか、エコアクション２１とか、そういう助成事業との関係というか関連は、どういったことがあるんでしょうか。","respondent":"野呂瀬環境課長","answer":"ＩＳＯとかエコアクション２１というのは、その事業者一つに対してのものですが、全体的に区の事業者に集まっていただいて、情報交換を含めてですけれども、事業者といってもいわゆる小売業とか運送業、いろいろありますので、そういう中で集まっていただいて。","voiceIndex":94,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５番目の参加案内を送付された３カ所というのは、それぞれ何点ぐらいずつあったのか教えてください。","respondent":"野呂瀬環境課長","answer":"それとエコパワーカンパニー取得事業所というのは、現在５０事業所程度、５１か５２ぐらいですので、もちろんその中で今言った昨年、一昨年参加のダブっているところはありますけれども、大体５０事業所ぐらいです。","voiceIndex":96,"id":"exchange-037"}]},{"id":"topic-05","title":"の（仮称）鮫洲入江埋立公園整備工事","agenda":"の（仮称）鮫洲入江埋立公園整備工事","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"こちらの公園ですけれども、犬を連れていってもいいというような話もちょっと伺っているんですけれど、そのとおりなのかということと、どのような利用を考えられているのか、また犬を入れることによって苦情とかそういうのが出てくる可能性もあるんですけれども、その辺をどうお考えになっているのかということを一点お伺いします。","respondent":"多並公園課長","answer":"ただ、説明会等でもいろいろ皆様のご意見をいただきまして、今後利用の状況により、いわゆるマナーがなかなか守られず、ほかの利用者の方に迷惑がかかるようなことがあった場合には、またいろいろ地域の皆様とご相談しながら、場合によったら入れないような形とか。","voiceIndex":105,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"大崎駅西口中地区の例が挙げられていますけれども、ここの地権者はたしか８０何世帯だったと思うんですけれど、その中でこのマンションに入られた方というのは何％ぐらいになったのかということと、こういうふうに新たなまちをつくるとなると、建物の耐震だけでなく、上下水道の耐震化とかもできているのかなと思うんですけれど、となると、巨大地震が来てもこういうところは断水とか。","respondent":"溝口都市開発課長","answer":"権利者数につきましては８８名で、すみません、ちょっと詳しい数字がありませんけれど、ほとんどの権利者の方はそのままマンション等施設に、権利変換で入っているというふうに聞いております。","voiceIndex":113,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、多分、水道というのはいろいろなところから確保できるという、いろいろな整備になっているというふうには聞いたんですけれど、ここの地域が断水するかどうか、そういうことはわからないでしょうか。大崎の向こう側の開発もあると思うんですけれど、そこら辺の上下水道の耐震化の技術的な部分がどうなっているのかということを、教えていただけたらと思います。","respondent":"溝口都市開発課長","answer":"ただ、それは自分で探したのかどうかということは、ケースにもよるとは思いますが、組合のほうで用意したとか、自分でいい物件を見つけてそちらに移った、そういったようなものがあったと考えております。","voiceIndex":115,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"このマンションは３９階建てでしたっけ、かなりの超高層だと思うんですが、長周期地震動に対しての対策というのはどのようにとられていたのか。それと昨年の３・１１でも、揺れというのはどうだったのか、把握されていたらお聞かせください。","respondent":"溝口都市開発課長","answer":"３・１１のとき、住んでいる方に聞きますと、揺れはしているようですけれども、物が落ちたとかそういったことは特にないというふうに、私のほうは聞いているところです。","voiceIndex":117,"id":"exchange-041"},{"speaker":"須藤委員","kind":"質問","question":"それから反対運動がいろいろあったとき、どの程度丁寧に説明をされて、その苦労がどうだったのかということも教えてください。","respondent":"溝口都市開発課長","answer":"反対者に対する苦労等ですけれど、その後、組合設立等に当たりまして、反対の地権者に対しては区のほうでもかなり前面に立って、よく事業の内容、効果、そういったものを説明していく中で、そういった形で、説得というのは進めてきたようです。","voiceIndex":119,"id":"exchange-042"},{"speaker":"須藤委員","kind":"意見","question":"今日の新聞か何かに載っていたけれど、８割のメンバーが賛成すれば、地震のときに倒壊しそうなマンションを壊すことができるみたいな法改正になるというような話になってきているので、やはり全体を見ていった場合、一部の妨害でなかなかそれが進まないというようなことは、区民全体から見ても大きなマイナスになってくると思うので、そのあたりはやはり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"２点質問がありまして申しわけないんですけれど、建てる前と建った後、時期にもよりますけれども、この地域の人口というんですか、居住者の人数というのはどのぐらい変化があったのかお伺いしたいのと、あと今ちょっと触れられていましたけれども、こういうビルが建つと、町会、自治会などのコミュニティーが崩れるというような意見も出ているかと思いますけれども、実際どのような現状なのか。","respondent":"溝口都市開発課長","answer":"中地区だけのデータというのがちょっと今手元にないんですけれど、大崎地域全体でいいますと、昭和６０年で約５,０００人だったものが、平成２３年今回の中地区完成後ですけれど、約８,０００人、ですから約３,０００人ほど人口が伸びているという状況です。","voiceIndex":122,"id":"exchange-044"},{"speaker":"浅野委員","kind":"意見","question":"人口もこのエリア全体で３,０００人プラスということで、品川区の人口増にもある意味ではいい影響を与えているのかなと、保育園とかいろいろな問題はありますけれども、人口が減るよりは少しずつでも増えていったほうが、まちとしての活性化、また品川区の活性化につながると考えています。","respondent":"溝口都市開発課長","answer":"人口ですけれど、改めさせていただきまして、大崎の昭和６０年の人口としましては約１万２,０００人、平成２３年度には１万６,０００人、ですから大体４,０００人程度の人口増があったという形の統計データが出ております。申しわけありませんでした。","voiceIndex":124,"id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"このマンションというか建物は２棟建ったんですよね。それで、これは高層ビルですから、高さがどれぐらいあるのか。それと、近隣の住宅とか商店街に何か悪影響が出ていないかどうか。よく鈴木委員が言いますけれど、風害と言うんですか、そういうものは出ているかどうか。あれば教えてください。","respondent":"溝口都市開発課長","answer":"風環境についてですけれど、これまでも再開発事業を説明していく中で、当然計画段階での検証等を行って進めてきておりますので、特に風害が起きているとか、そういったことは私どもの耳には入っていません。","voiceIndex":130,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その後、本計画になっていきますけれども、それに向けて震災対策特別委員会のほうでは、今まで話し合ってきた中身を、そこの中に反映させようということでのまとめを出していこうということで、震災対策特別委員会のほうではやっているんですけれども、そういうことであれば、地域防災計画の中に占める耐震化というのは、やはり大きな、一番と思うんですけれど、この委員会として耐震化についての。","respondent":"稲川委員長","answer":"ご意見として承りながら、正副でそれは判断させていただいて、私どもの所管事務調査のスケジュールとしては、最終の閉会中の委員会が２回ありますので、その中である程度の着地点は生み出していかなければいけないという思いでは進めておりますので。","voiceIndex":132,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"建設委員会の中で耐震化をやるということだったので、震災対策特別委員会の中では耐震化のことは外して、それ以外のところということで進められてきましたので、耐震化についてはこの建設委員会で。反映させていくようなまとめをするとしたら、この委員会しかないかなと思いますので。","respondent":"稲川委員長","answer":"そのまとめも含めて、ご意見としていただいて、正副で協議しますので。","voiceIndex":135,"id":"exchange-048"},{"speaker":"須藤委員","kind":"質問","question":"これは早くわかって、早く判断してくれたと思うんですけれど、実際に５,０００平方メートル以上で、申し込みというのは現実的にあったんですか。そのことに対して、今までのは違っていたので助成額がこう変わりますよという話も、説明せざるを得なくなりますよね。そのあたりの対応はどうしたのか。","respondent":"品川防災整備担当課長","answer":"実際に改修、除却等について、現在のところ申し込みをされたところはございません。ただ事前に相談という形で１件来ておりまして、その方については、今後丁重にこのことを説明しながら、進めていきたいと考えています。","voiceIndex":148,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":54113,"voices":152}}]);
